export const LEGAL_PACK = {"levels": ["basico", "substancial", "elevado"], "controls": {"GR.CO-1": {"objective": "GR — Gerir", "category": "GR.CO — Contexto Organizacional", "statement": "A missão, visão, estratégia de gestão dos riscos e objetivos da entidade são definidos e comunicados.", "description": "A missão, visão, valores, estratégias de gestão dos riscos e objetivos são os princípios fundamentais de orientação de uma entidade. Estes princípios indicam a forma como a entidade se posiciona no seu setor de atividade e como procura ser reconhecida pelo pessoal, clientes, fornecedores e outras entidades terceiras.", "measures": {"substancial": {"measure": "A missão, visão, estratégia de gestão dos riscos e objetivos da entidade devem ser definidas, comunicadas e priorizadas. A entidade deve, inclusive, definir as prioridades em matéria de cibersegurança.", "verification": "Registo documentado da missão, visão, estratégia de gestão do risco e objetivos no âmbito da cibersegurança e respetivas prioridades."}}}, "GR.CO-2": {"objective": "GR — Gerir", "category": "GR.CO — Contexto Organizacional", "statement": "As necessidades e expectativas das partes interessadas internas e externas são compreendidas e encontram-se refletidas na gestão dos riscos de cibersegurança da entidade.", "description": "A entidade identifica as partes interessadas internas e externas relevantes e ausculta as suas necessidades e expectativas no contexto de cibersegurança, refletindo-as na sua estratégia de gestão dos riscos de cibersegurança.", "measures": {}}, "GR.CO-3": {"objective": "GR — Gerir", "category": "GR.CO — Contexto Organizacional", "statement": "Os requisitos legais, regulamentares e contratuais para a cibersegurança, são compreendidos e geridos.", "description": "A entidade garante que cumpre com a legislação e regulamentação de cibersegurança nacional e europeia em vigor. Para esse efeito, a entidade define quais são os requisitos legais, regulamentares e contratuais nacionais e europeus que necessitam de ser observados e seguidos.", "measures": {"basico": {"measure": "Os requisitos legais e regulamentares relativos à cibersegurança devem ser identificados e aplicados.", "verification": "Evidência da gestão quotidiana da entidade que demonstre o cumprimento dos requisitos e obrigações legais de cibersegurança aplicáveis à entidade."}}}, "GR.CO-4": {"objective": "GR — Gerir", "category": "GR.CO — Contexto Organizacional", "statement": "Os serviços críticos da entidade dos quais as partes interessadas externas dependem são identificados e comunicados.", "description": "A entidade identifica os seus serviços críticos, dos quais as partes interessadas externas dependem, e utiliza esta informação, integrando-a e gerindo-a no seu processo de gestão dos riscos. Ao integrar a informação na gestão dos riscos, a entidade classifica e prioriza os serviços críticos identificados. A entidade comunica esta identificação às partes interessadas externas.", "measures": {"basico": {"measure": "Devem ser identificados e documentados os serviços críticos, dos quais as partes interessadas externas dependem.", "verification": "Registo documentado da identificação dos serviços críticos dos quais as partes interessadas externas dependem."}, "substancial": {"measure": "Os serviços críticos da entidade, dos quais as partes interessadas dependem, devem ser classificados, priorizados e integrados no processo de gestão dos riscos.", "verification": "Registo do processo de gestão dos riscos que contempla os serviços críticos das quais as partes interessadas externas dependem, incluindo a definição de critérios para a classificação e priorização dos serviços críticos."}}}, "GR.CO-5": {"objective": "GR — Gerir", "category": "GR.CO — Contexto Organizacional", "statement": "Os requisitos de resiliência necessários para suportar a prestação de serviços críticos são definidos.", "description": "A entidade identifica e define quais são os requisitos de resiliência adequados para suportar a prestação dos seus serviços críticos. A entidade define e implementa um Plano de Continuidade de Negócio que contém disposições quanto a redundâncias, planos e tempos de resposta para a recuperação dos serviços críticos e respetivos processos. De maneira a garantir que o Plano de Continuidade de Negócio responde às necessidades a entidade realiza testes ao mesmo.", "measures": {"basico": {"measure": "Os requisitos necessários para garantir o suporte de serviços críticos devem ser identificados e registados.", "verification": "Registo documentando da identificação dos requisitos de resiliência necessários para garantir o suporte dos serviços críticos."}, "substancial": {"measure": "A entidade deve implementar mecanismos de redundância para garantir a disponibilidade dos serviços críticos. A entidade deve definir, aprovar e implementar um Plano de Continuidade de Negócio contendo planos e tempos de resposta para a recuperação dos serviços críticos e respetivos processos.", "verification": "Evidencia técnica da implementação de mecanismos de redundância que garantam a disponibilidade dos serviços críticos. Plano de Continuidade de Negócio aprovado e implementado e que contenha a definição dos tempos necessários para a recuperação de cada serviço critico e respetivos processos."}, "elevado": {"measure": "O Plano de Continuidade de Negócios deve ser testado.", "verification": "Evidência da execução de testes ao Plano de Continuidade de Negócio."}}}, "GR.CO-6": {"objective": "GR — Gerir", "category": "GR.CO — Contexto Organizacional", "statement": "Os serviços externos dos quais a entidade depende, são identificados e comunicados.", "description": "A entidade identifica as dependências externas que, em caso de falha, podem afetar as suas operações e serviços críticos, e partilha esta informação com as partes interessadas. A entidade identifica qual o seu papel na cadeia de abastecimento.", "measures": {"basico": {"measure": "Devem ser identificados, documentados, classificados e priorizados os serviços críticos externos dos quais a entidade depende, numa lógica de compreensão do seu papel na cadeia de abastecimento. A entidade deve comunicar às partes interessadas esta identificação, respeitando sempre o princípio da necessidade de saber. A entidade deve incluir no processo de gestão dos riscos esta identificação.", "verification": "Registo da identificação, e da comunicação dos serviços críticos externos dos quais a entidade depende. Registo do processo de gestão dos riscos que contempla os serviços críticos externos dos quais a entidade depende, incluindo a definição de critérios para a classificação e priorização destes serviços."}}}, "GR.GR-1": {"objective": "GR — Gerir", "category": "GR.GR — Estratégia de Gestão do Risco", "statement": "O apetite e a tolerância ao risco da entidade são definidos, aprovados, comunicados e revistos regularmente.", "description": "A entidade define, aprova, comunica e atualiza o nível de risco que está disposta a aceitar por forma a permitir aferir as expectativas sobre o seu nível de risco tolerável. O apetite ao risco considera o contexto organizacional e o setor no qual a entidade se insere.", "measures": {"substancial": {"measure": "A entidade deve definir, registar, aprovar, rever regularmente e comunicar internamente, o seu apetite e tolerância ao risco.", "verification": "Registo documentado e aprovado da definição do apetite e tolerância ao risco. Registo da sua comunicação às partes interessadas internas."}}}, "GR.GR-2": {"objective": "GR — Gerir", "category": "GR.GR — Estratégia de Gestão do Risco", "statement": "Os processos de gestão dos riscos de cibersegurança estão incluídos na estratégia transversal de gestão dos riscos da entidade.", "description": "A entidade garante que os seus processos da gestão dos riscos se encontram devidamente definidos, aprovados e geridos. É assegurado que os processos de gestão dos riscos de cibersegurança são consistentes e transversais à entidade, e à sua estratégia de gestão do risco. Isto é, os processos de gestão dos riscos de cibersegurança são tidos em conta na gestão dos restantes riscos da entidade, e são devidamente acompanhados pelos órgãos de gestão, administração e direção, tal como os restantes riscos.", "measures": {"basico": {"measure": "A entidade deve identificar, aprovar, gerir e manter atualizados os processos de gestão dos riscos de cibersegurança.", "verification": "Evidência da gestão quotidiana que demonstre a implementação das várias fases de gestão de riscos da cibersegurança."}, "substancial": {"measure": "A entidade deve garantir que os seus processos de gestão dos riscos de cibersegurança estão incluídos na estratégia transversal da gestão dos riscos da entidade.", "verification": "Evidência de gestão quotidiana que demonstre a implementação das várias fases de gestão de risco da cibersegurança nos processos transversais de gestão dos riscos da entidade."}}}, "GR.GR-3": {"objective": "GR — Gerir", "category": "GR.GR — Estratégia de Gestão do Risco", "statement": "A entidade define a sua estratégia de tratamento do risco.", "description": "A entidade define a resposta de tratamento do risco a aplica-a aos seus ativos, tendo em conta a sua tolerância ao risco.", "measures": {"substancial": {"measure": "A entidade deve definir e comunicar às partes interessadas a sua estratégia de tratamento do risco, respeitando sempre o princípio da necessidade de saber.", "verification": "Registo documentado da estratégia de tratamento do risco e da sua comunicação às partes interessadas."}}}, "GR.GR-4": {"objective": "GR — Gerir", "category": "GR.GR — Estratégia de Gestão do Risco", "statement": "A entidade estabelece um canal de comunicação interno para partilha de riscos de cibersegurança.", "description": "A entidade determina e usa regularmente um canal interno a utilizar para comunicar os riscos de cibersegurança aos órgãos de gestão, direção e administração e às restantes áreas relevantes da entidade.", "measures": {"substancial": {"measure": "A entidade deve estabelecer um canal de comunicação interno, para partilha de informação sobre os riscos de cibersegurança, com os órgãos de gestão, direção e administração e restantes áreas relevantes.", "verification": "Canal interno de comunicação usado para a partilha de riscos de cibersegurança."}}}, "GR.GR-5": {"objective": "GR — Gerir", "category": "GR.GR — Estratégia de Gestão do Risco", "statement": "A entidade define uma Política de Gestão dos Riscos de Cibersegurança a qual prevê uma metodologia para a gestão dos riscos de cibersegurança.", "description": "A entidade define, comunica, atualiza e revê, uma Política de Gestão dos Riscos de Cibersegurança por forma a refletir alterações nos requisitos legais e regulamentares, nas ameaças, em novas tecnologias, e na missão organizacional. Esta Política inclui a metodologia para calcular, registar, categorizar e dar prioridade aos riscos de cibersegurança da entidade.", "measures": {"substancial": {"measure": "A entidade define uma metodologia para a gestão dos riscos de cibersegurança que permita identificar, registar, calcular, categorizar e priorizar os riscos de cibersegurança.", "verification": "Registo da metodologia de gestão dos riscos de cibersegurança."}, "elevado": {"measure": "A entidade define, aprova e implementa uma Política de Gestão dos Riscos de Cibersegurança.", "verification": "Política de Gestão dos Riscos de Cibersegurança aprovada e implementada."}}}, "GR.FR-1": {"objective": "GR — Gerir", "category": "GR.FR — Funções, Responsabilidades e Autoridades", "statement": "Os órgãos de gestão, direção e administração compreendem as suas funções e responsabilidades, e promovem uma cultura de cibersegurança, ética e de melhoria contínua.", "description": "Os órgãos de gestão, direção e administração demonstram estar comprometidos com a temática da cibersegurança, promovendo uma cultura de cibersegurança. Estes órgãos compreendem qual é o seu papel e responsabilidade na cibersegurança.", "measures": {"basico": {"measure": "Os órgãos de gestão, direção e administração devem disponibilizar os recursos necessários para a melhoria contínua da cibersegurança.", "verification": "Plano de Melhoria Contínua de Cibersegurança com medidas, prazos e recursos a afetar, aprovado pelos órgãos de gestão, direção e administração."}}}, "GR.FR-2": {"objective": "GR — Gerir", "category": "GR.FR — Funções, Responsabilidades e Autoridades", "statement": "São atribuídos recursos adequados e proporcionais à estratégia de gestão do risco de cibersegurança, às funções, responsabilidades e políticas de cibersegurança da entidade.", "description": "A entidade garante que são atribuídos recursos adequados e proporcionais à estratégia de risco de cibersegurança, às funções, responsabilidades e políticas da mesma.", "measures": {"substancial": {"measure": "A entidade deve alocar recursos suficientes e proporcionais à gestão do risco de cibersegurança, às funções, responsabilidades e políticas da entidade.", "verification": "Registo do planeamento das atividades em matéria de cibersegurança a curto ou médio prazo, e evidência da gestão quotidiana que demonstre a alocação dos recursos para a gestão do risco de cibersegurança."}}}, "GR.FR-3": {"objective": "GR — Gerir", "category": "GR.FR — Funções, Responsabilidades e Autoridades", "statement": "As funções, responsabilidades e autoridades em matéria de cibersegurança são definidas e comunicadas ao pessoal, fornecedores e partes interessadas.", "description": "As funções, responsabilidades e autoridades de cibersegurança dentro da entidade são documentadas,, aprovadas, alinhadas com as funções internas da entidade e partes interessadas externas e atualizadas. O estabelecido deve ser comunicado ao pessoal, fornecedores e outras partes interessadas.", "measures": {"substancial": {"measure": "As funções, responsabilidades e autoridades de cibersegurança dentro da entidade devem ser documentadas, aprovadas, comunicadas, alinhadas com as funções internas e entidades externas, e atualizadas.", "verification": "Registo documentado e aprovado das funções, responsabilidades e autoridades e da sua comunicação às partes interessadas."}}}, "GR.FR-4": {"objective": "GR — Gerir", "category": "GR.FR — Funções, Responsabilidades e Autoridades", "statement": "A cibersegurança é contemplada nos processos de gestão de recursos humanos.", "description": "Os processos organizacionais que gerem os recursos humanos, que incluem a seleção de candidatos, contratação, categorização das posições e a cessação de vínculo laboral, são avaliados e revistos com base nos requisitos de cibersegurança estabelecidos pela entidade.", "measures": {"basico": {"measure": "A entidade deve definir uma Política de Uso Aceitável, que seja abrangente para toda a entidade e que defina as regras para a utilização segura e responsável dos seus ativos. A entidade deve disponibilizar a Política de Uso Aceitável ao pessoal aquando da sua entrada, sensibilizando-os para garantir o cumprimento da mesma.", "verification": "Política de Uso Aceitável aprovada e implementada e registo da tomada de conhecimento pelo pessoal aquando da sua entrada."}, "substancial": {"measure": "A entidade deve desenvolver e manter medidas de cibersegurança associadas à gestão dos recursos humanos, aplicável no recrutamento, durante o contrato e após o seu término.", "verification": "Registo das medidas de cibersegurança para a gestão de recursos humanos, desde a entrada até à saída do pessoal."}}}, "GR.PP-1": {"objective": "GR — Gerir", "category": "GR.PP — Políticas e Planos de Cibersegurança", "statement": "As Políticas para a gestão de Cibersegurança, incluindo a Política de Cibersegurança, são definidas com base no contexto organizacional, na estratégia de cibersegurança e nas prioridades da entidade.", "description": "A entidade define e aprova superiormente a sua Política de Cibersegurança e garante o compromisso dos órgãos de gestão, direção e administração com a Política. A entidade comunica às partes interessadas a existência da Política de Cibersegurança. A entidade desenvolve, e identifica na Política de Cibersegurança as várias políticas que compõem o seu processo da gestão da cibersegurança, e que poderão ser nomeadamente: a) Política de Gestão dos Riscos de Cibersegurança; b) Política de Gestão do Risco da Cadeia de Abastecimento; c) Política de Gestão do Ciclo de Vida de Ativos; d) Política de Classificação e Gestão de Dados; e) Política de Monitorização, Identificação e Documentação das Vulnerabilidades; f) Política de Palavra-Passe; g) Política de Gestão de Identidades, Autenticação e Controlo de Acessos; h) Política de Uso Aceitável; i) Política de Cópias de Segurança.", "measures": {"basico": {"measure": "A entidade deve definir, documentar e atualizar a Política de Cibersegurança aprovada pelos órgãos de gestão, direção e administração, que inclua a identificação e atribuição de funções e responsabilidades em cibersegurança. A entidade deve divulgar a política internamente.", "verification": "Política de Cibersegurança, aprovada pelos órgãos de gestão, direção e administração. Registos da comunicação interna da Política de Cibersegurança."}, "substancial": {"measure": "A entidade deve definir, aprovar e implementar uma Política de Classificação e Gestão de Dados.", "verification": "Política de Classificação e Gestão de Dados aprovada e implementada."}}}, "GR.PP-2": {"objective": "GR — Gerir", "category": "GR.PP — Políticas e Planos de Cibersegurança", "statement": "O Plano de Resposta a Incidentes é definido, comunicado, mantido e melhorado.", "description": "O Plano de Reposta a Incidentes é definido, implementado e atualizado com frequência, com vista à sua melhoria. A entidade garante que as partes interessadas relevantes, internas e externas, têm o conhecimento apropriado de todas as atualizações efetuadas.", "measures": {"basico": {"measure": "A entidade deve definir, aprovar, implementar e atualizar o Plano de Resposta a Incidentes com a devida atribuição e identificação de funções e responsabilidades.", "verification": "Plano de Resposta a Incidentes aprovado e implementado e devidamente atualizado."}}}, "GR.PP-3": {"objective": "GR — Gerir", "category": "GR.PP — Políticas e Planos de Cibersegurança", "statement": "O Plano de Recuperação de Desastres é definido, comunicado, mantido e melhorado.", "description": "O Plano de Recuperação de Desastres é definido, implementado e atualizado com frequência, com vista à sua melhoria. A entidade garante que as partes interessadas relevantes, internas e externas, têm o conhecimento apropriado de todas as atualizações efetuadas.", "measures": {"substancial": {"measure": "A entidade deve definir, aprovar, implementar e atualizar o Plano de Recuperação de Desastres com a devida atribuição e identificação de funções e responsabilidades.", "verification": "Plano de Recuperação de Desastres aprovado implementado, e devidamente atualizado."}}}, "GR.SP-1": {"objective": "GR — Gerir", "category": "GR.SP — Supervisão", "statement": "Os resultados da estratégia de gestão dos riscos de cibersegurança são analisados para informar os órgãos de gestão, direção e administração e, caso necessário, para adaptar a estratégia da entidade quanto aos riscos.", "description": "Os responsáveis pela análise de atividades e desempenho da estratégia de gestão dos riscos de cibersegurança informam os órgãos de gestão, direção e administração e, quando necessário, adaptam a estratégia de acordo com os resultados obtidos, considerando possíveis limitações no normal funcionamento operacional da entidade, no orçamento e em processos de inovação, entre outros.", "measures": {}}, "GR.SP-2": {"objective": "GR — Gerir", "category": "GR.SP — Supervisão", "statement": "A estratégia de gestão de riscos de cibersegurança é regularmente revista e adaptada para garantir a cobertura dos requisitos e riscos organizacionais.", "description": "A entidade revê regularmente a estratégia de gestão dos riscos de cibersegurança para incorporar requisitos e riscos organizacionais que sejam identificados através de análises de auditorias, de incidentes e do desempenho das funções de cibersegurança.", "measures": {"elevado": {"measure": "A estratégia de gestão dos riscos de cibersegurança deve ser revista regularmente e adaptada para garantir a cobertura dos requisitos e riscos organizacionais.", "verification": "Evidência de que a entidade tem atualizado o quadro de ameaças e que revê e adapta a estratégia de gestão dos riscos em conformidade."}}}, "GR.SP-3": {"objective": "GR — Gerir", "category": "GR.SP — Supervisão", "statement": "O desempenho da gestão dos riscos de cibersegurança da entidade é avaliado e revisto para alterações necessárias.", "description": "A entidade avalia e revê o seu desempenho da gestão dos riscos de cibersegurança, através da implementação de mecanismos de avaliação e monitorização de desempenho, para garantir que alterações são consideradas e aplicadas quando necessário.", "measures": {"elevado": {"measure": "Devem ser definidos e implementados mecanismos de avaliação do desempenho da gestão dos riscos de cibersegurança.", "verification": "Registo da definição de mecanismos para avaliar o desempenho da gestão dos riscos de cibersegurança."}}}, "GR.CA-1": {"objective": "GR — Gerir", "category": "GR.CA — Gestão do Risco na Cadeia de Abastecimento", "statement": "As políticas e processos de gestão dos riscos da cadeia de abastecimento são identificados, estabelecidos, avaliados e geridos.", "description": "A entidade identifica e implementa processos e procedimentos para gerir os riscos de segurança associados à utilização de produtos e serviços fornecidos por terceiros, incluindo serviços de computação em nuvem. Estes procedimentos incluem as obrigações da própria entidade e as obrigações dos fornecedores para o início ou término da utilização dos produtos e serviços fornecidos por terceiros.", "measures": {"elevado": {"measure": "A entidade deve definir, aprovar, implementar, rever e atualizar a Política de Gestão de Riscos da Cadeia de Abastecimento e o respetivo procedimento.", "verification": "Política e procedimento de Gestão de Riscos da Cadeia de Abastecimento aprovados, implementados e atualizados."}}}, "GR.CA-2": {"objective": "GR — Gerir", "category": "GR.CA — Gestão do Risco na Cadeia de Abastecimento", "statement": "Os papéis e responsabilidades dos parceiros, fornecedores e clientes no âmbito da gestão da cibersegurança são definidos, comunicados e coordenados interna e externamente.", "description": "A entidade define, coordena e comunica os papéis e responsabilidades no âmbito do sistema de gestão de cibersegurança das partes interessadas externas relevantes para a entidade, sendo este entendimento essencial para aumentar o nível de cibersegurança da entidade. A entidade comunica e efetua ações de sensibilização para garantir que o entendimento das partes interessadas sobre este tema é o adequado e necessário.", "measures": {}}, "GR.CA-3": {"objective": "GR — Gerir", "category": "GR.CA — Gestão do Risco na Cadeia de Abastecimento", "statement": "Os processos de gestão dos riscos de cibersegurança da cadeia de abastecimento da entidade estão incluídos nos processos transversais de cibersegurança e na estratégia de gestão dos riscos da entidade.", "description": "A entidade inclui os riscos associados à sua cadeia de abastecimento, incluindo fornecedores, prestadores de serviços e parceiros tecnológicos e, de forma sistemática, identifica, avalia, gere e monitoriza estes riscos. A entidade garante o alinhamento da gestão de riscos da cadeia de abastecimento com a gestão de riscos de cibersegurança e risco global da entidade. Esta gestão do risco de cibersegurança da cadeia de abastecimento deve garantir a resiliência da entidade face a potenciais incidentes com origem nos seus fornecedores, parceiros, prestadores de serviços e outros.", "measures": {"substancial": {"measure": "A entidade deve identificar, aprovar, gerir e manter atualizados, sempre que ocorram alterações, os riscos de cibersegurança associados à cadeia de abastecimento. A entidade deve incluir os processos de gestão dos riscos de cibersegurança da cadeia de abastecimento nos seus processos transversais de cibersegurança e de gestão dos riscos da entidade.", "verification": "Registo documentado da identificação, aprovação, gestão e atualização dos riscos de cibersegurança associados à cadeia de abastecimento."}}}, "GR.CA-4": {"objective": "GR — Gerir", "category": "GR.CA — Gestão do Risco na Cadeia de Abastecimento", "statement": "Os fornecedores são periodicamente avaliados.", "description": "A entidade define o processo de gestão de fornecedores na cadeia de abastecimento de acordo com as prestações contratualizadas com os mesmos.", "measures": {}}, "GR.CA-5": {"objective": "GR — Gerir", "category": "GR.CA — Gestão do Risco na Cadeia de Abastecimento", "statement": "A entidade define e integra nos contratos e outros acordos com fornecedores os requisitos para gerir os riscos de cibersegurança da cadeia de abastecimento.", "description": "A entidade garante que os seus fornecedores cumprem com os requisitos de cibersegurança estabelecidos no quadro contratual. Os contratos e outros acordos com fornecedores são utilizados para implementar medidas adequadas, de modo a garantir o cumprimento dos objetivos da Política de Cibersegurança da entidade e da Política de Gestão dos Riscos para a Cadeia de Abastecimento.", "measures": {"substancial": {"measure": "A entidade deve definir e integrar requisitos de cibersegurança e os meios de partilha de informação sensível nos contratos e outros acordos a definir com fornecedores.", "verification": "Modelos de contratos/acordos contendo cláusulas específicas de requisitos de cibersegurança."}, "elevado": {"measure": "Os contratos e outros acordos com fornecedores devem integrar disposições legais que permitam a avaliação contínua da cibersegurança dos fornecedores e a correção de eventuais falhas identificadas.", "verification": "Modelos de contratos/acordos contendo cláusulas específicas que permitam a avaliação contínua da cibersegurança dos fornecedores e a correção de eventuais falhas identificadas."}}}, "GR.CA-6": {"objective": "GR — Gerir", "category": "GR.CA — Gestão do Risco na Cadeia de Abastecimento", "statement": "Antes da contratação de fornecedores são realizados processos de devida diligência para reduzir os riscos da entidade.", "description": "A entidade planeia e conduz processos de devida diligência antes de formalizar uma relação, contratação ou aquisição de serviço com um fornecedor, com o objetivo de minimizar a exposição ao risco.", "measures": {"elevado": {"measure": "A entidade deve, antes de estabelecer relações contratuais com fornecedores, conduzir, sempre que possível, processos de devida diligência, com o objetivo de minimizar a sua exposição ao risco.", "verification": "Registo dos processos de devida diligência realizados antes da contratação."}}}, "GR.CA-7": {"objective": "GR — Gerir", "category": "GR.CA — Gestão do Risco na Cadeia de Abastecimento", "statement": "A entidade avalia os riscos de cibersegurança da cadeia de abastecimento.", "description": "Os fornecedores de redes e sistemas de informação, componentes e serviços de cibersegurança são identificados, priorizados e avaliados, recorrendo a um processo de avaliação do risco da cadeia de abastecimento de cibersegurança. A entidade, após a identificação dos fornecedores, categoriza-os considerando: 1) A exposição da sua informação aos mesmos; 2) O impacto na cadeia de abastecimento; 3) O tipo de bens e serviços fornecidos.", "measures": {"basico": {"measure": "A entidade deve efetuar avaliações do risco da cadeia de abastecimento pelo menos uma vez por ano ou sempre que relevante.", "verification": "Registo documentado das avaliações do risco da cadeia de abastecimento."}, "substancial": {"measure": "A entidade deve mitigar os riscos identificados durante o processo de avaliação do risco da cadeia de abastecimento.", "verification": "Registo das medidas de mitigação aplicadas face aos riscos identificados durante o processo de avaliação do risco da cadeia de abastecimento."}, "elevado": {"measure": "A entidade deve realizar avaliações da cibersegurança dos seus fornecedores em conformidade com o nível de exigência requerido.", "verification": "Registo da avaliação de cibersegurança dos fornecedores em conformidade com o nível de exigência requerido, nomeadamente: Certificados válidos no âmbito do Selo de Maturidade Digital; Relatórios de auditorias realizadas; Resultados de testes realizados no âmbito da cibersegurança."}}}, "GR.CA-8": {"objective": "GR — Gerir", "category": "GR.CA — Gestão do Risco na Cadeia de Abastecimento", "statement": "O Plano de Resposta a Incidentes e o Plano de Recuperação de Desastres são testados com o acompanhamento dos fornecedores.", "description": "A entidade identifica os fornecedores e pontos de contacto a participar nas atividades previstas nos Planos de Resposta a Incidentes e Plano de Recuperação de Desastres e garante que os mesmos são envolvidos nos testes e nos exercícios planeados.", "measures": {"substancial": {"measure": "A entidade deve identificar o pessoal-chave dos fornecedores a incluir nas atividades previstas nos Plano de Resposta a Incidentes e Plano de Recuperação de Desastres.", "verification": "Registo da inclusão do pessoal-chave dos fornecedores nas atividades previstas nos Plano de Resposta a Incidentes e no Plano de Recuperação de Desastres."}, "elevado": {"measure": "A entidade deve incluir o pessoal-chave dos fornecedores nos seus exercícios e testes dos Plano de Resposta a Incidentes e Plano de Recuperação de Desastres.", "verification": "Registo de testes e exercícios ao Plano de Resposta a Incidentes e Plano de Recuperação de Desastres com a inclusão do pessoalchave dos fornecedores."}}}, "GR.CA-9": {"objective": "GR — Gerir", "category": "GR.CA — Gestão do Risco na Cadeia de Abastecimento", "statement": "As práticas de cibersegurança da cadeia de abastecimento são integradas em programas de cibersegurança e de gestão de riscos organizacionais, e o seu desempenho é monitorizado ao longo do ciclo de vida dos produtos e serviços tecnológicos.", "description": "A entidade garante que todas as práticas de segurança relacionadas com a cadeia de abastecimento são integradas na Política de Cibersegurança, garantindo também uma monitorização contínua de todo o ciclo de vida dos produtos e serviços tecnológicos adquiridos. Esta sinergia permite a manutenção de um ambiente seguro e resiliente, capaz de endereçar os riscos emergentes de forma proativa.", "measures": {}}, "GR.CA-10": {"objective": "GR — Gerir", "category": "GR.CA — Gestão do Risco na Cadeia de Abastecimento", "statement": "Aquando da definição de processos de gestão dos riscos da cadeia de abastecimento de cibersegurança a entidade inclui disposições para atividades que possam ocorrer durante ou após a cessação de contratos com fornecedores ou parceiros.", "description": "A entidade garante que estão instituídos procedimentos internos para o término de parcerias, contratos ou acordos com fornecedores ou parceiros. Esta prática protege a entidade de determinados riscos inerentes às anteriores atividades ou responsabilidades dos fornecedores, como acesso não autorizado a informação ou sistemas, uso indevido de informação interna partilhada, divulgação de vulnerabilidades internas, entre outros aspetos.", "measures": {}}, "ID.GA-1": {"objective": "ID — Identificar", "category": "ID.GA — Gestão de Ativos", "statement": "Os equipamentos e os demais recursos físicos geridos ou detidos pela entidade são inventariados.", "description": "A entidade inventaria os seus equipamentos e os demais recursos físicos existentes, por forma a garantir que existe um mapeamento estruturado dos mesmos, e realiza um mapeamento das dependências entre ativos. Todos os dispositivos inventariados são classificados de acordo com a sua relevância para a entidade.", "measures": {"basico": {"measure": "Os equipamentos e os demais recursos físicos geridos ou detidos pela entidade são inventariados. O inventário deve ser documentado e atualizado.", "verification": "Inventário atualizado de equipamentos e recursos físicos."}, "elevado": {"measure": "A entidade deve utilizar ferramentas de suporte à gestão de equipamentos e os demais recursos físicos.", "verification": "Evidência técnica da ferramenta de inventariação e de suporte à gestão de equipamentos e os demais recursos físicos."}}}, "ID.GA-2": {"objective": "ID — Identificar", "category": "ID.GA — Gestão de Ativos", "statement": "Os recursos lógicos que suportam os processos dos serviços da entidade são inventariados", "description": "A entidade inventaria os recursos lógicos que suportam os processos dos serviços da entidade, por forma a garantir que existe um mapeamento estruturado dos mesmos, e realiza um mapeamento das dependências entre ativos. Todos os dispositivos inventariados são classificados de acordo com a sua relevância para a entidade.", "measures": {"basico": {"measure": "O inventário de recursos lógicos deve refletir as plataformas de software e aplicações que são geridos ou detidos pela entidade. O inventário deve ser documentado e atualizado.", "verification": "Inventário atualizado de recursos lógicos."}, "elevado": {"measure": "A entidade deve utilizar ferramentas ou aplicações de suporte à gestão de recursos lógicos.", "verification": "Evidência técnica da ferramenta de inventariação e de suporte à gestão de recursos lógicos."}}}, "ID.GA-3": {"objective": "ID — Identificar", "category": "ID.GA — Gestão de Ativos", "statement": "As redes e fluxos de comunicação são mapeados.", "description": "A entidade dispõe de um inventário com todas as suas redes de comunicações e de gestão e o mapeamento dos seus fluxos de comunicação internos e externos. O mapeamento de fluxos de comunicação externos inclui, por exemplo, conexões VPN e acessos à internet. Esta informação é essencial para que a entidade tenha conhecimento dos ativos que suportam a sua infraestrutura de comunicações e dos respetivos fluxos de comunicação existentes.", "measures": {"substancial": {"measure": "A entidade deve criar diagramas de rede e sistemas que demonstrem a topologia da sua rede. A entidade deve mapear os fluxos de comunicação entre os seus sistemas internos.", "verification": "Diagramas de rede e sistemas e de fluxos de comunicação internos"}, "elevado": {"measure": "A entidade deve mapear os fluxos de comunicação externos, e os mesmos devem ser documentados, devidamente aprovados e atualizados.", "verification": "Diagramas de rede e sistemas e de fluxos de comunicação externos aprovados e atualizados."}}}, "ID.GA-4": {"objective": "ID — Identificar", "category": "ID.GA — Gestão de Ativos", "statement": "Os serviços prestados por fornecedores são inventariados.", "description": "Descrição A entidade mantém um inventário atualizado de todos os serviços externos prestados por fornecedores os quais utiliza e depende. Este inventário permite que a entidade tenha conhecimento do(s) responsáveis pela gestão destes serviços e das suas dependências.", "measures": {"basico": {"measure": "A entidade deve incluir no seu inventário de ativos os serviços prestados por fornecedores que utiliza e dos quais depende.", "verification": "Inventário de ativos que inclua os serviços prestados por fornecedores que a entidade utiliza e depende."}}}, "ID.GA-5": {"objective": "ID — Identificar", "category": "ID.GA — Gestão de Ativos", "statement": "Os ativos são classificados de acordo com a sua criticidade.", "description": "A entidade classifica os seus ativos de acordo com a criticidade e valor que estes ativos representem para si. No processo de inventariação, a entidade: 1 — Identifica um método de classificação de ativos que seja aprovado internamente; 2 — Garante que os responsáveis pelos ativos os classificam de acordo com a importância dos mesmos para a entidade.", "measures": {"basico": {"measure": "Os ativos devem ser classificados de acordo com a sua criticidade e valor dos mesmos.", "verification": "Registo da classificação dos ativos de acordo com a sua criticidade e valor."}}}, "ID.GA-6": {"objective": "ID — Identificar", "category": "ID.GA — Gestão de Ativos", "statement": "Os dados e respetivos metadados são identificados e registados.", "description": "A entidade mantém um registo atualizado dos dados e respetivos metadados para cada tipo de dados designados. sendo que se entendem como dados designados os dados que a entidade explicitamente identifica, categoriza e sinaliza como requerendo tratamento, proteção ou gestão especial. Este inclui o seu tipo, localização, responsável e classificação em termos de criticidade. Esta prática permite à entidade uma melhor gestão dos dados gerados, guardados e que circulam na rede, facilitando a gestão ao nível do cumprimento de requisitos legais e a correta e ponderada aplicação de medidas de cibersegurança que restrinjam e protejam o uso e retenção dos dados com base no risco. Os metadados são dados sobre dados, isto é, informação que descreve os dados. São exemplos de metadados: a) Metadados descritivos (título, autor, palavras-chave); b) Metadados estruturais (formato, esquema); c) Metadados administrativos (acessos, políticas de armazenamento da informação); d) Metadados técnicos (arquivo, informações de codificação e local de armazenamento).", "measures": {"elevado": {"measure": "Os dados e respetivos metadados que a entidade trata devem ser identificados e classificados de acordo com a Política de Classificação e Gestão de Dados.", "verification": "Registo da identificação e classificação dos dados e respetivos metadados, de acordo com a Política de Classificação e Gestão de Dados."}}}, "ID.GA-7": {"objective": "ID — Identificar", "category": "ID.GA — Gestão de Ativos", "statement": "Sistemas, hardware, software, serviços e dados são geridos ao longo dos seus ciclos de vida", "description": "A entidade gere todos os aspetos relacionados com o ciclo de vida dos seus sistemas, hardware, software, serviços e dados ao longo dos seus ciclos de vida, desde a sua aquisição/criação até à sua eventual destruição. Este ciclo é monitorizado por forma a assegurar que os ativos da entidade são protegidos e mantidos em todas as suas fases da vida da forma mais eficiente e considerando o seu nível de risco. No ciclo de vidaé incluída a manutenção do software da entidade, que é sujeita a processos de aprovação. A manutenção é registada de forma a impedir a existência de acessos e utilização não autorizados. A entidade executa as tarefas de manutenção dos seus ativos críticos, de forma regular e atempada. A manutenção é registada, efetuada e supervisionada por pessoal da entidade com as autorizações e competências adequadas. A entidade tem procedimentos de autorização, monitorização, registo e de controlo do hardware, sendo este mantido, substituído e removido de acordo com o risco.", "measures": {"basico": {"measure": "A entidade deve realizar atualizações de segurança dos seus sistemas regularmente e deve aplicar patches adequados nas suas aplicações e sistemas, sempre que possível. Na eventual impossibilidade da aplicação de atualizações de segurança, a entidade deve aplicar controlos compensatórios em função do risco A entidade deve garantir a manutenção periódica dos equipamentos e demais recursos físicos existentes. A entidade aprova as ações de manutenção de software e hardware.", "verification": "Evidência técnica das atualizações de segurança e aplicação de patches nas aplicações e sistemas. Evidência técnica de aplicação de controlos compensatórios, que sejam aplicados de acordo com uma análise de risco, na eventual impossibilidade de realização de atualizações de segurança e de aplicação de patches. Registo da execução de manutenções de equipamentos e demais recursos físicos. Registo da aprovação das ações de manutenção de software e hardware."}, "substancial": {"measure": "A entidade deve definir, aprovar e implementar uma Política de Gestão do Ciclo de Vida de Ativos para garantir que são implementadas medidas necessárias para gerir a perda, má utilização, dano ou roubo de ativos. A entidade deve planear, executar e documentar a manutenção preventiva e as reparações dos componentes críticos do seu sistema, de acordo com a Política de Gestão do Ciclo de Vida de Ativos.", "verification": "Política de Gestão do Ciclo de Vida de Ativos aprovada e implementada. Registo documentado do planeamento das ações de manutenção e reparações de componentes críticos dos sistemas, em conformidade com a Política de Gestão do Ciclo de Vida de Ativos."}}}, "ID.GA-8": {"objective": "ID — Identificar", "category": "ID.GA — Gestão de Ativos", "statement": "Os dados são destruídos de acordo com a Política de Classificação e Gestão de Dados definida.", "description": "As informações digitais e físicas são sujeitas aos métodos apropriados de destruição, de acordo com a classificação de informação.", "measures": {"substancial": {"measure": "A entidade deve garantir que os dados dos seus sistemas críticos e as informações sensíveis são destruídos de acordo com a Política de Classificação e Gestão de Dados definida e aprovada.", "verification": "Registo da inclusão de medidas para a destruição dos dados dos sistemas críticos e das informações sensíveis na Política de Classificação e Gestão de Dados."}, "elevado": {"measure": "Os processos de sanitização, físicos e digitais, devem ser documentados e testados, para garantir a eficácia da destruição da informação.", "verification": "Registo do processo de sanitização e dos testes realizados."}}}, "ID.GA-9": {"objective": "ID — Identificar", "category": "ID.GA — Gestão de Ativos", "statement": "A entidade implementa um processo de gestão de alterações.", "description": "A entidade implementa um processo formal de gestão de alterações, assegurando que todas as alterações nos sistemas de informação, planeadas ou não planeadas, e que possam ter impacto na infraestrutura, sistemas, aplicações, serviços ou processos internos, são geridas de forma controlada e segura. As alterações incluem, mas não se limitam a: Atualizações de software, patches de segurança e correções de vulnerabilidades; Alteração de configurações de servidores, redes ou bases de dados; Implementação de novas políticas de segurança, como regras de firewall; Alteração de permissões de acesso para utilizadores: Substituição ou atualização de hardware; Introdução de novas aplicações ou descontinuação de sistemas antigos.", "measures": {"elevado": {"measure": "A entidade deve estabelecer regras internas para a gestão de alterações, incluindo processos de avaliação e aprovação prévia de alterações. As alterações devem ser testadas e validadas antes da sua implementação nos sistemas operacionais. A entidade deve garantir a atualização dos seus procedimentos de forma a acompanhar as alterações efetuadas.", "verification": "Registo do processo documentado de gestão de alterações que inclua, pelo menos, a avaliação e aprovação prévia das regras para a realização de alterações. Registo do resultado dos testes e da validação às alterações efetuadas antes da sua implementação em produção. Evidência de uma gestão do quotidiano que reflita atualizações de procedimentos quando existam alterações."}}}, "ID.AR-1": {"objective": "ID — Identificar", "category": "ID.AR — Avaliação do Risco", "statement": "As vulnerabilidades dos ativos são identificadas e documentadas com base na metodologia definida.", "description": "Uma das bases da avaliação do risco da entidade é o processo de gestão de vulnerabilidades, nomeadamente, todas as vulnerabilidades conhecidas que não foram mitigadas. Estas vulnerabilidades são avaliadas em sede de análise do risco da entidade, sendo formalmente definida qual a estratégia a aplicar, respeitando a metodologia de gestão dos riscos da entidade.", "measures": {"basico": {"measure": "A entidade deve identificar vulnerabilidades dos seus ativos.", "verification": "Registo documentado das vulnerabilidades identificadas"}, "substancial": {"measure": "A entidade deve aprovar e implementar uma Política de Monitorização, Identificação e Documentação das Vulnerabilidades dos seus sistemas críticos e implementar a mesma através da definição de um processo, que esteja incluído na Política.", "verification": "Política de Monitorização, Identificação e Documentação das Vulnerabilidades aprovada e implementada."}, "elevado": {"measure": "A entidade deve utilizar ferramentas de identificação e monitorização contínua das vulnerabilidades dos seus ativos. A entidade deve realizar testes de intrusão regulares.", "verification": "Evidência técnica de ferramentas de identificação e monitorização contínua das vulnerabilidades. Registo do resultado da realização regular de testes de intrusão."}}}, "ID.AR-2": {"objective": "ID — Identificar", "category": "ID.AR — Avaliação do Risco", "statement": "A entidade partilha informações sobre ameaças de cibersegurança com partes interessadas.", "description": "A entidade estabelece contacto com grupos de interesse sobre cibersegurança, para trocar experiências sobre boas práticas e ter acesso a informações relevantes sobre cibersegurança. As informações sobre ameaças podem ser recolhidas junto de fóruns ou em fontes de partilha de informações da especialidade. Caso as fontes de partilha de informação sejam de formato eletrónico e passíveis de ser consumidas por interfaces aplicacionais, devem ser sistematizados processos automáticos de recolha, tratamento e armazenamento das mesmas, para posterior correlação pelos sistemas de gestão e correlação de eventos de segurança.", "measures": {}}, "ID.AR-3": {"objective": "ID — Identificar", "category": "ID.AR — Avaliação do Risco", "statement": "As ameaças internas e externas são identificadas e documentadas com base na metodologia definida.", "description": "No âmbito do processo de gestão dos riscos, a entidade identifica potenciais ameaças que possam explorar vulnerabilidades eventualmente existentes nos seus ativos. As ameaças podem ser internas ou externas à entidade, podendo ser de origem natural ou humana, e acidentais ou intencionais.", "measures": {}}, "ID.AR-4": {"objective": "ID — Identificar", "category": "ID.AR — Avaliação do Risco", "statement": "São identificados e registados potenciais impactos e as respetivas probabilidades de ameaças.", "description": "A entidade identifica, na sua metodologia de gestão do risco, os critérios associados à aferição de probabilidade e impacto das ameaças. Os critérios para a definição da probabilidade e do impacto das ameaças devem considerar o contexto organizacional, os objetivos de negócio, bem como os próprios objetivos do processo de gestão dos riscos.", "measures": {"basico": {"measure": "A entidade deve determinar e registar, no processo de gestão dos riscos, a probabilidade de concretização de ameaças e avaliar os respetivos potenciais impactos.", "verification": "Critérios para determinar a probabilidade das ameaças e para a avaliar os potenciais impactos das mesmas."}}}, "ID.AR-5": {"objective": "ID — Identificar", "category": "ID.AR — Avaliação do Risco", "statement": "A entidade avalia os riscos identificados.", "description": "A entidade avalia os riscos identificados com base na lista das ameaças e vulnerabilidades dos ativos, das medidas implementados e a sua eficácia. O risco é expresso como a combinação do impacto de um evento e a sua probabilidade de acontecer.", "measures": {"basico": {"measure": "A entidade deve realizar avaliações do risco com base na análise de ameaças, vulnerabilidades, probabilidades e impactos nos processos e em todos os ativos que garantam a continuidade do funcionamento das redes e sistemas de informação que utilizam, incluindo os ativos que garantam a prestação dos serviços críticos.", "verification": "Evidência da gestão quotidiana que demonstre realização de avaliações do risco tendo como base a análise de ameaças, vulnerabilidades, probabilidades e impactos nos processos e ativos organizacionais"}, "substancial": {"measure": "As avaliações do risco devem ser conduzidas, documentadas e atualizadas de forma contínua, com base nos critérios definidos na sua metodologia de gestão do risco.", "verification": "Registo documentado da avaliação do risco e respetiva atualização, tendo por base os critérios definidos na metodologia."}}}, "ID.AR-6": {"objective": "ID — Identificar", "category": "ID.AR — Avaliação do Risco", "statement": "A entidade garante que as respostas aos riscos são identificadas e priorizadas.", "description": "A entidade define a resposta adequada ao nível do risco encontrado. A prioridade de tratamento dos riscos é definida de acordo com o nível do risco observado e a criticidade do ativo para a entidade.", "measures": {"basico": {"measure": "A entidade implementa controlos de segurança para os riscos identificados.", "verification": "Evidência técnica da implementação de controlos de segurança para os riscos identificados."}, "substancial": {"measure": "As respostas aos riscos devem ser identificadas, priorizadas, planeadas, acompanhadas e comunicadas.", "verification": "Registo da identificação, priorização, planeamento, acompanhamento e comunicação das respostas aos riscos."}, "elevado": {"measure": "A entidade deve incluir na sua estratégia de tratamento dos riscos um plano de monitorização, revisão e melhoria contínua das respostas aos riscos.", "verification": "Registo da inclusão de um plano de monitorização, revisão e melhoria contínua, na estratégia de tratamento dos riscos."}}}, "ID.AR-7": {"objective": "ID — Identificar", "category": "ID.AR — Avaliação do Risco", "statement": "A entidade define processos para receber informação, analisar e responder a vulnerabilidades provenientes de fontes internas e externas.", "description": "A entidade define um processo formal para receber a submissão de vulnerabilidades, provenientes de fontes internas ou externas (por exemplo: formulários semi-automatizados, testes internos, relatórios de segurança ou investigadores de segurança). Cada submissão é analisada, verificada e, no caso de se confirmar que a informação configura uma vulnerabilidade, a entidade segue o processo de resposta a vulnerabilidades conforme definido.", "measures": {"basico": {"measure": "A entidade deve tratar as vulnerabilidades que tenha conhecimento.", "verification": "Registo da identificação e de tratamento das vulnerabilidades."}, "substancial": {"measure": "A entidade deve implementar processos de gestão de vulnerabilidades que incluam processamento, análise e correção de vulnerabilidades de fontes internas e externas. O processo de gestão de vulnerabilidades da entidade deve estar alinhado com a Instrução Técnica de Divulgação Coordenada de Vulnerabilidades.", "verification": "Registo dos processos de gestão de vulnerabilidades que incluam processamento, análise e correção de vulnerabilidades de fontes internas e externas, o qual deve estar alinhado com a Instrução Técnica de Divulgação Coordenada de Vulnerabilidades."}, "elevado": {"measure": "As vulnerabilidades registadas devem ser analisadas e avaliadas sistematicamente. A entidade deve implementar mecanismos automatizados, para divulgar e acompanhar os esforços de correção de vulnerabilidades, recolhidas de fontes internas e externas, para as principais partes interessadas.", "verification": "Registo do resultado da análise e avaliação das vulnerabilidades identificadas. Evidência técnica da implementação de mecanismos automatizados para a divulgação e acompanhamento dos esforços de correção de vulnerabilidades."}}}, "ID.MC-1": {"objective": "ID — Identificar", "category": "ID.MC — Melhoria Contínua", "statement": "As melhorias são identificadas através de avaliações e a informação é partilhada com as partes interessadas.", "description": "A entidade tem um compromisso com a melhoria dos seus processos de gestão do risco de cibersegurança, efetuando sessões de lições aprendidas, analisando os incidentes já ocorridos, entre outros, para reduzir o risco da ocorrência de incidentes futuros. A entidade partilha com as partes relevantes a informação sobre melhorias identificadas.", "measures": {}}, "ID.MC-2": {"objective": "ID — Identificar", "category": "ID.MC — Melhoria Contínua", "statement": "São identificadas melhorias a partir de testes e exercícios de cibersegurança.", "description": "A entidade realiza testes e exercícios de cibersegurança, incluindo com partes interessadas, quando se justificar, para identificar pontos de melhoria. A entidade garante que Planos de Reposta a Incidentes, Planos de Recuperação de Desastres, e Planos de Continuidade de Negócio estabelecidos são testados, para que se possa determinar a eficácia, prontidão de execução dos mesmos e identificar possíveis pontos de falha.", "measures": {"elevado": {"measure": "Os testes e exercícios de cibersegurança devem ser utilizados para identificar pontos de melhoria dos processos da entidade. A entidade deve realizar testes com partes interessadas.", "verification": "Registo da realização de testes e exercícios de cibersegurança, incluindo os efetuados com partes interessadas."}}}, "ID.MC-3": {"objective": "ID — Identificar", "category": "ID.MC — Melhoria Contínua", "statement": "As melhorias são identificadas a partir da execução de processos, procedimentos e atividades operacionais.", "description": "A entidade avalia e atualiza regularmente os seus processos e procedimentos de cibersegurança para que as possíveis fragilidades existentes sejam identificadas e alvo de um plano de correção. A entidade extrai conclusões com os incidentes que ocorrem nas suas redes e sistemas de informação, identificando medidas operacionais e/ou processuais que possam melhorar a capacidade de deteção de novos incidentes.", "measures": {"basico": {"measure": "A entidade deve efetuar avaliações pós-incidentes para identificar as lições aprendidas e, consequentemente, melhorar os processos/procedimentos/tecn ologias para reforçar a sua ciber-resiliência.", "verification": "Registo documentado das avaliações pósincidentes, com identificação de lições aprendidas, definição e implementação de melhorias."}, "substancial": {"measure": "A entidade deve incluir nos seus planos e processos de gestão de cibersegurança, as melhorias derivadas da monitorização e avaliação periódicas, das medidas, controlos e processos de cibersegurança.", "verification": "Registo das melhorias derivadas da monitorização e avaliação periódicas nos seus planos e processos de gestão de cibersegurança."}}}, "PR.GA-1": {"objective": "PR — Proteger", "category": "PR.GA — Gestão de Identidades, Autenticação e Controlo de Acessos", "statement": "Os ciclos de vida de gestão de identidades são definidos", "description": "A entidade garante que as identidades e credenciais de acesso às suas redes e sistemas de informação são emitidas, geridas, verificadas, revogadas e auditadas em conformidade com os processos instituídos.", "measures": {"basico": {"measure": "As identidades e credenciais de dispositivos, serviços e utilizadores devem ser geridas. A entidade deverá implementar uma Política de Palavra-passe e uma Política de Gestão de Identidades, Autenticação e Controlo de Acessos.", "verification": "Evidência técnica da gestão de identidades e respetivas credenciais de dispositivos, serviços e utilizadores. Política de Gestão de Identidades, Autenticação e Controlo de Acessos aprovada e implementada. Política de Palavra-passe aprovada e implementada."}, "substancial": {"measure": "As credenciais dos sistemas devem ser desativadas após um período específico de inatividade, como determinado na Política de Gestão de Identidades, Autenticação e Controlo de Acessos, a menos que isso comprometa o funcionamento seguro dos processos críticos. Os sistemas críticos da entidade devem ser monitorizados quanto à utilização atípica de credenciais dos sistemas.", "verification": "Evidência técnica da desativação de credenciais dos sistemas, após o período específico de inatividade definido de acordo com a Política de Gestão de Identidades, Autenticação e Controlo de Acessos. Registo da monitorização contínua dos sistemas críticos quanto à utilização atípica de credenciais dos sistemas."}, "elevado": {"measure": "As identidades e credenciais dos dispositivos, serviços e utilizadores devem ser geridas através de mecanismos automatizados. A entidade deve aplicar autenticação segura nas suas transações entre sistemas críticos, nomeadamente, a autenticação multifator (MFA), certificados criptográficos, tokens e chaves criptográficas.", "verification": "Evidência técnica de mecanismos automatizados de suporte à gestão de identidades e credenciais dos dispositivos, serviços e utilizadores. Evidência técnica da aplicação de autenticação segura nas transações entre sistemas críticos."}}}, "PR.GA-2": {"objective": "PR — Proteger", "category": "PR.GA — Gestão de Identidades, Autenticação e Controlo de Acessos", "statement": "A entidade verifica a identidade dos utilizadores e vincula-a às respetivas credenciais.", "description": "A identidade dos utilizadores é vinculada, revista e as suas credenciais confirmadas de forma iterativa e quando necessário.", "measures": {"substancial": {"measure": "A entidade deve implementar procedimentos de acordo com o estabelecido na Política de Gestão de Identidades, Autenticação e Controlo de Acessos para verificar a identidade dos utilizadores antes de emitir as credenciais que dão acesso aos sistemas da entidade.", "verification": "Registo da implementação de procedimentos de verificação da identidade dos utilizadores, antes da emissão de credenciais."}, "elevado": {"measure": "A entidade deve garantir a utilização de credenciais únicas associadas a cada utilizador, dispositivo e processo que interaja com os sistemas críticos da entidade. A entidade deve garantir que todas as exceções estão documentadas e devidamente aprovadas.", "verification": "Evidência técnica da atribuição de credenciais únicas para cada utilizador, dispositivo ou processo que interaja com sistemas críticos da entidade. Registo documentado das exceções à Política de Gestão de Identidades, Autenticação e Controlo de Acessos e a sua respetiva aprovação."}}}, "PR.GA-3": {"objective": "PR — Proteger", "category": "PR.GA — Gestão de Identidades, Autenticação e Controlo de Acessos", "statement": "São definidos mecanismos de autenticação de utilizadores, dispositivos e outros ativos de sistemas de informação.", "description": "Os mecanismos de autenticação são definidos e mantidos de acordo com as características dos sistemas e dos perfis de acesso, por forma a permitir a manutenção da integridade e a confidencialidade da informação.", "measures": {"basico": {"measure": "A entidade deve implementar autenticação multifator (MFA) nos acessos remotos e contas privilegiadas.", "verification": "Evidência técnica da implementação de autenticação multifator (MFA) nos acessos remotos e contas privilegiadas."}, "substancial": {"measure": "A entidade deve realizar uma avaliação do risco das comunicações entre sistemas críticos. Como resultado da avaliação, a entidade deve aplicar mecanismos de autenticação aos utilizadores, dispositivos e outros ativos, adequados e proporcionais ao risco identificado. A entidade deve implementar autenticação multifator (MFA) nos seus sistemas críticos.", "verification": "Registo da avaliação do risco das comunicações entre sistemas críticos. Evidência técnica dos mecanismos de autenticação aplicados aos utilizadores, dispositivos e outros ativos. Evidência técnica da implementação de autenticação multifator (MFA) nos sistemas críticos."}, "elevado": {"measure": "A comunicação entre os sistemas da entidade e os sistemas externos (como os de parceiros, fornecedores ou prestadores de serviços, incluindo, serviços de computação em nuvem) deve ser enquadrada num acordo entre as entidades participantes. A entidade deve implementar autenticação multifator (MFA) em todos os seus dispositivos e outros ativos de sistemas de informação, quando estes o permitam.", "verification": "Modelos de acordos entre a entidade e terceiros para comunicação entre sistemas. Evidência técnica da implementação de autenticação multifator (MFA) em todos os seus dispositivos e outros ativos de sistemas de informação, quando possível."}}}, "PR.GA-4": {"objective": "PR — Proteger", "category": "PR.GA — Gestão de Identidades, Autenticação e Controlo de Acessos", "statement": "As afirmações de identidade são protegidas, transmitidas e verificadas.", "description": "A entidade protege as afirmações de identidade utilizadas para transmitir a autenticação e as informações do utilizador, por exemplo, através de sistemas de início de sessão único (SSO — Single Sign-On). Entendem-se por afirmações de identidade, uma declaração digital utilizada durante a autenticação que confirma a identidade de um utilizador, dispositivo ou processo.", "measures": {"elevado": {"measure": "As afirmações de identidade devem ser protegidas, transmitidas e verificadas.", "verification": "Evidência técnica da proteção, transmissão e verificação das afirmações de identidade."}}}, "PR.GA-5": {"objective": "PR — Proteger", "category": "PR.GA — Gestão de Identidades, Autenticação e Controlo de Acessos", "statement": "As permissões de acesso, os direitos e as autorizações são definidas numa política, são geridas, aplicadas e atualizadas, e incorporam os princípios do menor privilégio e da separação de funções.", "description": "As permissões de acesso e as autorizações são geridas de acordo com os princípios de acesso adequados à função, de acordo com os princípios de necessidade de conhecer e de segregação de funções, sendo que estes princípios e medidas de cibersegurança se aplicam a sistemas de TIC e TO, sempre que aplicável. Entende-se, por menor privilégio o acesso às redes e sistemas de informação da entidade concedido de acordo com o correto desempenho das suas funções. Por segregação de funções, entende-se a divisão de atribuição de funções e de privilégios entre múltiplos indivíduos, de forma que um processo em particular não possa ser executado ou controlado apenas por um deles. O principal fundamento, para a aplicação desta prática de segregação de funções, é a prevenção de incidentes com impacto significativo nas atividades operacionais da entidade. Existindo múltiplas pessoas envolvidas, minimiza-se a oportunidade de transgressões e fomenta-se a probabilidade de estas serem detetadas e reportadas. O princípio de segregação de funções pode ser aplicado nos seguintes tipos de processos: 1 — Sequenciais: quando as atividades podem ser executadas em tarefas sequenciais e por pessoas diferentes (por exemplo: na atribuição de acessos, uma pessoa solicita, outra aprova e uma terceira atribui os acessos); 2 — Quórum: Quando as atividades requerem um quórum mínimo de aprovações para poderem ser executadas (por exemplo: a recuperação de uma chave de cifra, onde é requerida a presença de dois ou mais administradores de sistemas); 3 — Geoespacial: quando as atividades podem ser divididas em tarefas que são realizadas em locais diferentes (por exemplo: gestão de sistemas de informação, cujas tarefas são efetuadas por pessoal sediado em diferentes zonas geográficas).", "measures": {"basico": {"measure": "As permissões de acesso dos utilizadores aos sistemas da entidade devem ser definidas e geridas, em conformidade com a Política de Gestão de Identidades, Autenticação e Controlo de Acessos existente, sendo que as permissões de acesso devem ser revistas periodicamente. Os acessos aos dados, informações e tecnologias críticas, devem ser identificados de acordo com o princípio do menor privilégio. A entidade deve garantir que não são atribuídos privilégios de administração por defeito.", "verification": "Registo documentado da definição e evidência técnica da gestão de acessos dos utilizadores aos sistemas da entidade em conformidade com a Política de Gestão de Identidades, Autenticação e Controlo de Acessos. Inclusão na Política de Gestão de Identidades, Autenticação e Controlo de Acessos de critérios que garantam a aplicação do princípio do menor privilégio. Registo documentado dos utilizadores com privilégios de administração atribuídos e respetiva aprovação."}, "substancial": {"measure": "A entidade deve implementar mecanismos para apoiar a gestão de acessos aos seus sistemas críticos, incluindo a desativação, a monitorização, a comunicação e a eliminação de contas de utilizadores. A entidade deve aplicar o princípio de segregação de funções na gestão de permissões de acesso. A entidade deve gerir, documentar e rever regularmente as atribuições de privilégios elevados a utilizadores.", "verification": "Evidência técnica da implementação de mecanismos para apoiar a gestão do ciclo de vida dos acessos aos sistemas críticos. Registo da segregação de perfis de administração de ativos críticos em função da lista de papéis, funções e responsabilidades. Registo documentado da atribuição de privilégios elevados a utilizadores."}, "elevado": {"measure": "A entidade deve monitorizar o contexto em que ocorre a autenticação de utilizadores, e identificar os acessos realizados através de dispositivos, localizações e horários não habituais. A entidade deve monitorizar as atividades realizadas por utilizadores com privilégios elevados.", "verification": "Evidência técnica da aplicação de restrições e monitorização ativa do contexto em que ocorre a autenticação de utilizadores. Evidência técnica da monitorização das atividades realizadas por utilizadores com privilégios elevados."}}}, "PR.GA-6": {"objective": "PR — Proteger", "category": "PR.GA — Gestão de Identidades, Autenticação e Controlo de Acessos", "statement": "Os controlos de acesso físico a ativos da entidade são geridos, monitorizados e aplicados em função do risco.", "description": "A entidade protege e gere os acessos físicos às suas infraestruturas de rede e de sistemas de informação. A entidade aplica este controlo ao seu pessoal, visitantes, e terceiros que colaboram com a entidade, nas zonas da entidade que sejam de acesso restrito e/ou a áreas sensíveis que alojem informação confidencial, redes e/ou sistemas de informação.", "measures": {"basico": {"measure": "A entidade deve definir quais são as zonas de acesso restrito que alojam informação confidencial, e/ou redes e/ou sistemas de informação e deve protegê-las.", "verification": "Evidência da definição das zonas de acesso restrito. Evidência da aplicação de medidas para proteção das zonas de acesso restrito."}, "substancial": {"measure": "O acesso físico a zonas de acesso restrito da entidade deve ser monitorizado. O acesso físico a zonas de acesso restrito deve incluir medidas para situações de emergência.", "verification": "Registo da monitorização do acesso físico a zonas de acesso restrito. Registo da definição de medidas para o acesso físico a zonas de acesso restrito a aplicar em situações de emergência."}, "elevado": {"measure": "Os ativos alojados nas zonas de acesso restrito devem ser fisicamente protegidos.", "verification": "Evidência técnica da implementação de proteções físicas aos ativos alojados nas zonas críticas."}}}, "PR.GA-7": {"objective": "PR — Proteger", "category": "PR.GA — Gestão de Identidades, Autenticação e Controlo de Acessos", "statement": "A entidade gere os seus acessos remotos.", "description": "A entidade documenta, gere e controla os acessos remotos às suas redes e sistemas de informação. São considerados acessos remotos, todos os acessos feitos às redes e sistemas de informação por pessoal que comuniquem através de redes de comunicações externas à entidade. As VPN, quando criadas, devem ser consideradas redes de comunicações internas, observando-se os controlos de segurança apropriados. Cumulativamente, apenas são considerados acessos remotos a redes e sistemas de informação, aqueles que sejam realizados a sistemas que não estejam propositadamente disponíveis publicamente.", "measures": {"basico": {"measure": "A entidade deve definir e documentar a lista de utilizadores e dispositivos com permissão para aceder remotamente às suas redes e sistemas. A entidade deve implementar controlos de segurança adequados para proteger as suas redes e sistemas quando acedidos remotamente.", "verification": "Registo documentado dos utilizadores e dispositivos autorizados a aceder remotamente a redes e sistemas da entidade. Evidência técnica da implementação de controlos de segurança para proteção adequada de ligações remotas aos sistemas da entidade."}, "substancial": {"measure": "A entidade deve definir e implementar de acordo com a Política de Gestão de Identidades, Autenticação e Controlo de Acessos, as restrições de utilização, os requisitos de ligação e as autorizações de acesso remoto ao ambiente dos sistemas críticos da entidade. As ações realizadas no âmbito de manutenções remotas devem ser monitorizadas para análise de potenciais eventos que coloquem em causa a segurança dos sistemas. Os acessos atribuídos para manutenções remotas devem ser revogados assim que deixarem de ser necessários.", "verification": "Evidencia técnica da implementação de medidas de segurança para garantir que os acessos remotos ao ambiente dos sistemas críticos da entidade cumprem as restrições de utilização, os requisitos de ligação e as autorizações definidas. Evidencia técnica da monitorização das manutenções remotas, e dos acessos autorizados, atribuídos, e revogados após a conclusão da manutenção."}, "elevado": {"measure": "O acesso remoto aos sistemas críticos da entidade deve ser monitorizado. O acesso remoto deve ser realizado através de canais seguros, utilizando mecanismos de encriptação forte e protocolos seguros aprovados internamente, sendo que o mesmo se aplica a ações de manutenção remota.", "verification": "Evidencia técnica da implementação de canais seguros para acesso remoto (incluindo ações de manutenção). Evidência técnica da recolha e análise dos registos de atividades dos utilizadores em formato remoto aquando do seu acesso aos sistemas críticos da entidade."}}}, "PR.FC-1": {"objective": "PR — Proteger", "category": "PR.FC — Formação e Sensibilização", "statement": "Todo o pessoal é sensibilizado e formado em matérias de cibersegurança.", "description": "A entidade estabelece um plano de ações de sensibilização e formação em cibersegurança e define os processos e procedimentos necessários para garantir a sua correta implementação. A entidade mede o sucesso das suas ações de formação. As ações de sensibilização visam consciencializar um grupo abrangente de pessoas sobre um determinado tema enquanto as ações de formação têm como objetivo capacitar um determinado grupo de pessoas com conhecimento e competências específicas.", "measures": {"basico": {"measure": "A entidade deve garantir que o pessoal é sensibilizado em matéria de cibersegurança e que os mesmos participam em ações de sensibilização periodicamente.", "verification": "Registo documentado da participação do pessoal em ações de sensibilização em matéria de cibersegurança."}, "substancial": {"measure": "A entidade deve realizar ações de formação periódicas para que o pessoal compreenda as suas funções, responsabilidades e prioridades específicas durante um incidente de cibersegurança, incluindo quais as ações que devem seguir para responder de forma eficaz. A entidade deve incluir a sensibilização e a comunicação de ameaças internas na sua formação em cibersegurança, de forma a ajudar o pessoal a reconhecer e responder a potenciais ameaças internas.", "verification": "Registo documentado da participação periódica do pessoal em ações de formação em matérias de cibersegurança."}, "elevado": {"measure": "A entidade deve definir e implementar indicadores para avaliar a eficácia das ações de sensibilização e formação. A entidade deve aplicar os resultados dos indicadores recolhidos, nos seus processos de melhoria contínua.", "verification": "Registo da definição dos indicadores para avaliar a eficácia das ações de sensibilização e formação, e recolha dos resultados dos mesmos com a respetiva integração em processos de melhoria continua."}}}, "PR.FC-2": {"objective": "PR — Proteger", "category": "PR.FC — Formação e Sensibilização", "statement": "O pessoal com funções especializadas em cibersegurança e os órgãos de gestão, direção e administração recebem formação adequada para o exercício das suas funções.", "description": "As pessoas que desempenham funções especializadas em cibersegurança e os órgãos de gestão, direção e administração são sensibilizadas e formadas de modo a possuírem os conhecimentos e as competências necessárias para desempenharem tarefas relevantes, tendo em conta os riscos de cibersegurança.", "measures": {"basico": {"measure": "A entidade deve assegurar que os membros dos órgãos de gestão, direção e administração completam formações periódicas em matéria de cibersegurança.", "verification": "Registo documentado da participação periódica dos membros dos órgãos de gestão, direção e administração em ações de formação em matéria de cibersegurança."}, "substancial": {"measure": "A entidade deve definir, implementar e atualizar periodicamente um plano estruturado de ações de formação em matéria de cibersegurança para o pessoal com funções especializadas em cibersegurança.", "verification": "Registo documentado da definição do Plano de sensibilização e formação para pessoal com funções especializadas em cibersegurança, e da respetiva execução do mesmo."}}}, "PR.SD-1": {"objective": "PR — Proteger", "category": "PR.SD — Segurança de Dados", "statement": "A entidade protege a confidencialidade, integridade e disponibilidade dos dados em repouso.", "description": "As redes e sistemas de informação protegem a confidencialidade, integridade e disponibilidade dos dados armazenados.", "measures": {"substancial": {"measure": "A entidade deve implementar controlos de verificação da integridade da informação, do software e firmware para detetar alterações não autorizadas aos dados por si armazenados. A restrição da utilização de suportes de armazenamento amovíveis deve ser assegurada em conformidade com a Política de Uso Aceitável.", "verification": "Evidência técnica da implementação de controlos de verificação da integridade da informação do software e firmware. Evidência técnica da configuração da restrição da utilização de suportes de armazenamento amovíveis."}, "elevado": {"measure": "A entidade protege as informações dos seus sistemas críticos, consideradas críticas/sensíveis, enquanto estiverem armazenadas, utilizando mecanismos criptográficos.", "verification": "Evidência técnica da implementação de controlos de segurança, e de mecanismos criptográficos, para proteção da informação armazenada nos sistemas críticos e que seja considerada crítica/sensível."}}}, "PR.SD-2": {"objective": "PR — Proteger", "category": "PR.SD — Segurança de Dados", "statement": "A entidade protege a confidencialidade, integridade e disponibilidade dos dados em trânsito.", "description": "A entidade protege adequadamente a integridade e a confidencialidade da informação transmitida. Este controlo é aplicado, quer a redes de comunicações internas, como externas. Para sistemas distribuídos, este controlo aplica-se em toda a linha, por forma a garantir a integridade entre os componentes e serviços que geram a informação e os componentes e serviços que a recebem. Quando for impraticável ou impossível garantir os controlos de cibersegurança necessários e as garantias de controlo efetivo através dos veículos contratuais apropriados, a entidade implementa os controlos compensatórios necessários ou explicitamente aceita o risco adicional e/ou transfere o risco para o fornecedor contratual.", "measures": {"basico": {"measure": "A entidade deve implementar mecanismos criptográficos para o acesso aos dados e informação considerada crítica/ sensível.", "verification": "Evidência técnica da implementação de mecanismos criptográficos para os dados em trânsito."}, "elevado": {"measure": "A entidade deve implementar controlos de segurança que garantam a confidencialidade e integridade da informação em trânsito, consoante a sua classificação, para todos os fluxos de dados e interfaces de comunicação para o exterior, de acordo com a Política de Classificação e Gestão de Dados, incluindo quando há recurso a suportes de armazenamento amovíveis. Qualquer exceção à política deve ser devidamente registada.", "verification": "Evidência técnica da implementação dos controlos de segurança para proteção dos dados em trânsito, de acordo com a classificação, e em conformidade com a Política de Classificação e Gestão de Dados, inclusive nos fluxos de dados e interfaces de comunicação para o exterior."}}}, "PR.SD-3": {"objective": "PR — Proteger", "category": "PR.SD — Segurança de Dados", "statement": "A entidade implementa proteções que evitem exfiltração de dados.", "description": "A entidade implementa controlos de segurança nas fronteiras das suas instalações ou das suas redes e sistemas de informação, para detetar acessos e atividades não autorizadas e impedir a exfiltração não autorizada de dados. É definido o âmbito de atuação e frequência da aplicação, com o objetivo de se adequar a mitigação do risco associado. Este risco deve ser calculado tendo por base a classificação de confidencialidade da informação.", "measures": {"elevado": {"measure": "A entidade deve adotar controlos de segurança adequados para monitorizar os seus sistemas críticos nas fronteiras externas e nos pontos críticos internos, para evitar acessos e atividades não autorizadas, incluindo exfiltração de dados.", "verification": "Evidência técnica da implementação de controlos de segurança adequados para monitorizar os sistemas críticos nas fronteiras externas e nos pontos críticos internos, para evitar acessos e atividades não autorizadas, incluindo exfiltração de dados."}}}, "PR.SD-4": {"objective": "PR — Proteger", "category": "PR.SD — Segurança de Dados", "statement": "A entidade protege a confidencialidade, integridade e disponibilidade dos dados em uso.", "description": "As redes e sistemas de informação protegem a confidencialidade, integridade e disponibilidade da informação em utilização.", "measures": {"elevado": {"measure": "A entidade deve implementar controlos de segurança para proteger os seus sistemas críticos ou limitar o impacto de ataques de negação de serviço.", "verification": "Evidência técnica da implementação de controlos de segurança para proteger os sistemas críticos ou limitar o impacto de ataques de negação de serviço."}}}, "PR.SD-5": {"objective": "PR — Proteger", "category": "PR.SD — Segurança de Dados", "statement": "São realizadas, mantidas e testadas cópias de segurança dos dados da entidade.", "description": "A entidade garante que as suas cópias de segurança são testadas e validadas regularmente, através da execução de planos de testes de restauro. Estes testes são efetuados no âmbito dos Planos de Continuidade do Negócio da entidade ou através de exercícios periódicos e planeados, para validação da integridade das cópias de segurança efetuadas.", "measures": {"basico": {"measure": "Devem ser realizadas regularmente cópias de segurança de dados críticos para garantir a continuidade de negócio. A entidade deve armazenar as cópias de segurança num sistema distinto do dispositivo no qual os dados originais estão alojados.", "verification": "Evidência técnica da execução regular de cópias de segurança, e armazenamento num sistema distinto do dispositivo no qual os dados originais estão alojados."}, "substancial": {"measure": "Deve ser definida, aprovada e implementada uma Política de Cópias de Segurança que inclua regras internas formais para a realização das cópias de segurança. A entidade deve verificar e testar regularmente a disponibilidade e integridade das cópias de segurança, de forma independente ao ambiente protegido. Deve ser definido e implementado um esquema de redundância aplicado às cópias de segurança da entidade. As cópias de segurança devem ser mantidas em locais distintos e protegidas segundo os mesmos mecanismos de segurança.", "verification": "Política de Cópias de Segurança aprovada e implementada. Evidência técnica da verificação e de testes regulares, de acordo com a periodicidade definida na Política de Cópias de Segurança, da integridade das cópias de segurança. Evidência técnica da implementação de um esquema de redundância das cópias de segurança, e seu armazenamento em local distinto e protegido."}, "elevado": {"measure": "O processo de verificação das cópias de segurança deve ser implementado em conformidade com os restantes processos, políticas e planos em matéria de cibersegurança da entidade (nomeadamente, o Plano de Continuidade de Negócio e o Plano de Resposta a Incidentes). As cópias de segurança dos sistemas críticos, nomeadamente, de sistemas operativos, configurações e aplicações, devem ser separadas das cópias de segurança de informações críticas.", "verification": "Registo de um processo de verificação das cópias de segurança em conformidade com os restantes procedimentos, planos e políticas da entidade. Evidência técnica do armazenamento em locais separados, das cópias de segurança dos sistemas críticos e das informações críticas."}}}, "PR.SP-1": {"objective": "PR — Proteger", "category": "PR.SP — Segurança de plataformas", "statement": "É criada e mantida uma configuração base de redes e sistemas de informação que incorpora os princípios de segurança.", "description": "A entidade estabelece uma configuração base para redes e sistemas de informação, para os seus componentes e para as suas comunicações e conectividades. Por configuração base, entende-se: 1) Programas informáticos instalados em estações de trabalho; 2) Equipamentos pessoais, tais como computadores portáteis, impressoras e outros dispositivos móveis; 3) Servidores e elementos de rede; 4) Versões e atualizações aplicadas a sistemas operativos e aplicações, configurações e parâmetros por omissão, topologia de rede e composição lógica das arquiteturas das redes e sistemas de informação.", "measures": {"basico": {"measure": "A entidade deve manter uma configuração base de redes e sistemas de informação que incorpora os princípios de segurança.", "verification": "Registo da configuração base aplicada nos diferentes sistemas e componentes de rede da entidade."}, "substancial": {"measure": "A entidade deve desenvolver, documentar e manter atualizada uma configuração base de segurança das suas redes e sistemas de informação.", "verification": "Evidencia técnica das configurações base de segurança das redes e sistemas de informação."}, "elevado": {"measure": "A entidade deve configurar os seus sistemas críticos com base no princípio de funcionalidades mínimas e desativar todos os protocolos, portos e serviços desnecessários. A entidade deve implementar controlos de segurança que prevejam os princípios de “deny-all” e “permit by exception”.", "verification": "Evidência técnica da aplicação do princípio da funcionalidade mínima e desativação de todos os protocolos, portos e serviços desnecessários, aquando da configuração das redes e sistemas da entidade. Evidência técnica da implementação de controlos alinhados com os princípios de segurança de “denyall” e “permit by exception”."}}}, "PR.SP-2": {"objective": "PR — Proteger", "category": "PR.SP — Segurança de plataformas", "statement": "Os logs de sistemas e o histórico de atividades são documentados, implementados e revistos de acordo com as Políticas da entidade.", "description": "Os logs de sistemas e o histórico de atividades da entidade são determinados, documentados, implementados e revistos.", "measures": {"basico": {"measure": "Os logs dos ativos devem ser recolhidos, guardados, protegidos e revistos regularmente. A definição da duração do armazenamento dos logs deve ter em conta a análise do risco dos sistemas e das atividades e o princípio da proporcionalidade.", "verification": "Evidência técnica da recolha, armazenamento e análise regular dos logs dos sistemas da entidade."}, "substancial": {"measure": "Os logs dos ativos devem ser sincronizados utilizando uma fonte interna de relógio sincronizada com uma fonte de relógio oficial.", "verification": "Evidencia técnica da sincronização temporal dos logs dos ativos."}, "elevado": {"measure": "A entidade deve assegurar que as falhas no processamento de logs nos seus sistemas geram alertas. A capacidade de retenção e registo de logs deve ser revista periodicamente e ampliada sempre que necessário. Os logs gerados por sistemas críticos devem ser armazenados em sistema autónomo.", "verification": "Evidência técnica de alarmística para situações de falha de processamento de logs. Evidência técnica do armazenamento de logs gerados por sistemas críticos em sistema autónomo."}}}, "PR.SP-3": {"objective": "PR — Proteger", "category": "PR.SP — Segurança de plataformas", "statement": "A instalação e execução de software não autorizado são impedidas.", "description": "A entidade impede a instalação e execução de software não autorizado ou não aprovado nos dispositivos e sistemas corporativos. Estas ações, caso não sejam monitorizadas e corretamente prevenidas, constituem comportamentos de risco, possibilitando a introdução de vulnerabilidades, malware ou outro tipo de riscos/ameaças que comprometam a segurança, integridade ou confidencialidade dos sistemas ou informação da entidade.", "measures": {"basico": {"measure": "A entidade deve impedir a instalação e execução de software não autorizado. A entidade deve implementar tecnologias de filtro de rede, e-mail e web.", "verification": "Evidência técnica de configuração implementada para impedir a instalação e execução de software não autorizado. Evidência técnica da implementação de tecnologias de filtro de rede, e-mail e web."}}}, "PR.SP-4": {"objective": "PR — Proteger", "category": "PR.SP — Segurança de plataformas", "statement": "É implementado um ciclo de vida de desenvolvimento seguro de software.", "description": "A entidade aplica princípios de cibersegurança na especificação, desenho, desenvolvimento, implementação e modificação das suas redes e sistemas de informação. Estes princípios devem ser aplicados, quer a novos sistemas, como a sistemas que estejam a passar por alterações significativas. Para sistemas legados, estes princípios devem ser aplicados, na medida do possível, tendo em conta o estado atual do hardware, software e firmware desses sistemas.", "measures": {"substancial": {"measure": "O ciclo de vida de desenvolvimento de sistemas e aplicações deve incorporar o princípio de segurança por defeito e princípio de segurança desde a conceção. Em caso de alterações e exceções durante o desenvolvimento de software a entidade deve efetuar uma análise do impacto na segurança, num ambiente de teste separado, antes da implementação em produção.", "verification": "Evidência técnica da aplicação dos princípios de segurança aplicadas ao ciclo de vida de desenvolvimento de sistemas e aplicações. Registos da gestão de alterações aplicável ao desenvolvimento de software."}, "elevado": {"measure": "Ao longo do ciclo de vida do desenvolvimento de software as práticas de desenvolvimento seguro devem ser integradas e o seu desempenho monitorizado.", "verification": "Registo dos testes de qualidade de software, respetivas conclusões e acompanhamento da devida integração dos critérios de segurança definidos."}}}, "PR.RI-1": {"objective": "PR — Proteger", "category": "PR.RI — Resiliência da Infraestrutura Tecnológica", "statement": "A entidade protege a integridade das redes de comunicações.", "description": "A integridade das redes de comunicações é protegida através da sua segregação e segmentação. A rede de comunicações é desenhada de forma a não ser possível aceder-se a qualquer sistema, a partir de qualquer ponto da mesma. São criadas zonas de segurança com propósitos identificados e com barreiras bem definidas e forçadas por equipamentos de rede de comunicações com capacidade para o efeito (routers, gateways, firewalls, entre outros). As segregações da rede de comunicação são documentadas em políticas que definam o seu modelo de governação, nomeadamente, que autorizações são necessárias para a aprovação de novos fluxos e que fluxos entre zonas são pré-aprovados. Os fluxos de informação entre sistemas obrigam a autorizações específicas e conformidade com as políticas definidas para o efeito. Exemplos do que as restrições de fluxos incluem: 1) Impedimentos de transmissão de informação sensível em claro para a Internet; 2) Bloqueio de tráfego externo que indica ser interno (forjado); 3) Restrição de acessos diretos à Internet que não sejam feitos através de um proxy corporativo; 4) Limitação de transferências de informação, com base em estruturas de dados e conteúdos. O controlo dos fluxos de comunicação é efetuado com base nas características da informação e no caminho que a mesma efetua ao longo do seu transporte. A aplicação de restrições deve ser efetuada nos equipamentos de fronteira, como routers, firewalls ou proxies. Os fluxos regulam a transferência de informação e os caminhos que podem ser abertos dentro de cada sistema ou entre sistemas. Estes são controlados operacionalmente e são sempre requeridas as autorizações prévias para que possam ser alterados.", "measures": {"basico": {"measure": "As firewalls devem ser instaladas, configuradas e as suas regras permanentemente atualizadas em todas as redes da entidade. A entidade deve proteger a integridade da rede dos seus sistemas críticos através da incorporação da segmentação e segregação da rede. Todos os pontos de acesso a redes sem fio da entidade devem ser configurados de forma segura, geridos e monitorizados de forma a prevenir acessos não autorizados e assegurar a integridade da rede.", "verification": "Evidência técnica da instalação e ativação de firewalls em todas as redes da entidade. Evidência técnica da segmentação e segregação das redes. Evidência técnica da configuração segura dos pontos de acesso a redes sem fio da entidade, da sua gestão e monitorização."}, "substancial": {"measure": "A integridade da rede dos sistemas críticos deve ser protegida através da identificação, documentação e controlo das ligações entre os componentes do sistema e da limitação das ligações externas aos sistemas críticos da entidade. A entidade deve monitorizar e controlar as ligações e comunicações nos limites externos e nos principais limites internos dos seus sistemas críticos, implementando dispositivos e tecnologias de proteção.", "verification": "Diagrama de redes da entidade com referência à sua segmentação dos sistemas críticos. Demonstração das configurações para bloqueio de ligações não autorizadas aos sistemas críticos. Evidência técnica da monitorização de rede das ligações e comunicações aos sistemas críticos."}, "elevado": {"measure": "A entidade deve implementar servidores proxy autenticados para o tráfego de comunicações definido entre os sistemas críticos da entidade e as redes externas. A entidade deve implementar controlos de segurança e de tolerância a falhas em dispositivos e tecnologias de proteção. A entidade deve controlar os fluxos de dados dos seus sistemas críticos.", "verification": "Evidência técnica da implementação de servidores proxy para a comunicação entre os sistemas críticos e redes externas. Evidência técnica da implementação de controlos de segurança para a tolerância a falhas dos dispositivos e tecnologias de proteção. Evidência técnica da monitorização dos fluxos de dados dos sistemas críticos."}}}, "PR.RI-2": {"objective": "PR — Proteger", "category": "PR.RI — Resiliência da Infraestrutura Tecnológica", "statement": "Os ambientes de desenvolvimento e de teste são separados de ambientes de produção.", "description": "A entidade efetua a separação dos ambientes das suas redes e dos seus sistemas de informação, de forma física ou lógica, de acordo com as suas funções. Os ambientes de desenvolvimento e testes estão segregados dos ambientes de produção, quer em termos de acessos, quer em termos de dados.", "measures": {"substancial": {"measure": "O(s) ambiente(s) de desenvolvimento e teste deve(m) ser isolado(s) do ambiente de produção.", "verification": "Evidência técnica da separação de ambientes de teste e de produção."}}}, "PR.RI-3": {"objective": "PR — Proteger", "category": "PR.RI — Resiliência da Infraestrutura Tecnológica", "statement": "Os ativos tecnológicos da entidade são protegidos de ameaças naturais.", "description": "A entidade protege as redes e sistemas de informação contra desastres naturais, falhas de energia, incêndios e inundações.", "measures": {"elevado": {"measure": "A entidade deve implementar dispositivos de deteção de incêndios que se ativam e notificam automaticamente o pessoal indicado em caso de incêndio. A entidade deve testar periodicamente a eficácia dos controlos de segurança aplicados aos ambientes físicos.", "verification": "Evidência técnica da implementação de dispositivos de deteção contra ameaças naturais e registo da realização periódica de testes."}}}, "PR.RI-4": {"objective": "PR — Proteger", "category": "PR.RI — Resiliência da Infraestrutura Tecnológica", "statement": "São implementados mecanismos para cumprir os requisitos de resiliência em situações adversas.", "description": "A entidade implementa os controlos necessários para que possa cumprir os requisitos de resiliência básicos em situações fora do comum e que garantam a alocação de recursos e equipamentos adicionais. Caso seja necessário responder a situações adversas, coloca-se em prática o Plano de Continuidade de Negócio.", "measures": {"substancial": {"measure": "A entidade deve garantir a implementação de controlos adequados para responder em tempo útil a eventuais disrupções às normais operações, em conformidade com o Plano de Continuidade de Negócios estabelecido. A entidade deve garantir a existência de mecanismos que garantam a disponibilidade dos seus sistemas críticos, através de soluções de balanceamento de carga e redundâncias dos sistemas.", "verification": "Evidência técnica da implementação de controlos adequados que permitam a resposta a disrupções de acordo com o Plano de Continuidade de Negócio. Evidência técnica da implementação de redundâncias técnicas nos sistemas críticos."}}}, "PR.RI-5": {"objective": "PR — Proteger", "category": "PR.RI — Resiliência da Infraestrutura Tecnológica", "statement": "A entidade planeia a capacidade adequada dos recursos para garantir a disponibilidade das suas redes e sistemas de informação.", "description": "A capacidade das redes e dos sistemas de informação é monitorizada e são efetuadas previsões sobre as necessidades de capacidade futura, para garantir que o desempenho dos sistemas está alinhado com os requisitos de prestação dos serviços críticos.", "measures": {"substancial": {"measure": "A entidade deve planear e disponibilizar a capacidade adequada dos recursos que processam o volume normal, atual e futuro, de informação dos sistemas críticos da entidade, redes, telecomunicações e armazenamento de dados.", "verification": "Registo do planeamento da capacidade dos recursos para o processamento de informações dos sistemas críticos, redes, telecomunicações e armazenamento de dados."}}}, "DE.MC-1": {"objective": "DE — Detetar", "category": "DE.MC — Monitorização Contínua de Segurança", "statement": "As redes e sistemas de informação são monitorizados para detetar potenciais incidentes.", "description": "A entidade efetua a monitorização da sua rede e dos seus sistemas de informação, incluindo nos seus sistemas de IA e outros, incluindo a ligação com sistemas externos dos quais depende, como serviços de computação em nuvem. A monitorização está integrada com o processo de gestão e correlação de eventos de segurança. A monitorização e avaliação permitem que a entidade verifique a necessidade de correções, melhorias e, quando necessário, as comunique às partes interessadas relevantes.", "measures": {"basico": {"measure": "Devem ser corretamente configuradas, instaladas e atualizadas soluções de monitorização de tráfego da rede, nomeadamente, através de firewalls e proteção contra atividade não autorizada e potencialmente maliciosa.", "verification": "Evidência técnica de instalação, configuração e atualização de soluções de monitorização de tráfego da rede e proteção contra atividade não autorizada e potencialmente maliciosa."}, "substancial": {"measure": "A entidade deve monitorizar, identificar e bloquear comunicações, locais e remotas, não autorizadas às suas redes e sistemas críticos e remover conteúdo malicioso.", "verification": "Evidência da monitorização, identificação e bloqueio de comunicações não autorizadas e conteúdo/ações malicioso/ maliciosas."}, "elevado": {"measure": "A entidade deve monitorizar os seus sistemas críticos de forma contínua para detetar eventos e indicadores de potenciais incidentes e automaticamente acionar mecanismos de resposta.", "verification": "Registo de monitorização contínua dos sistemas críticos quanto a potenciais incidentes."}}}, "DE.MC-2": {"objective": "DE — Detetar", "category": "DE.MC — Monitorização Contínua de Segurança", "statement": "O ambiente físico é monitorizado para possibilitar a deteção de potenciais incidentes de segurança.", "description": "A entidade garante que os seus perímetros de segurança física são monitorizados. A monitorização dos controlos de proteção física é inserida no processo de gestão e correlação de eventos de segurança, associados a categorização e tipificação específica.", "measures": {"substancial": {"measure": "A entidade deve monitorizar o ambiente físico para identificar eventos potencialmente adversos.", "verification": "Evidência técnica da monitorização do ambiente físico."}, "elevado": {"measure": "Para além da monitorização do acesso físico às instalações, a entidade deve monitorizar o acesso físico aos seus sistemas e dispositivos críticos, com alarmes de intrusão física, equipamento de vigilância e equipas de monitorização independentes.", "verification": "Evidência técnica da implementação de alarmes de intrusão física e equipamento de vigilância no acesso físico aos sistemas e dispositivos críticos. Registo de monitorização do acesso físico por equipas independentes."}}}, "DE.MC-3": {"objective": "DE — Detetar", "category": "DE.MC — Monitorização Contínua de Segurança", "statement": "A atividade do pessoal da entidade é monitorizada para se detetar potenciais incidentes.", "description": "A monitorização das atividades do pessoal da entidade está integrada no âmbito do processo de gestão e correlação de eventos de segurança. Esta atividade tem como objetivo recolher informação que possibilite uma atuação célere da entidade, no caso de existência de algum incidente que possa ter origem na atividade de um colaborador. A entidade garante também que a informação recolhida e o seu respetivo tratamento respeitam o enquadramento jurídico aplicável.", "measures": {}}, "DE.MC-4": {"objective": "DE — Detetar", "category": "DE.MC — Monitorização Contínua de Segurança", "statement": "A entidade identifica e implementa mecanismos para deteção de código malicioso.", "description": "A entidade implementa mecanismos que permitam a deteção e a prevenção de existência de atividade maliciosa nas suas redes e sistemas de informação.", "measures": {"basico": {"measure": "A entidade deve instalar e atualizar ferramentas de monitorização de postos cliente (endpoints) por forma a detetar atividade maliciosa", "verification": "Evidência técnica da instalação de ferramentas de monitorização de postos cliente, e da sua atualização."}}}, "DE.MC-5": {"objective": "DE — Detetar", "category": "DE.MC — Monitorização Contínua de Segurança", "statement": "A utilização de aplicações não autorizadas em dispositivos móveis é detetada.", "description": "A entidade é capaz de detetar instalações indevidas de aplicações nas suas redes e sistemas de informação. A deteção deste tipo de atividades está integrada no processo de gestão e correlação de eventos de segurança da entidade.", "measures": {"basico": {"measure": "A entidade deve definir uma lista de aplicações aprovadas para uso em ativos corporativos. Todas as exceções devem ser aprovadas e documentadas. Em caso de utilização de dispositivos pessoais para fins profissionais, a entidade deve definir, na sua Política de Uso Aceitável, critérios a utilização de dispositivos pessoais no trabalho (BYOD).", "verification": "Registo das aplicações aprovadas para uso em ativos corporativos. Documentação da aprovação das exceções. Registo da inclusão de critérios para a Utilização de Dispositivos Pessoais no Trabalho (BYOD) na Política de Uso Aceitável."}, "substancial": {"measure": "A entidade deve incluir requisitos para a utilização de dispositivos móveis corporativos na sua Política de Uso Aceitável e monitorizar o cumprimento dos mesmos, nomeadamente no processo de gestão de eventos.", "verification": "Registo documentado de inclusão na Política de Uso Aceitável de requisitos para a utilização de dispositivos móveis corporativos e registo da monitorização do cumprimento destes requisitos."}, "elevado": {"measure": "A entidade deve gerir a instalação e suporte de software numa ferramenta centralizada. A entidade deve criar alarmística relativamente à instalação de software indevido e integrar o processo de alarmística na gestão de incidentes.", "verification": "Evidência técnica da ferramenta centralizada de suporte de software. Evidência técnica de alarmística relativamente à instalação de software indevido e integração deste processo de gestão de incidentes."}}}, "DE.MC-6": {"objective": "DE — Detetar", "category": "DE.MC — Monitorização Contínua de Segurança", "statement": "As atividades dos prestadores de serviços externos são monitorizadas para deteção de incidentes.", "description": "As atividades dos prestadores de serviços externos são monitorizadas pela entidade, para detetar se as suas redes e sistemas de informação são acedidos sem autorização.", "measures": {"substancial": {"measure": "Todas as ligações aos sistemas, aplicações ou infraestrutura da entidade, efetuadas por fornecedores ou qualquer entidade externa, devem ser monitorizadas e protegidas por forma a detetar eventos potencialmente adversos. A entidade deve garantir a contínua conformidade dos prestadores de serviços com as suas políticas e procedimentos e com os requisitos de segurança previamente definidos em contratos ou acordos.", "verification": "Registo da monitorização de todas as ligações aos sistemas, aplicações ou infraestrutura da entidade, efetuadas por fornecedores ou qualquer entidade externa. Registo da avaliação periódica dos prestadores de serviços com acesso às redes e sistemas da entidade por forma a garantir o cumprimento dos requisitos de segurança previamente definidos."}}}, "DE.MC-7": {"objective": "DE — Detetar", "category": "DE.MC — Monitorização Contínua de Segurança", "statement": "O hardware, software, os ambientes em produção e os seus dados são monitorizados para detetar eventos potencialmente adversos.", "description": "A entidade utiliza mecanismos de verificação que garantam a integridade de hardware, software, firmware e respetivos dados. Estes controlos têm como objetivo detetar manipulações não autorizadas ou erros inesperados devido a má utilização.", "measures": {"substancial": {"measure": "O hardware, software, ambientes em produção e respetivos dados devem ser monitorizados para detetar eventos potencialmente adversos.", "verification": "Evidência técnica da recolha de eventos potencialmente adversos."}, "elevado": {"measure": "A entidade deve efetuar verificações da integridade do hardware dos seus sistemas críticos para detetar eventuais adulterações. A deteção de adulterações do hardware dos sistemas críticos deve ser incluída no Plano de Resposta a Incidentes. A entidade deve implementar um sistema de deteção e alerta de eventos de segurança, que permita identificar falsos positivos, com vista a uma melhor deteção e bloqueio de código ou atividades maliciosas.", "verification": "Evidência técnica da monitorização de integridade de hardware dos sistemas críticos. Registo da inclusão da deteção de adulteração de hardware dos sistemas críticos no Plano de Resposta a Incidentes. Evidência técnica da implementação de sistemas de deteção de falsos positivos na deteção e bloqueio de código e atividades maliciosas."}}}, "DE.AE-1": {"objective": "DE — Detetar", "category": "DE.AE — Anomalias e Eventos", "statement": "Os eventos detetados são analisados.", "description": "A entidade implementa um processo de gestão e de correlação de eventos de segurança que: 1) Suporta o seu processo de análise e tratamento de eventos; 2) Suporta o processo de identificação de possíveis incidentes.", "measures": {"substancial": {"measure": "A entidade deve analisar a informação recolhida sobre os eventos detetados para filtrar eventos com impacto potencialmente relevante e identificar respetivas origens, alvos e métodos de ataque.", "verification": "Evidência técnica da análise da informação sobre os eventos detetados."}, "elevado": {"measure": "A entidade deve implementar um sistema automatizado para agregação, correlação e análise dos eventos de segurança detetados.", "verification": "Evidência técnica da implementação de sistemas automatizados para agregação, correlação e análise dos eventos de segurança detetados."}}}, "DE.AE-2": {"objective": "DE — Detetar", "category": "DE.AE — Anomalias e Eventos", "statement": "Os eventos são recolhidos e correlacionados a partir de várias fontes e sensores.", "description": "A entidade implementa os mecanismos tecnológicos e processuais necessários, que permitam a recolha e correlação dos eventos gerados nas suas redes e sistemas de informação e nos dispositivos de segurança. Estes eventos devem ser correlacionados entre si e, se possível, enriquecidos com fontes de conhecimento externas sobre ameaças.", "measures": {"basico": {"measure": "A funcionalidade de recolha de eventos de segurança dos sistemas e aplicações deve estar ativa, e esta informação deve ser analisada e preservada através de cópias de segurança, durante um período previamente definido pela entidade.", "verification": "Evidência técnica da recolha sistemática de eventos. Evidência técnica da preservação da informação da análise de eventos através de cópias de segurança."}, "elevado": {"measure": "O sistema automatizado para agregação, correlação e análise de eventos de segurança da entidade deve considerar, para os eventos dos ativos críticos, as diversas fontes e sensores existentes. O sistema automatizado para agregação, correlação e análise de eventos de segurança da entidade deve integrar informação relativa a rastreamentos de vulnerabilidades e estatísticas de performance dos sistemas e aplicações.", "verification": "Registo da integração de toda a informação proveniente das diversas fontes e sensores existentes (incluindo rastreamentos de vulnerabilidades e estatísticas de performance dos sistemas e aplicações) para a agregação, correlação e análise dos eventos de segurança dos ativos críticos da entidade."}}}, "DE.AE-3": {"objective": "DE — Detetar", "category": "DE.AE — Anomalias e Eventos", "statement": "O impacto estimado e o âmbito dos eventos adversos detetados são compreendidos e identificados.", "description": "A entidade efetua uma categorização e tipificação dos eventos, por forma a aferir qual o impacto dos mesmos sobre as suas redes e sistemas de informação. A categorização dos eventos irá suportar a entidade no processo de decisão sobre que ações desencadear para cada tipo de evento. Os eventos poderão dar origem a incidentes.", "measures": {"elevado": {"measure": "Os potenciais impactos dos eventos de segurança detetados no normal funcionamento da entidade, nas operações, nos ativos ou nas pessoas devem ser tidos em conta durante o processo de gestão dos riscos.", "verification": "Registo documentado da revisão do processo de gestão dos riscos tendo em o impacto dos eventos de segurança detetados."}}}, "DE.AE-4": {"objective": "DE — Detetar", "category": "DE.AE — Anomalias e Eventos", "statement": "As informações sobre deteções de eventos são comunicadas.", "description": "A entidade define uma estratégia de comunicação, que mantenha informadas as partes interessadas relevantes sobre a ocorrência de eventos. A estratégia é suportada num Plano de Comunicação que poderá ser consolidado com os outros planos de comunicação que a entidade disponha.", "measures": {"substancial": {"measure": "As informações sobre eventos adversos devem ser disponibilizadas ao pessoal autorizado e configuradas nos sistemas relevantes para a devida deteção, investigação e resposta.", "verification": "Registo da disponibilização da informação sobre eventos adversos ao pessoal autorizado."}}}, "DE.AE-5": {"objective": "DE — Detetar", "category": "DE.AE — Anomalias e Eventos", "statement": "As informações sobre ciberameaças e outras informações contextuais são integradas na análise de eventos.", "description": "A entidade incorpora a informação sobre ameaças provenientes de fontes de conhecimento legítimas e relevantes ao contexto do evento para a sua análise. Estes dados permitem uma maior clareza relativamente a potenciais táticas, técnicas e procedimentos utilizados por potenciais atacantes possibilitando uma análise mais aprofundada e fundamentada do contexto do(s) evento(s) para a determinação duma resposta mais direcionada e eficaz. Esta análise capacita a entidade em termos de resposta, priorização e mitigação de eventos de segurança potencialmente disruptivos às suas operações.", "measures": {}}, "DE.AE-6": {"objective": "DE — Detetar", "category": "DE.AE — Anomalias e Eventos", "statement": "Os critérios para a declaração de incidentes são definidos", "description": "Tendo como base a tipificação e categorização dos eventos do seu sistema de gestão e correlação de eventos de segurança, a entidade define quais são os critérios que devem justificar a necessidade de abertura de incidentes.", "measures": {"basico": {"measure": "A entidade deve definir os limites a considerar quando um evento, conjunto de eventos ou correlação de múltiplos eventos, configura um incidente.", "verification": "Registo da definição dos limites que determinam quando um evento ou correlação de múltiplos eventos configura um incidente."}}}, "RS.GI-1": {"objective": "RS — Responder", "category": "RS.GI — Gestão de Incidentes", "statement": "O Plano de Resposta a Incidentes é executado, em coordenação com as partes interessadas, durante ou após a ocorrência de um incidente.", "description": "A entidade sistematiza o seu Plano de Resposta a Incidentes, em coordenação com as partes interessadas, por forma a garantir uma correta alocação de recursos (humanos, tecnológicos e processuais) na resolução do mesmo. A resolução dos incidentes segue um processo sistematizado, no âmbito do qual é identificado um responsável pelo seu tratamento. No processo de análise de evidências de um incidente, é relevante garantir-se a integridade das evidências analisadas e recolhidas.", "measures": {"basico": {"measure": "O Plano de Resposta a Incidentes deve incluir as funções, as responsabilidades e as competências dos envolvidos e deve ser executado durante ou logo após um incidente.", "verification": "Registo da inclusão das funções, responsabilidades e competências dos envolvidos no Plano de Resposta a Incidentes."}, "substancial": {"measure": "As ações de resposta a incidentes devem ser coordenadas com as partes interessadas definidas no Plano de Resposta a Incidentes.", "verification": "Registo documentado do planeamento e atualização dos processos de resposta a incidentes que incluam requisitos para escalonamento."}}}, "RS.GI-2": {"objective": "RS — Responder", "category": "RS.GI — Gestão de Incidentes", "statement": "As notificações dos sistemas de deteção são triadas e validadas.", "description": "A entidade garante que as notificações de incidentes originados nos sistemas de deteção (internos ou externos) ou fora da entidade são analisados, categorizados e tratados de forma sistematizada.", "measures": {"substancial": {"measure": "As notificações de incidentes devem ser triadas e validadas de acordo com o Plano de Resposta a Incidentes da entidade.", "verification": "Registo da triagem e validação das notificações de incidentes."}}}, "RS.GI-3": {"objective": "RS — Responder", "category": "RS.GI — Gestão de Incidentes", "statement": "Os incidentes são categorizados de acordo com o Plano de Resposta a Incidentes definido.", "description": "A entidade garante que a categorização dos incidentes é efetuada de acordo com as regras definidas no seu Plano de Resposta a Incidentes.", "measures": {"substancial": {"measure": "A entidade deve garantir que os incidentes de cibersegurança são categorizados de acordo com o nível de gravidade e impacto, e com os critérios de avaliação incluídos no Plano de Resposta a Incidentes. A entidade deve utilizar uma taxonomia de categorização de incidentes.", "verification": "Registo da categorização de incidentes e a sua classificação, de acordo com a taxonomia de categorização de incidentes."}, "elevado": {"measure": "O Plano de Resposta a Incidentes deve descrever os procedimentos de resposta para os diferentes tipos de incidente definidos na taxonomia de categorização de incidentes. Devem ser utilizadas ferramentas automatizadas para apoiar na investigação e a avaliação do impacto de incidentes previamente validados.", "verification": "Registo documentado da inclusão de procedimentos de resposta a diferentes tipos de incidente, no Plano de Resposta a Incidentes. Evidência técnica da implementação de ferramentas automatizadas de apoio à investigação e avaliação do impacto de incidentes."}}}, "RS.GI-4": {"objective": "RS — Responder", "category": "RS.GI — Gestão de Incidentes", "statement": "Os incidentes são escalados ou elevados conforme necessário.", "description": "A entidade implementa um processo de coordenação e de escalonamento de incidentes, alinhado com a categorização e criticidade dos mesmos.", "measures": {}}, "RS.GI-5": {"objective": "RS — Responder", "category": "RS.GI — Gestão de Incidentes", "statement": "São aplicados os critérios para iniciar a recuperação de incidentes.", "description": "A entidade aplica os critérios definidos para dar início aos procedimentos de recuperação de incidentes, às caraterísticas conhecidas e presumíveis do incidente.", "measures": {"substancial": {"measure": "Os critérios para iniciar a recuperação de incidentes devem estar definidos e ser aplicados.", "verification": "Registo de critérios e evidência da sua aplicação na fase inicial da recuperação de incidentes."}}}, "RS.AI-1": {"objective": "RS — Responder", "category": "RS.AI — Análise de Incidentes", "statement": "É realizada uma análise forense para determinar o que ocorreu durante um incidente e a sua causa raiz.", "description": "A entidade cria as condições necessárias para que lhe seja possível efetuar análises forenses, no âmbito do processo de resposta a incidentes.", "measures": {"elevado": {"measure": "A entidade deve realizar análises forenses dos artefactos recolhidos para determinar a causa raiz do incidente. A entidade deve garantir a existência de mecanismos ondemand, internos ou externos para a realização de análises forenses.", "verification": "Registo documentado da realização de análises forenses."}}}, "RS.AI-2": {"objective": "RS — Responder", "category": "RS.AI — Análise de Incidentes", "statement": "As ações realizadas durante uma investigação são registadas e a integridade e proveniência dos registos são preservadas.", "description": "A entidade garante que todas as ações realizadas durante a investigação de um incidente são documentadas e que estes registos são protegidos de forma a garantir a sua integridade. Esta preservação é essencial para a realização de análises forenses e para demonstrar que foram tomadas as diligências necessárias para uma resposta eficaz ao incidente.", "measures": {"elevado": {"measure": "As ações realizadas durante uma investigação devem ser registadas e a integridade e a proveniência dos registos devem ser preservadas.", "verification": "Registo documentado das ações realizadas durante a investigação dos incidentes."}}}, "RS.AI-3": {"objective": "RS — Responder", "category": "RS.AI — Análise de Incidentes", "statement": "Os dados e metadados do incidente são recolhidos, e a sua integridade e proveniência são preservadas.", "description": "A entidade recolhe dados e metadados das investigações realizadas dos incidentes, e dos dados analisados. A entidade preserva os dados e garante a sua integridade.", "measures": {"elevado": {"measure": "Os dados e metadados dos incidentes devem ser recolhidos e armazenados e a sua autenticidade, exatidão e rastreabilidade são protegidas.", "verification": "Evidência do armazenamento dos dados e metadados dos incidentes e da implementação de mecanismos que garantam a preservação da integridade e proveniência dos mesmos."}}}, "RS.AI-4": {"objective": "RS — Responder", "category": "RS.AI — Análise de Incidentes", "statement": "O impacto do incidente é estimado e validado.", "description": "No processo de categorização dos incidentes, a entidade avalia o impacto que os incidentes causam aos seus ativos e, consequentemente, à sua operação, utilizando essa avaliação para definir qual a severidade a atribuir ao incidente.", "measures": {"elevado": {"measure": "O resultado da análise de incidentes deve ser considerado na avaliação de impacto do incidente em causa.", "verification": "Registo da inclusão dos resultados da análise das investigações realizadas, na avaliação de impacto do incidente."}}}, "RS.NC-1": {"objective": "RS — Responder", "category": "RS.NC — Notificação e Comunicação de Incidentes", "statement": "As partes interessadas internas e externas são notificadas dos incidentes.", "description": "A entidade define canais adequados para que os incidentes sejam reportados às partes interessadas relevantes, e identifica quais as partes interessadas que devem ser informadas dos incidentes. No processo de resposta a um incidente, a entidade identifica qual a informação que tem de ser partilhada com as partes interessadas externas.", "measures": {"basico": {"measure": "A entidade deve comunicar ao seu pessoal, de forma clara e simples, a ocorrência de incidentes. Os incidentes com impacto significativo devem ser notificados à autoridade competente nos termos do Regime Jurídico da Cibersegurança.", "verification": "Evidência da partilha de informações quanto à ocorrência de incidentes."}, "substancial": {"measure": "A entidade deve partilhar informação sobre incidentes com as partes interessadas externas relevantes dentro do prazo estabelecido no seu Plano de Resposta a Incidentes.", "verification": "Registo da partilha de informações sobre incidentes com as partes interessadas externas relevantes."}}}, "RS.NC-2": {"objective": "RS — Responder", "category": "RS.NC — Notificação e Comunicação de Incidentes", "statement": "Existe partilha voluntária de informação com partes interessadas externas.", "description": "A entidade partilha, de forma voluntária, informações sobre os incidentes a grupos de interesse, para que estes possam beneficiar da partilha e melhorar tempos de resposta para identificar, detetar, conter e erradicar essas ameaças na sua circunscrição e no seu círculo de influência.", "measures": {}}, "RS.MI-1": {"objective": "RS — Responder", "category": "RS.MI — Mitigação", "statement": "Os incidentes são contidos.", "description": "A entidade define processos e procedimentos sistematizados para resolução e tratamento de incidentes que lhe permitam conter, efetivamente, os incidentes ocorridos.", "measures": {"substancial": {"measure": "A entidade deve conter e resolver os incidentes. As decisões de não contenção e não resolução de incidentes devem ser documentadas.", "verification": "Evidência dos processos de contenção de incidentes. Registo de decisões tomadas durante o processo de resposta."}}}, "RS.MI-2": {"objective": "RS — Responder", "category": "RS.MI — Mitigação", "statement": "Os incidentes são resolvidos.", "description": "A entidade possui processos e procedimentos sistematizados para resolução e tratamento de incidentes que lhe permitam indicar que os incidentes são, efetivamente, resolvidos.", "measures": {"elevado": {"measure": "O Plano de Resposta a Incidentes deve conter critérios que permitam declarar a conclusão da resolução do incidente.", "verification": "Registo da inclusão de critérios para declarar a conclusão da resolução do incidente no Plano de Resposta a Incidentes."}}}, "RC.PR-1": {"objective": "RC — Recuperar", "category": "RC.PR — Plano de Recuperação", "statement": "A entidade segue um plano de recuperação durante ou após um incidente.", "description": "A entidade sistematiza o seu processo de recuperação de incidentes, por forma a garantir uma correta alocação de recursos (humanos/tecnológicos e processuais) à resolução dos mesmos. No processo de recuperação de um incidente é relevante garantir a integridade e disponibilidade dos sistemas.", "measures": {"basico": {"measure": "Devem ser desenvolvidos e executados procedimentos de recuperação de incidentes, de acordo com o Plano de Resposta a Incidentes.", "verification": "Registo das ações tomadas em resposta a incidentes."}}}, "RC.PR-2": {"objective": "RC — Recuperar", "category": "RC.PR — Plano de Recuperação", "statement": "As ações de recuperação são definidas, priorizadas e executadas.", "description": "A entidade garante que todas as ações de recuperação de incidentes são ponderadas, planeadas e selecionadas com base no seu âmbito, prioridade e impacto para a entidade. É realizada uma abordagem estruturada e atempada para a recuperação dos sistemas, serviços e operações afetadas.", "measures": {}}, "RC.PR-3": {"objective": "RC — Recuperar", "category": "RC.PR — Plano de Recuperação", "statement": "A integridade das cópias de segurança e de outros ativos de restauro é verificada antes da sua utilização.", "description": "A entidade verifica a integridade e autenticidade das cópias de segurança e de outros ativos usados no âmbito da recuperação pós-incidentes, antes destes serem colocados novamente em operação. Esta verificação assegura que os elementos para recuperação não estão comprometidos ou corrompidos, reduzindo o risco de prolongar o tempo de recuperação ou situações de reincidência de incidentes.", "measures": {"basico": {"measure": "A integridade das cópias de segurança deve ser verificada antes da sua utilização no âmbito da recuperação pós incidente.", "verification": "Registo das ações tomadas em resposta a incidentes, que inclua a verificação da integridade das cópias de segurança."}}}, "RC.PR-4": {"objective": "RC — Recuperar", "category": "RC.PR — Plano de Recuperação", "statement": "A entidade considera os seus serviços críticos e a gestão dos riscos de cibersegurança para estabelecer normas operacionais pós-incidente.", "description": "A entidade considera as conclusões retiradas de situações pós-incidente para redefinir, caso aplicável, as suas funções de missão crítica (e respetivas práticas operacionais) e postura de risco (incluindo novas vulnerabilidades identificadas pós-incidente). A entidade reflete quais as suas funções e operações mais críticas e prioritárias e pondera aumentar a sua ciberresiliência.", "measures": {}}, "RC.PR-5": {"objective": "RC — Recuperar", "category": "RC.PR — Plano de Recuperação", "statement": "A integridade dos ativos restaurados é verificada, os sistemas e serviços são restaurados e o estado de normal funcionamento é confirmado.", "description": "Definição Após um incidente a entidade verifica a integridade dos ativos que foram restaurados antes dos mesmos serem colocados em funcionamento. A entidade restaura os sistemas e serviços e confirma o estado operacional normal dos mesmos.", "measures": {"substancial": {"measure": "A integridade dos ativos restaurados deve ser verificada, os sistemas e serviços devem ser recuperados e o seu estado de normal funcionamento deve ser confirmado.", "verification": "Registo do processo de verificação da integridade dos ativos, recuperação de sistemas e serviços e confirmação do normal estado de funcionamento."}}}, "RC.PR-6": {"objective": "RC — Recuperar", "category": "RC.PR — Plano de Recuperação", "statement": "O fim da recuperação do incidente é documentado e declarado com base em critérios predefinidos.", "description": "Tendo por base procedimentos e processos de gestão de incidentes, a entidade declara o fim da recuperação do incidente, baseando-se em critérios específicos. Para dar como terminada a recuperação do incidente, a entidade garante que toda a documentação relacionada com o incidente é concluída.", "measures": {"substancial": {"measure": "O fim da recuperação do incidente deve ser documentado e declarado com base em critérios prédefinidos.", "verification": "Registo da definição de critérios para a declaração do fim da recuperação do incidente e evidência da sua implementação."}}}, "RC.CO-1": {"objective": "RC — Recuperar", "category": "RC.CO — Comunicações", "statement": "As atividades de recuperação são comunicadas às partes interessadas, bem como aos órgãos de gestão, direção e administração.", "description": "A entidade garante que as partes interessadas, internas e externas, são informadas quanto às atividades de recuperação e progressos no restauro para garantir o normal funcionamento dos sistemas e aplicações da entidade, após a ocorrência de incidentes. A entidade define uma estratégia de comunicação baseada num plano de comunicação produzido para o efeito. Este poderá ser consolidado com outros planos de comunicação existentes na entidade.", "measures": {"substancial": {"measure": "As atividades de recuperação e os progressos no restauro do normal funcionamento dos sistemas e aplicações da entidade, devem ser comunicados às partes interessadas internas e externas.", "verification": "Registo da comunicação das atividades de recuperação e progresso do restauro, às partes interessadas, internas e externas."}}}, "RC.CO-2": {"objective": "RC — Recuperar", "category": "RC.CO — Comunicações", "statement": "As atualizações sobre a recuperação de incidentes são partilhadas utilizando métodos aprovados pela entidade.", "description": "A entidade comunica o que é relevante no contexto de cibersegurança. O fluxo de comunicação deve ser controlado pela entidade para minimizar potenciais impactos na sua credibilidade e reputação. A entidade define uma estratégia de comunicação, que se poderá basear noutras estratégias/ panos de comunicação existentes na entidade.", "measures": {"substancial": {"measure": "As atualizações públicas sobre a recuperação do incidente devem ser partilhadas utilizando métodos de comunicação definidos e aprovados pela entidade.", "verification": "Registo dos procedimentos para a comunicação de atualizações públicas sobre a recuperação de incidentes."}, "elevado": {"measure": "A entidade deve implementar uma estratégia de comunicação de crise para mitigar os impactos negativos durante uma crise.", "verification": "Registo documentado da estratégia de comunicação para situações de crise."}}}}, "epr": {"A": [{"code": "O.PSI", "area": "Política de Cibersegurança", "measure": "A entidade deve definir uma Política de Cibersegurança que determine o compromisso da entidade para com a cibersegurança.", "verification": "Política de Cibersegurança aprovada e implementada."}, {"code": "O.IAC", "area": "Inventariação dos ativos", "measure": "A entidade deve inventariar todos os seus ativos e identificar as dependências entre os mesmos. A entidade deve atualizar o inventário regularmente.", "verification": "Inventário completo e atualizado dos ativos."}, {"code": "O.PAP", "area": "Política de acessos e permissões.", "measure": "A entidade deve definir e implementar uma Política de Gestão de Acessos e Permissões.", "verification": "Política de Gestão de Acessos e Permissões aprovada e implementada."}, {"code": "O.GEC", "area": "Gestão de equipamentos computacionais.", "measure": "A entidade deve garantir a segregação de dispositivos móveis/eletrónicos pessoais dos dispositivos corporativos.", "verification": "Evidência técnica da segregação de redes."}, {"code": "O.PUA", "area": "Política(s) de utilização aceitável.", "measure": "A entidade deve definir e disponibilizar junto de todos o pessoal a Política de Utilização Aceitável, que seja abrangente para toda a entidade e que defina as regras para a utilização segura e responsável dos seus ativos. Esta Política deve incluir requisitos de segurança para a proteção da confidencialidade e integridade dos ficheiros em circulação entre entidades.", "verification": "Política de Utilização Aceitável aprovada e implementada."}, {"code": "O.PP", "area": "Política de palavra-passe", "measure": "A entidade deve definir uma Política para Gestão das suas palavras-passe.", "verification": "Política de Palavra-passe aprovada e implementada."}, {"code": "O.PCF", "area": "Processo de Classificação da Informação.", "measure": "A entidade deve definir um processo de classificação da informação, que permita identificar os critérios/ níveis de sensibilidade relativamente aos seus dados.", "verification": "Registo documentado da classificação da informação."}, {"code": "O.GMO", "area": "Gestão da mudança organizacional.", "measure": "A entidade deve definir e implementar procedimentos de atualização ao nível das TIC, aquando da entrada, alteração e saída de pessoal, e sincronizá-las com a área de recursos humanos.", "verification": "Registo documentado dos procedimentos quanto a ações a executar quando existe a saída ou mudança de funções de pessoal."}, {"code": "O.ID", "area": "Identificação de funções ou atividades críticas.", "measure": "A entidade deve identificar as funções ou atividades críticas e as dependências existentes das TIC.", "verification": "Registo documentado da identificação de funções ou atividades críticas, dos ativos que as suportam e da relação e/ou dependência que entre eles se estabelece."}, {"code": "O.PSF", "area": "Política de Segurança de fornecedores.", "measure": "A entidade deve definir e implementar uma Política de Segurança de Fornecedores que determine os mecanismos de avaliação de risco da cadeia de abastecimento e os critérios de aceitação.", "verification": "Política de Segurança de Fornecedores aprovada e implementada."}, {"code": "T.PPT", "area": "Proteção de postos de trabalho", "measure": "A entidade deve implementar mecanismos de controlo de acesso dos postos de trabalho, assim como cópias de segurança da respetiva informação.", "verification": "Evidência técnica da implementação de controlo de acesso dos postos de trabalho. Evidência técnica da execução de cópias de segurança."}, {"code": "T.PPT", "area": "Perfil de trabalho nos dispositivos móveis.", "measure": "A entidade deve garantir que a informação corporativa apenas é acedida através de um perfil de trabalho nos dispositivos móveis.", "verification": "Evidência técnica da configuração do perfil de trabalho para acesso a aplicações corporativas."}, {"code": "T.GP", "area": "Gestão de palavras-passe", "measure": "A entidade deve garantir que as palavras-passe para acessos privilegiados se encontram armazenadas através de uma solução para a gestão de palavras-passe.", "verification": "Evidência técnica da implementação de uma solução para a gestão das palavras-passe para acessos privilegiados."}, {"code": "T.PAD", "area": "Privilégios de acesso diferenciados.", "measure": "A entidade deve garantir que os acessos e permissões são concedidos de acordo com o princípio da necessidade de conhecer e com o princípio do menor privilégio, e em conformidade com a Política de Gestão de Acessos e Permissões.", "verification": "Registo documentado da identificação de acessos a sistemas e aplicações por perfil funcional, em conformidade com a Política de Gestão de Acessos e Permissões."}, {"code": "T.AS", "area": "Atualizações de segurança", "measure": "A entidade deve garantir a aplicação atempada de todas atualizações de segurança de acordo com as recomendações dos fabricantes nos seus dispositivos de hardware.", "verification": "Registo documentado da atualização dos equipamentos hardware."}, {"code": "T.AM", "area": "Autenticação multifator", "measure": "A entidade deve ativar a autenticação multifator nas suas aplicações críticas.", "verification": "Evidência técnica da implementação de autenticação multifator em aplicações críticas."}, {"code": "T.PEW", "area": "Proteção Correio Eletrónico e Serviços Web.", "measure": "A entidade deve garantir que são aplicadas as melhores práticas a nível de segurança de correio eletrónico e páginas de Internet.", "verification": "Evidência técnica da implementação de mecanismos de segurança para autenticação e validação do correio eletrónico e utilização de protocolos seguros, certificados digitais e configuração dos cabeçalhos de segurança nas páginas de Internet."}, {"code": "T.CS", "area": "Cópias de segurança", "measure": "A entidade deve segregar o armazenamento das cópias de segurança do ambiente protegido.", "verification": "Evidência técnica da segregação do armazenamento das cópias de segurança."}, {"code": "T.RAR", "area": "Recolha e armazenamento de registos.", "measure": "A entidade deve garantir a salvaguarda dos logs dos sistemas operativos, aplicações e outros dispositivos.", "verification": "Evidência técnica da recolha de logs."}, {"code": "T.SC", "area": "Securização (hardening) de configurações.", "measure": "A entidade deve garantir que são implementadas práticas de segurança ao nível do posto de trabalho, das configurações do sistema operativo e principais aplicações utilizadas.", "verification": "Evidência técnica da implementação das melhores práticas de segurança."}, {"code": "H.EC", "area": "Realização de exercícios de phishing.", "measure": "A entidade deve garantir a realização periódica de exercícios de phishing, que permitam avaliar o grau de preparação do seu pessoal.", "verification": "Registo documentado dos resultados dos exercícios realizados, assim como as conclusões e iniciativas com base nesses resultados."}, {"code": "H.PF", "area": "Plano de formação", "measure": "A entidade deve estabelecer um plano de ações de formação em cibersegurança, bem como definir os processos e procedimentos necessários para garantir a sua correta implementação.", "verification": "Registos documentado da definição dos planos e ações de formação."}], "B": [{"code": "O.CRI", "area": "Identificação de ponto de contacto para resposta a incidentes.", "measure": "A entidade deve identificar um ponto de contacto para a resposta a incidentes. A pessoa identificada deve ser capaz de responder a eventuais solicitações externas, e, caso seja necessário, ter disponibilidade para contactos de emergência fora do horário de expediente.", "verification": "Evidência documental sobre o ponto de contacto."}, {"code": "O.IAC", "area": "Inventariação dos ativos críticos.", "measure": "A entidade deve inventariar os seus ativos críticos para a execução da sua atividade principal, deve ainda identificar as dependências entre os ativos críticos. A entidade deve atualizar o inventário de ativos críticos regularmente.", "verification": "Inventário atualizado dos ativos críticos."}, {"code": "O.GAP", "area": "Gestão de acessos e permissões.", "measure": "A entidade deve assegurar que os novos acessos, alteração e revogação dos mesmos são acompanhados por um pedido/aprovação.", "verification": "Evidência da gestão dos pedidos e respetivas aprovações."}, {"code": "O.GEC", "area": "Gestão de equipamentos computacionais.", "measure": "A entidade deve documentar e atualizar a atribuição e recolha dos equipamentos computacionais.", "verification": "Registo documentado da atribuição e recolha de equipamentos computacionais."}, {"code": "O.PSF", "area": "Política de Segurança de fornecedores.", "measure": "A entidade deve inventariar os fornecedores com acesso a sistemas de informação e obter contactos para notificação de incidentes de cibersegurança.", "verification": "Evidência documental da lista de fornecedores."}, {"code": "T.GPT", "area": "Gestão de Sistemas, Aplicações e Postos de Trabalho.", "measure": "A entidade deve garantir que são aplicados controlos de segurança nos sistemas, aplicações e postos de trabalho.", "verification": "Evidência técnica da implementação de controlos de segurança nos sistemas, aplicações e postos de trabalho."}, {"code": "T.PPT", "area": "Proteção de postos de trabalho", "measure": "A entidade deve garantir que se encontra instalado um antivírus nos seus postos de trabalho e servidores.", "verification": "Evidência técnica da implementação de antivírus nos postos de trabalho e servidores."}, {"code": "T.AR", "area": "Acesso remoto à entidade", "measure": "A entidade deve garantir que o acesso remoto é efetuado via mecanismo de acesso seguro (e.g. VPN, VDI) e autorizado através de um segundo fator de autenticação (MFA).", "verification": "Evidência técnica da implementação de mecanismo de acesso seguro para acessos remotos e que requeira segundo fator de autenticação."}, {"code": "T.PAS", "area": "Perfil de Administração Segregado.", "measure": "A entidade deve garantir a disponibilização de diferentes utilizadores dependendo da necessidade de acesso aplicacional ou de administração.", "verification": "Evidência documentada da segregação das contas de utilizadores das contas de perfil de administração."}, {"code": "T.AS", "area": "Atualizações de segurança", "measure": "A entidade deve garantir atempadamente a aplicação de todas atualizações de segurança de acordo com as recomendações dos fabricantes nos sistemas operativos e componentes de software nos seus postos de trabalho e servidores de suporte.", "verification": "Registo documentado de atualização dos sistemas operativos e componentes de software."}, {"code": "T.PEW", "area": "Proteção Correio Eletrónico e Serviços Web.", "measure": "A entidade deve garantir que aplica as melhores práticas a nível de segurança de correio eletrónico e páginas de Internet.", "verification": "Evidência técnica da implementação de mecanismos de segurança para autenticação do correio eletrónico e utilização de protocolos seguros e certificados digitais nas páginas de Internet."}, {"code": "T.CS", "area": "Cópias de segurança", "measure": "A entidade deve efetuar cópias de segurança e garantir que estas podem ser utilizadas, caso seja necessário.", "verification": "Evidência técnica da execução de cópias de segurança."}, {"code": "T.RAR", "area": "Recolha e armazenamento de registos.", "measure": "A entidade deve garantir a ativação dos registos definidos por defeito em sistemas operativos, aplicações e outros dispositivos.", "verification": "Evidência técnica da ativação dos registos por defeito em sistemas operativos, aplicações e outros dispositivos."}, {"code": "T.PPL", "area": "Proteção perimetral da infraestrutura lógica.", "measure": "A entidade deve garantir a proteção perimetral de infraestrutura.", "verification": "Evidência técnica da implementação das medidas de segurança lógica ao nível dos equipamentos."}, {"code": "T.PPF", "area": "Proteção perimetral da infraestrutura física.", "measure": "A entidade deve garantir a proteção física dos componentes da infraestrutura que alojam infraestrutura crítica (e.g. Centro de Processamento de Dados).", "verification": "Evidência técnica da implementação das medidas de segurança física ao nível dos espaços afetos à infraestrutura crítica."}, {"code": "T.MA", "area": "Mecanismos de autenticação", "measure": "A entidade deve implementar uma Política para garantir uma robustez adequada em relação à complexidade das suas palavras passe.", "verification": "Evidência da implementação operacional da Política de complexidade de palavras passe nas plataformas tecnológicas."}, {"code": "H.PF", "area": "Sensibilização e Formação", "measure": "A entidade deve estabelecer ações de sensibilização e/ou formação em cibersegurança.", "verification": "Registo documentado das ações de sensibilização e/ou formação."}, {"code": "H.FIC", "area": "Fontes de informação e canais de comunicação.", "measure": "A entidade deve garantir que existe consulta regular de fontes de informação e o acesso a canais de comunicação fidedignos quanto a ameaças de cibersegurança.", "verification": "Evidências dos canais de pesquisa e disseminação de informação sobre ameaças de cibersegurança."}]}, "rjc": {"25.º": {"title": "Obrigações dos órgãos de gestão, direção e administração", "text": "1 — Os órgãos de gestão, direção e administração das entidades essenciais e importantes:\na) Aprovam as medidas de gestão dos riscos de cibersegurança, adotadas em conformidade com o artigo 27.º;\nb) Supervisionam a aplicação das medidas de gestão dos riscos de cibersegurança;\nc) Asseguram o cumprimento das medidas de supervisão e de execução, a que se refere o capítulo vi;\nd) Asseguram a realização, com uma periodicidade regular, de ações de formação em cibersegurança, de forma a promover uma cultura de gestão interna sobre práticas de gestão dos riscos de cibersegurança.\n2 — Os titulares dos órgãos de gestão, direção e administração podem responder por ação ou omissão, com dolo ou culpa grave, nos termos da legislação aplicável, pelas infrações previstas no presente decreto-lei.\n3 — A responsabilidade e poderes necessários para o cumprimento das obrigações referidas no presente artigo não podem ser delegados, exceto num dos titulares dos órgãos de gestão, direção e administração."}, "26.º": {"title": "Sistema de gestão de riscos de cibersegurança", "text": "1 — As entidades essenciais e importantes são responsáveis por garantir a segurança das redes e dos sistemas de informação, tomando as medidas técnicas, operacionais e organizativas adequadas para gerir os riscos que se colocam à segurança das redes e dos sistemas de informação que utilizam nas suas operações e para impedir ou minimizar o impacto de incidentes nos destinatários dos seus serviços e noutros serviços.\n2 — As medidas de cibersegurança adotadas devem basear-se numa abordagem sistémica que abranja todos os riscos para as entidades essenciais e importantes e que vise proteger todos os ativos que garantam a continuidade do funcionamento das redes e os sistemas de informação que suportam os serviços essenciais, incluindo o seu ambiente físico, contra incidentes.\n3 — As medidas devem ainda:\na) Garantir um nível de segurança das redes e dos sistemas de informação adequado ao risco em causa, tendo em conta os progressos técnicos mais recentes e, se aplicáveis, as normas europeias e internacionais pertinentes, bem como os custos de execução e a viabilidade financeira destes; e\nb) Ser proporcionais ao grau de exposição da entidade aos riscos, a dimensão da entidade e a probabilidade de ocorrência de incidentes e a sua gravidade, incluindo o seu impacto social e económico, segundo os critérios técnicos que venham a ser definidos pelo CNCS.\n4 — De forma a orientar a política de gestão de riscos de cibersegurança por parte das entidades essenciais e importantes, o CNCS pode emitir instruções técnicas de harmonização e, sempre que necessário, elaborar e atualizar a matriz de risco aplicável àquelas entidades.\n5 — Considerando o setor de atividade e a dimensão da entidade e a matriz de risco definida, o CNCS, através de regulamento a aprovar pelo CNCS, define medidas de cibersegurança mínimas e específicas e níveis de conformidade a adotar pelas entidades essenciais e entidades importantes.\n6 — As medidas de cibersegurança mínimas não prejudicam a adoção de outras medidas que sejam necessárias e proporcionais, em resultado da análise e gestão dos riscos residuais de cibersegurança, nos termos do artigo seguinte.\n7 — As entidades públicas relevantes devem adotar as medidas técnicas, operacionais e organizativas adequadas que sejam determinadas pelo CNCS, de acordo com o grupo a que pertençam, nos termos do artigo 33.º\n8 — Sempre que seja alterada a qualificação das entidades, nos termos do artigo 8.º, ou as medidas de cibersegurança mínimas previstas no n.º 5 do presente artigo, em função da atualização da matriz de risco, as entidades essenciais e importantes dispõem de um prazo de seis meses para a respetiva adaptação à nova qualificação ou às novas medidas de cibersegurança mínimas, podendo o prazo ser prorrogado até um ano pela Autoridade Nacional de Cibersegurança, mediante pedido fundamento da entidade."}, "27.º": {"title": "Medidas de cibersegurança", "text": "1 — As medidas de cibersegurança a adotar pelas entidades essenciais e importantes, tendo em consideração a matriz de risco em que estiverem inseridas nos termos do artigo anterior, abrangem, designadamente, as seguintes áreas:\na) Tratamento de incidentes;\nb) Continuidade das atividades, como a gestão de cópias de segurança e a recuperação de desastres, e gestão de crises;\nc) Segurança da cadeia de abastecimento, incluindo aspetos de segurança respeitantes às relações entre cada entidade e os respetivos fornecedores ou prestadores de serviços diretos;\nd) Segurança na aquisição, desenvolvimento e manutenção das redes e sistemas de informação, incluindo o tratamento e a divulgação de vulnerabilidades;\ne) Políticas e procedimentos para avaliar a eficácia das medidas de gestão dos riscos de cibersegurança;\nf) Práticas básicas de ciber-higiene e formação em cibersegurança, incluindo os titulares de órgãos máximos de gestão e trabalhadores;\ng) Políticas e procedimentos relativos à utilização de criptografia e, se for caso disso, de cifragem, sem prejuízo das competências conferidas a outras entidades em matéria de criptografia no âmbito nacional ou perante outras organizações internacionais de que Portugal seja membro;\nh) Segurança dos recursos humanos, políticas seguidas em matéria de controlo do acesso e gestão de ativos;\ni) Utilização de autenticação multifator ou de autenticação contínua, comunicações seguras e sistemas seguros de comunicações de emergência no seio da entidade.\n2 — As entidades essenciais e importantes devem adotar ainda, sem demora injustificada, todas as medidas de cibersegurança corretivas necessárias, adequadas e proporcionais, que sejam indispensáveis ao suprimento de falhas ou omissões no cumprimento das medidas previstas no número anterior.\n3 — As autoridades nacionais setoriais de cibersegurança podem emitir disposições regulamentares para adoção de medidas de cibersegurança específicas do sector, sem prejuízo do disposto no n.º 3 do artigo 20.º"}, "29.º": {"title": "Gestão do risco residual", "text": "1 — As entidades essenciais e importantes devem realizar uma análise e gestão de riscos em relação a todos os ativos que garantam a continuidade do funcionamento das redes e sistemas de informação que utilizam, incluindo aos ativos que garantam a prestação dos serviços essenciais, com a periodicidade e os elementos técnicos e documentais a definir por regulamento da autoridade de cibersegurança competente, para além do cumprimento das medidas de cibersegurança mínimas nos termos do n.º 5 do artigo 26.º\n2 — Com base na análise e gestão de riscos referida no número anterior, as entidades essenciais e importantes devem adotar as medidas de cibersegurança adequadas e proporcionais de forma a gerir os riscos que se colocam à segurança das redes e dos sistemas de informação que utilizam, incluindo os riscos residuais, tendo em conta o QNRCS, os progressos técnicos mais recentes e, se aplicáveis, as normas europeias e internacionais pertinentes.\n3 — As entidades essenciais e importantes devem documentar a preparação, a execução e a apresentação dos resultados da análise dos riscos."}, "30.º": {"title": "Relatório anual", "text": "1 — As entidades essenciais e importantes devem elaborar e manter um relatório anual que contenha os seguintes elementos em relação ao ano civil a que se reportam:\na) Descrição sumária das principais atividades desenvolvidas em matéria de segurança das redes e dos serviços de informação;\nb) Estatística trimestral de todos os incidentes, com indicação do número e do tipo dos incidentes;\nc) Análise agregada dos incidentes com impacto significativo, com informação sobre:\ni) Número de utilizadores afetados pela perturbação serviço;\nii) Duração dos incidentes;\niii) Distribuição geográfica, no que se refere à zona afetada pelos incidentes, incluindo a indicação de impacto transfronteiriço;\nd) Recomendações de atividades, de medidas ou de práticas que promovam a melhoria da segurança das redes e dos sistemas de informação;\ne) Problemas identificados e medidas implementadas na sequência dos incidentes;\nf) Qualquer outra informação que se considere relevante.\n2 — As entidades essenciais remetem o relatório anual à autoridade de cibersegurança competente, devidamente assinado pelo responsável de cibersegurança, nos seguintes termos:\na) O primeiro relatório anual é submetido:\ni) Até ao último dia útil do mês de janeiro do ano civil seguinte ao primeiro ano civil de atividade, quando esta tenha tido início no primeiro semestre;\nii) Até ao último dia útil do mês de janeiro do segundo ano civil seguinte ao primeiro ano civil de atividade, quando esta tenha tido início no segundo semestre;\nb) Os relatórios anuais subsequentes são submetidos até ao último dia útil do mês de janeiro do ano civil seguinte aos quais os mesmos se reportam.\n3 — Para efeitos do disposto na subalínea ii) da alínea a) do número anterior, o relatório anual deve abranger também o período entre a data de início de atividade e o final do ano civil anterior ao que se reporta.\n4 — As entidades importantes devem comunicar o relatório anual ao CNCS sempre que solicitado.\n5 — O CNCS, ouvidas as autoridades nacionais setoriais de cibersegurança, pode adotar modelos para a apresentação do relatório referido nos números anteriores."}, "33.º": {"title": "Medidas de cibersegurança aplicáveis às entidades públicas relevantes", "text": "1 — As entidades públicas relevantes devem cumprir com as medidas de cibersegurança estabelecidas pelo CNCS nos termos do número seguinte.\n2 — O CNCS estabelece, através de regulamento, as medidas de cibersegurança que devem ser cumpridas por parte das entidades públicas relevantes, considerando os critérios previstos no disposto nos n.os 2 e 3 do artigo 26.º e em termos proporcionais e adequados ao grupo a que pertencem, de acordo com o disposto no artigo 7.º\n3 — As entidades públicas relevantes estão sujeitas às medidas de supervisão e de execução previstas nos artigos 55.º e 56.º, respetivamente.\n4 — É aplicável às entidades públicas relevantes o disposto no n.º 8 do artigo 26.º"}, "40.º": {"title": "Notificação obrigatória", "text": "1 — As entidades essenciais, importantes e públicas relevantes notificam qualquer incidente significativo à autoridade de cibersegurança competente.\n2 — O cumprimento da mera notificação não gera responsabilidade acrescida para a entidade notificante.\n3 — A fim de determinar se um incidente tem impacto significativo nos termos do n.º 1, as entidades em causa devem ter em consideração, designadamente, os seguintes parâmetros:\na) Número de utilizadores afetados pela perturbação do serviço;\nb) Número total de utilizadores do serviço perturbado;\nc) A duração do incidente;\nd) O nível da gravidade da perturbação do funcionamento do serviço;\ne) A dimensão do impacto nas atividades económicas e sociais.\n4 — As entidades devem ainda ter em consideração os parâmetros e limiares definidos, quando aplicável, por instrução técnica do CNCS e pelos atos de execução da Comissão, previstos no n.º 11 do artigo 23.º da Diretiva (UE) 2022/2555, do Parlamento Europeu e do Conselho, de 14 de dezembro de 2022.\n5 — O cumprimento do disposto no presente decreto-lei não dispensa o respeito pelas obrigações específicas de notificação de incidentes nos termos definidos pelas autoridades com competência para o efeito, nomeadamente o Ministério Público, a Polícia Judiciária, a CNPD, a Entidade Fiscalizadora do Segredo de Estado e o GNS, de acordo com as disposições legais e regulamentares aplicáveis.\n6 — As notificações devem ser submetidas na plataforma eletrónica referida no n.º 7 do artigo 8.º\n7 — Às entidades essenciais, importantes e públicas relevantes é assegurada a possibilidade de notificar um incidente, simultaneamente, à autoridade de cibersegurança competente, às autoridades especiais de cibersegurança, bem como às entidades previstas no n.º 5, através da plataforma prevista no n.º 7 do artigo 8.º, nos termos a definir por protocolo outorgado entre as referidas autoridades."}, "41.º": {"title": "Tipos de notificações", "text": "1 — Por cada incidente sujeito a notificação obrigatória, as entidades essenciais, importantes e públicas relevantes submetem:\na) Uma notificação inicial, nos termos do artigo 42.º;\nb) Uma notificação de fim do impacto significativo, nos termos do artigo 43.º;\nc) Um relatório final, nos termos dos artigos 44.º\n2 — Nos casos em que o incidente é resolvido nas duas horas após a sua deteção, as entidades referidas ficam apenas obrigadas ao envio da notificação do fim de impacto significativo.\n3 — Sem prejuízo do disposto no número anterior, as entidades essenciais, importantes e públicas relevantes podem ainda ser notificadas para apresentar um relatório intercalar, nos termos do artigo 44.º\n4 — O formato e procedimento de notificação de incidentes e a taxonomia dos incidentes, incluindo as categorias de causas dos incidentes e os seus efeitos, são definidos por instrução técnica do CNCS, sem prejuízo dos atos de execução adotados pela Comissão previstos no n.º 11 do artigo 23.º da Diretiva (UE) 2022/2555, do Parlamento Europeu e do Conselho, de 14 de dezembro de 2022."}, "42.º": {"title": "Notificação inicial", "text": "1 — A notificação inicial deve ser enviada à autoridade de cibersegurança competente, assim que a entidade essencial, importante ou pública relevante concluir que existe, ou possa vir a existir, um incidente significativo, sem demora injustificada e até 24 horas após essa verificação, salvo quando tal for incompatível com a mitigação ou a resolução do incidente.\n2 — A notificação inicial deve incluir, pelo menos, a seguinte informação:\na) Nome, número de telefone e endereço de correio eletrónico de um representante da entidade, quando diferente do ponto de contacto permanente a que se refere o artigo 32.º, para efeito de um eventual contacto pela autoridade de cibersegurança competente;\nb) Data e hora do início ou, em caso de impossibilidade de o determinar, da deteção do incidente;\nc) Breve descrição do incidente, incluindo a indicação da categoria da causa e dos efeitos produzidos, de acordo com a taxonomia definida pelo CNCS, sempre que possível, o respetivo detalhe;\nd) Estimativa possível do impacto, considerando:\ni) Número de utilizadores afetados pela perturbação do serviço;\nii) Duração do incidente;\niii) Distribuição geográfica, no que se refere à zona afetada pelo incidente, incluindo a indicação do impacto transfronteiriço;\niv) Outra informação que a entidade essencial e importante considere relevante.\n3 — Quando necessário, a entidade essencial, importante ou pública relevante envia à autoridade de cibersegurança competente uma atualização da notificação inicial até 72 horas após a verificação do incidente significativo, revendo a informação referida no número anterior e fornecendo uma avaliação inicial do incidente significativo, incluindo da sua gravidade e do seu impacto, bem como, se disponíveis, dos indicadores de exposição a riscos."}, "43.º": {"title": "Notificação do fim de impacto significativo", "text": "1 — A notificação do fim de impacto significativo do incidente deve ser submetida à autoridade de cibersegurança competente, sem demora injustificada e dentro do prazo de 24 horas após o fim do impacto.\n2 — A notificação do fim de impacto significativo deve incluir a seguinte informação, pelo menos:\na) Atualização da informação transmitida na notificação inicial, caso exista;\nb) Breve descrição das medidas adotadas para a resolução do incidente;\nc) Descrição da situação de impacto existente no momento da perda de impacto significativo, nomeadamente:\ni) Número de utilizadores afetados pela perturbação do serviço;\nii) Duração do incidente;\niii) Distribuição geográfica, no que se refere à zona afetada pelo incidente, incluindo a indicação de impacto transfronteiriço;\niv) Tempo estimado para a recuperação total dos serviços."}, "44.º": {"title": "Relatórios final e intercalar", "text": "1 — O relatório final deve ser submetido à autoridade de cibersegurança competente, no prazo de 30 dias úteis a contar da data da notificação do fim de impacto significativo do incidente.\n2 — O relatório final deve incluir a seguinte informação:\na) Data e hora em que o incidente assumiu o impacto significativo;\nb) Data e hora em que o incidente perdeu o impacto significativo;\nc) Impacto do incidente, considerando:\ni) Número de utilizadores afetados pela perturbação do serviço;\nii) Duração do incidente;\niii) Distribuição geográfica, no que se refere à zona afetada pelo incidente, incluindo a indicação de impacto transfronteiriço;\niv) Descrição do incidente, com a indicação da categoria da causa e dos efeitos produzidos, de acordo com a taxonomia definida pelo CNCS, e o respetivo detalhe;\nd) Indicação das medidas adotadas para mitigar o incidente;\ne) Descrição da situação residual do impacto existente à data da notificação final, nomeadamente:\ni) Número de utilizadores afetados pela perturbação do serviço;\nii) Distribuição geográfica, no que se refere à zona afetada pelo incidente, incluindo a indicação de impacto transfronteiriço;\niii) Tempo estimado para a recuperação total dos serviços ainda afetados;\niv) Indicação, sempre que aplicável, da apresentação de notificação do incidente em causa às autoridades competentes, nomeadamente ao Ministério Público ou à CNPD e a outras autoridades setoriais, nos termos previstos nas disposições legais e regulamentares aplicáveis;\nv) Outra informação que a entidade essencial e importante considere relevante.\n3 — Na hipótese de, decorrido o prazo para apresentação do relatório final, o incidente ainda se encontrar em curso, a entidade essencial, importante ou pública relevante em causa deve apresentar relatório intercalar a autoridade de cibersegurança competente, a pedido destas entidades e com periodicidade semanal até ao momento da apresentação do relatório final.\n4 — O relatório intercalar deve incluir a seguinte informação:\na) Atualização da informação transmitida na notificação inicial, caso exista;\nb) Breve descrição das medidas adotadas para a resolução do incidente;\nc) Descrição da situação de impacto existente no momento da perda de impacto significativo, nomeadamente:\ni) Número de utilizadores afetados pela perturbação do serviço;\nii) Duração do incidente;\niii) Distribuição geográfica, no que se refere à zona afetada pelo incidente, incluindo a indicação de impacto transfronteiriço;\niv) Tempo estimado para a recuperação total dos serviços."}}, "reg756": {"20.º": {"title": "Notificação obrigatória de incidentes", "text": "1 — As entidades essenciais, importantes e públicas relevantes, quando ocorra um incidente com impacto significativo, submetem à autoridade de cibersegurança competente, através de formulário disponível na área reservada da plataforma eletrónica:\na) Uma notificação inicial, nos termos e com a informação prevista no artigo 42.º do Regime Jurídico da Cibersegurança;\nb) Uma notificação de fim do impacto significativo, nos termos e com a informação prevista no artigo 43.º do Regime Jurídico da Cibersegurança;\nc) Um relatório final ou intercalar, nos termos e com a informação prevista no artigo 44.º do Regime Jurídico da Cibersegurança;\n2 — Sem prejuízo do número anterior, as entidades podem, ainda, submeter, sem necessidade de autenticação na plataforma eletrónica, notificações voluntárias de informações pertinentes nos termos do artigo seguinte.\n3 — O impacto de um incidente é definido como significativo:\na) Nos termos do Regulamento de Execução (UE) n.º 2024/2690, de 17 de outubro, para as entidades pertinentes aí previstas;\nb) Nos termos gerais previstos na alínea l) do artigo 2.º do Regime Jurídico da Cibersegurança, densificados por via de instrução técnica a aprovar pela Autoridade Nacional de Cibersegurança, para as restantes entidades integradas no âmbito subjetivo do Regime Jurídico da Cibersegurança.\n4 — Quando as entidades não consigam proceder às notificações de incidentes, por falta temporária de capacidade operacional própria, em resultado do incidente ou por outro motivo de natureza eminentemente técnica devidamente justificado, a notificação pode ser efetuada, a título excecional, através de correio eletrónico ou telefonicamente, estando os devidos meios de contacto disponibilizados no sítio de internet da autoridade de cibersegurança competente. Nos casos em que a plataforma eletrónica esteja indisponível aquando do envio da notificação, aplicam-se os procedimentos previstos no artigo 17.º do presente Regulamento."}, "23.º": {"title": "QNRCS", "text": "1 — O QNRCS, aprovado no presente Regulamento e constante do Anexo I, é o instrumento nacional de referência para a identificação das normas, padrões e boas práticas existentes em matéria de gestão da Cibersegurança e da Segurança Informação, nos termos do artigo 14.º do Regime Jurídico da Cibersegurança.\n2 — O QNRCS é construído e atualizado atendendo aos princípios da prossecução do interesse público, da legalidade, da eficiência, da eficácia e da proporcionalidade, devendo minimizar, sempre que possível, o seu impacto nas atividades públicas, sociais e empresariais das entidades.\n3 — As entidades devem considerar o QNRCS visando uma perspetiva de melhoria contínua e evolutiva.\n4 — Compete ao CNCS atualizar, pelo menos, de cinco em cinco anos, o QNRCS, nos termos do n.º 2 do artigo 14.º do Regime Jurídico da Cibersegurança."}, "26.º": {"title": "Aplicação conjunta", "text": "A aplicação facultativa do QNRCS pelas entidades essenciais e importantes deve ser conjugada com as medidas de cibersegurança mínimas e respetivos níveis de conformidade previstos no anexo iii do presente Regulamento."}, "28.º": {"title": "Matriz de Risco", "text": "1 — A matriz de risco, aprovada no presente Regulamento e constante do Anexo II, é o quadro referencial que estabelece os valores de risco para o conjunto de cenários de risco que recaem sobre um setor e subsetor de atividade, considerando os ativos comuns, as principais ameaças e vulnerabilidades, nos termos do disposto na alínea m) do artigo 2.º, no n.os 5 do artigo 26.º e no n.º 3 do artigo 53.º do Regime Jurídico da Cibersegurança.\n2 — Considerando o setor de atividade, a dimensão da entidade e a matriz de risco definida são determinados os níveis de conformidade e as medidas de cibersegurança mínimas e específicas a adotar que constam do anexo iii.\n3 — Os valores de risco referidos no n.º 1 são determinados com base no nível de risco associado ao setor ou subsetor a que as entidades pertencem tendo em conta a sua dimensão e com a importância do setor ou subsetor, podendo ser atribuído um de três níveis de conformidade:\na) Básico;\nb) Substancial;\nc) Elevado.\n4 — Os critérios para a produção da matriz de risco são construídos e atualizados atendendo aos princípios da prossecução do interesse público, da legalidade, da eficiência, da eficácia e da proporcionalidade, devendo minimizar, sempre que possível, o seu impacto nas atividades públicas, sociais e empresariais das entidades.\n5 — O CNCS disponibiliza na plataforma eletrónica um glossário de apoio à leitura da Matriz de Risco."}, "29.º": {"title": "Cenários de Risco", "text": "O CNCS emite anualmente, através de instrução técnica, nos termos do n.º 4 do artigo 26.º do Regime Jurídico da Cibersegurança, as orientações relevantes de forma a orientar a política de gestão de riscos da cibersegurança das entidades essenciais e importantes, nomeadamente:\na) Cenários de risco;\nb) Vetores de ameaça;\nc) Informações quanto aos ativos."}, "30.º": {"title": "Medidas de Cibersegurança Mínimas", "text": "1 — As entidades essenciais, importantes e públicas relevantes aplicam, pelo menos, as medidas de cibersegurança mínimas, aprovadas no presente Regulamento e constante dos anexos iii e iv, nos termos dos n.os 5 e 6 do artigo 26.º, artigo 27.º e artigo 33.º do Regime Jurídico da Cibersegurança.\n2 — As entidades essenciais e importantes sujeitas aos níveis de conformidade substancial e elevado asseguram, ainda, a aplicação das medidas de cibersegurança mínimas dos níveis de conformidade respetivamente inferiores.\n3 — As entidades públicas relevantes sujeitas às medidas de cibersegurança previstas para o Grupo A, nos termos definidos no Anexo IV do presente Regulamento, asseguram, igualmente, a aplicação das medidas de cibersegurança mínimas definidas para o Grupo B do mesmo anexo.\n4 — Caso as entidades essenciais ou importantes se encontrem em mais do que um nível de conformidade, aplica-se o nível de conformidade que se revelar mais exigente para gerir os riscos que se colocam à segurança das redes e sistemas de informação de acordo com a seguinte ordem descendente:\na) Elevado;\nb) Substancial;\nc) Básico.\n5 — O CNCS pode exigir às entidades essenciais, importantes e públicas relevantes, a obtenção de certificação, nacional, europeia ou internacional, que ateste o cumprimento das medidas de cibersegurança aplicáveis, nos termos do n.º 1 do artigo 34.º do Regime Jurídico da Cibersegurança.\n6 — A decisão prevista no número anterior é fundamentada, nomeadamente em função do risco ou essencialidade do serviço ou da entidade, é sujeita a audiência dos interessados nos termos do Código do Procedimento Administrativo e define o prazo de adaptação das entidades, não superior a 24 meses.\n7 — Nos termos do n.º 3 do artigo 20.º do Regime Jurídico da Cibersegurança, as autoridades nacionais setoriais ou especiais de cibersegurança podem emitir disposições regulamentares, precedidas de parecer do CNCS, para a adoção de medidas de cibersegurança do setor.\n8 — A autoridade de cibersegurança competente pode ainda recomendar, sem caráter vinculativo, a adoção de medidas mínimas de cibersegurança às entidades que se encontram fora do âmbito de aplicação do Regime Jurídico da Cibersegurança."}, "31.º": {"title": "Gestão do Risco", "text": "1 — As entidades essenciais e importantes, procedem, nos termos do n.º 1 do artigo 29.º do Regime Jurídico da Cibersegurança, à análise e gestão periódicas dos riscos e dos riscos residuais, relativos aos ativos que garantam a continuidade do funcionamento das redes e dos sistemas de informação que utilizam, incluindo os ativos que garantam a prestação dos serviços essenciais.\n2 — As entidades essenciais e importantes realizam a análise dos riscos com a seguinte periodicidade:\na) Pelo menos uma vez por ano;\nb) Após a notificação, por parte do CNCS, de um risco, de uma ameaça ou de uma vulnerabilidade emergentes que implique uma elevada probabilidade de ocorrência de um incidente com impacto relevante, dentro do prazo fixado pelo CNCS.\n3 — A análise dos riscos pelas entidades essenciais e importantes deve ter em consideração:\na) O histórico de situações extraordinárias ocorridas;\nb) O histórico de incidentes e, em especial, de incidentes com impacto relevante;\nc) O número de utilizadores afetados pelos incidentes;\nd) A duração dos incidentes;\ne) A distribuição geográfica, no que se refere à zona afetada pelos incidentes;\nf) As dependências intersetoriais para efeitos da prestação dos serviços;\ng) Os elementos constantes da instrução técnica referida no artigo 29.º do presente Regulamento.\n4 — As entidades essenciais e importantes realizam ainda a análise do risco residual, após a adoção de medidas de cibersegurança, nos termos do disposto nos n.os 1 e 2 do artigo 29.º do Regime Jurídico da Cibersegurança."}, "32.º": {"title": "Lista de ativos publicamente acessíveis", "text": "1 — Para efeitos de comunicação das gamas de endereços de IP prevista na alínea c) do n.º 1 e alínea d) do n.º 2 do artigo 35.º do Regime Jurídico da Cibersegurança, as entidades essenciais, importantes e públicas relevantes, devem elaborar, manter atualizado e comunicar à autoridade de cibersegurança competente, através da plataforma eletrónica, uma lista de todos os ativos, com base no seu inventário de ativos, que estejam diretamente acessíveis publicamente através da Internet.\na) A lista de ativos acima referida, que constitui informação classificada de grau reservado deve incluir a seguinte informação: Serviço suportado;\nb) Nome do equipamento/Nome do software;\nc) Modelo/Versão;\nd) Sistema operativo;\ne) Software do servidor aplicacional;\nf) Endereço IP, se aplicável;\ng) Fully Qualified Domain Names (FQDNs), se aplicável;\nh) Fabricante;\ni) As dependências dos ativos, diretamente acessíveis de forma pública através da Internet, com outros ativos (diretamente acessíveis de forma pública através da Internet ou não), quando existentes.\n2 — Para os efeitos da alínea i) do número anterior, existe dependência entre ativos quando a indisponibilidade de um ativo compromete sequencialmente a continuidade da atividade ou utilização de outro ativo.\n3 — As entidades devem comunicar à autoridade de cibersegurança competente a lista dos ativos, com a seguinte periodicidade:\na) Na sua versão inicial, até 31 de janeiro do ano seguinte ao ano em que ocorra a notificação prevista no n.º 5 do artigo 8.º Regime Jurídico da Cibersegurança ou no prazo de seis meses após a mesma notificação consoante o que se vença primeiro;\nb) Numa versão atualizada, anualmente, a ser entregue simultaneamente com o relatório anual a que se refere o n.º 2 do artigo 30.º do Regime Jurídico da Cibersegurança, quando sejam entidades essenciais;\nc) Numa versão atualizada, anualmente, e até ao último dia útil do mês de janeiro, do ano civil seguinte ao qual a mesma se reporta, quando sejam entidades importantes e públicas relevantes.\n4 — O CNCS publica uma instrução técnica de apoio à identificação dos ativos essenciais para a prestação dos respetivos serviços e referidos no n.º 1 do presente artigo."}}, "nis2_art21": [{"letter": "a", "text": "Políticas de análise dos riscos e de segurança dos sistemas de informação;"}, {"letter": "b", "text": "Tratamento de incidentes;"}, {"letter": "c", "text": "Continuidade das atividades, como a gestão de cópias de segurança e a recuperação de desastres, e gestão de crises;"}, {"letter": "d", "text": "Segurança da cadeia de abastecimento, incluindo aspetos de segurança respeitantes às relações entre cada entidade e os respetivos fornecedores ou prestadores de serviços diretos;"}, {"letter": "e", "text": "Segurança na aquisição, desenvolvimento e manutenção dos sistemas de rede e informação, incluindo o tratamento e a divulgação de vulnerabilidades;"}, {"letter": "f", "text": "Políticas e procedimentos para avaliar a eficácia das medidas de gestão dos riscos de cibersegurança;"}, {"letter": "g", "text": "Práticas básicas de ciber-higiene e formação em cibersegurança;"}, {"letter": "h", "text": "Políticas e procedimentos relativos à utilização de criptografia e, se for caso disso, de cifragem;"}, {"letter": "i", "text": "Segurança dos recursos humanos, políticas seguidas em matéria de controlo do acesso e gestão de ativos;"}, {"letter": "j", "text": "Utilização de soluções de autenticação multifatores ou de autenticação contínua, comunicações seguras de voz, vídeo e texto e sistemas seguros de comunicações de emergência no seio da entidade, se for caso disso."}], "r2690": [{"id": "1.1.1", "section": "1. Política de segurança dos sistemas de rede e informação", "text": "Para efeitos do artigo 21.º, n.º 2, alínea a), da Diretiva (UE) 2022/2555, a política de segurança dos sistemas de rede e informação deve:\n(a) Definir a abordagem das entidades pertinentes no que toca à gestão da segurança dos seus sistemas de rede e informação;\n(b) Ser adequada e complementar em relação à estratégia e aos objetivos empresariais das entidades pertinentes;\n(c) Definir objetivos em matéria de segurança das redes e da informação;\n(d) Incluir um compromisso de melhoria contínua da segurança dos sistemas de rede e informação;\n(e) Incluir um compromisso relativo à disponibilização dos recursos adequados necessários à sua execução, incluindo o pessoal, os recursos financeiros, os processos, as ferramentas e as tecnologias necessários;\n(f) Ser comunicada aos trabalhadores pertinentes e às partes externas interessadas pertinentes, e por eles reconhecida;\n(g) Definir as funções e responsabilidades, nos termos do ponto 1.2;\n(h) Enumerar a documentação a conservar e o respetivo período de conservação;\n(i) Enumerar as políticas temáticas;\n(j) Estabelecer indicadores e medidas para acompanhar a sua aplicação e o estado atual do nível de maturidade das entidades pertinentes em termos de segurança das redes e da informação;\n(k) Indicar a data da aprovação formal pelos órgãos de direção das entidades pertinentes («órgãos de direção»)."}, {"id": "1.1.2", "section": "1. Política de segurança dos sistemas de rede e informação", "text": "A política de segurança do sistema de rede e informação deve ser analisada e, se for caso disso, atualizada pelos órgãos de direção pelo menos anualmente e sempre que ocorram incidentes significativos ou alterações significativas das operações ou dos riscos. O resultado das análises deve ser documentado."}, {"id": "1.2.1", "section": "1. Política de segurança dos sistemas de rede e informação", "text": "No âmbito da sua política de segurança dos sistemas de rede e informação a que se refere o ponto 1.1, as entidades pertinentes definem as responsabilidades e as autoridades em matéria de segurança do sistema de rede e informação, atribuem-nas a funções, distribuem-nas de acordo com as necessidades das entidades pertinentes e comunicam-nas aos órgãos de direção."}, {"id": "1.2.2", "section": "1. Política de segurança dos sistemas de rede e informação", "text": "As entidades pertinentes exigem que todo o pessoal e terceiros implementem a segurança do sistema de rede e informação em conformidade com a política de segurança das redes e da informação estabelecida, com as políticas temáticas e com os procedimentos das entidades pertinentes."}, {"id": "1.2.3", "section": "1. Política de segurança dos sistemas de rede e informação", "text": "Pelo menos uma pessoa deve responder diretamente perante os órgãos de direção no que se refere a questões de segurança do sistema de rede e informação."}, {"id": "1.2.4", "section": "1. Política de segurança dos sistemas de rede e informação", "text": "Em função da dimensão das entidades pertinentes, a segurança do sistema de rede e informação deve ser abrangida por funções ou deveres específicos desempenhados de forma complementar às funções existentes."}, {"id": "1.2.5", "section": "1. Política de segurança dos sistemas de rede e informação", "text": "Quando aplicável, deve assegurar-se a separação dos deveres e das áreas de responsabilidade conflituantes."}, {"id": "1.2.6", "section": "1. Política de segurança dos sistemas de rede e informação", "text": "As funções, as responsabilidades e as autoridades devem ser analisadas e, se for caso disso, atualizadas pelos órgãos de direção a intervalos planeados e sempre que ocorram incidentes significativos ou alterações significativas das operações ou dos riscos."}, {"id": "2.1.1", "section": "2. Política de gestão dos riscos", "text": "Para efeitos do artigo 21.º, n.º 2, alínea a), da Diretiva (UE) 2022/2555, as entidades pertinentes estabelecem e mantêm um quadro adequado de gestão dos riscos para identificar e dar resposta aos riscos que se colocam à segurança dos sistemas de rede e informação. As entidades pertinentes realizam e documentam avaliações dos riscos e, com base nos respetivos resultados, estabelecem, aplicam e acompanham um plano de tratamento dos riscos. Os resultados da avaliação dos riscos e os riscos residuais são aceites pelos órgãos de direção ou, quando aplicável, pelas pessoas responsáveis e com autoridade para gerir os riscos, contanto que as entidades pertinentes assegurem a devida comunicação aos órgãos de direção."}, {"id": "2.1.2", "section": "2. Política de gestão dos riscos", "text": "Para efeitos do ponto 2.1.1, as entidades pertinentes estabelecem procedimentos para a identificação, a análise, a avaliação e o tratamento de riscos («processo de gestão dos riscos de cibersegurança»). O processo de gestão dos riscos de cibersegurança faz parte integrante do processo global de gestão dos riscos das entidades pertinentes, quando aplicável. No âmbito do processo de gestão dos riscos de cibersegurança, as entidades pertinentes:\n(a) Seguem uma metodologia de gestão dos riscos;\n(b) Estabelecem o nível de tolerância ao risco de acordo com a sua apetência pelo risco;\n(c) Estabelecem e mantêm critérios de risco pertinentes;\n(d) Em consonância com uma abordagem que contemple todos os riscos, identificam e documentam os riscos para a segurança dos sistemas de rede e informação, em especial no que se refere a terceiros, e os riscos suscetíveis de conduzir a perturbações na disponibilidade, integridade, autenticidade e confidencialidade dos sistemas de rede e informação, incluindo a identificação de falhas pontuais;\n(e) Analisam os riscos para a segurança dos sistemas de rede e informação, incluindo a ameaça, a probabilidade, o impacto e o nível de risco, tendo em conta as informações sobre ciberameaças e as vulnerabilidades;\n(f) Avaliam os riscos identificados com base nos critérios de risco;\n(g) Identificam as opções e medidas adequadas de tratamento dos riscos e definem a respetiva prioridade;\n(h) Acompanham continuamente a aplicação das medidas de tratamento dos riscos;\n(i) Especificam a pessoa ou pessoas responsáveis pela aplicação das medidas de tratamento dos riscos e o momento em que deve ocorrer tal aplicação;\n(j) Documentam, de forma compreensível, as medidas de tratamento dos riscos escolhidas num plano de tratamento dos riscos, bem como as razões que justificam a aceitação dos riscos residuais."}, {"id": "2.1.3", "section": "2. Política de gestão dos riscos", "text": "Ao identificarem e definirem a prioridade das opções e medidas adequadas de tratamento dos riscos, as entidades pertinentes têm em conta os resultados da avaliação dos riscos, os resultados do procedimento de avaliação da eficácia das medidas de gestão dos riscos de cibersegurança, o custo da aplicação face aos benefícios esperados, a classificação dos ativos a que se refere o ponto 12.1 e a análise de impacto na atividade a que se refere o ponto 4.1.3."}, {"id": "2.1.4", "section": "2. Política de gestão dos riscos", "text": "As entidades pertinentes analisam e, se for caso disso, atualizam os resultados da avaliação dos riscos e o plano de tratamento dos riscos a intervalos planeados e no mínimo anualmente, bem como sempre que ocorram incidentes significativos ou alterações significativas das operações ou dos riscos."}, {"id": "2.2.1", "section": "2. Política de gestão dos riscos", "text": "As entidades pertinentes analisam periodicamente o cumprimento das suas políticas de segurança do sistema de rede e informação, das políticas temáticas, das regras e das normas. Os órgãos de direção são informados do estado da segurança das redes e da informação através de relatórios periódicos baseados em verificações do cumprimento."}, {"id": "2.2.2", "section": "2. Política de gestão dos riscos", "text": "As entidades pertinentes criam um sistema eficaz de comunicação de informações sobre o cumprimento, que deve ser adequado às suas estruturas, ambientes operacionais e panoramas de ameaças. O sistema de comunicação de informações sobre o cumprimento deve ser capaz de fornecer aos órgãos de direção uma visão informada do estado atual da gestão dos riscos das entidades pertinentes."}, {"id": "2.2.3", "section": "2. Política de gestão dos riscos", "text": "As entidades pertinentes efetuam o controlo do cumprimento a intervalos planeados e sempre que ocorram incidentes significativos ou alterações significativas das operações ou dos riscos."}, {"id": "2.3.1", "section": "2. Política de gestão dos riscos", "text": "As entidades pertinentes analisam de forma independente a sua abordagem em matéria de gestão da segurança do sistema de rede e informação, bem como a respetiva aplicação, incluindo pessoas, processos e tecnologias."}, {"id": "2.3.2", "section": "2. Política de gestão dos riscos", "text": "As entidades pertinentes desenvolvem e mantêm processos para a realização de análises independentes, que devem ser levadas a cabo por pessoas com competências de auditoria adequadas. Se a análise independente for realizada por membros do pessoal da entidade pertinente, essas pessoas não podem fazer parte da cadeia hierárquica do pessoal da área visada pela análise. Se a dimensão das entidades pertinentes não permitir essa separação, estas adotam medidas alternativas para garantir a imparcialidade das análises."}, {"id": "2.3.3", "section": "2. Política de gestão dos riscos", "text": "Os resultados das análises independentes, incluindo os resultados do controlo do cumprimento nos termos do ponto 2.2 e do acompanhamento e medição nos termos do ponto 7, são comunicados aos órgãos de direção. As entidades pertinentes tomam medidas corretivas ou aceitam o risco residual de acordo com os seus critérios de aceitação dos riscos."}, {"id": "2.3.4", "section": "2. Política de gestão dos riscos", "text": "As análises independentes são realizadas a intervalos planeados e sempre que ocorram incidentes significativos ou alterações significativas das operações ou dos riscos."}, {"id": "3.1.1", "section": "3. Tratamento de incidentes", "text": "Para efeitos do artigo 21.º, n.º 2, alínea b), da Diretiva (UE) 2022/2555, as entidades pertinentes estabelecem e aplicam uma política de tratamento de incidentes que defina as funções, as responsabilidades e os procedimentos para detetar, analisar, conter ou responder a, recuperar de, documentar e comunicar incidentes em tempo útil."}, {"id": "3.1.2", "section": "3. Tratamento de incidentes", "text": "A política a que se refere o ponto 3.1.1 deve ser coerente com o plano de continuidade das atividades e de recuperação de desastres referido no ponto 4.1. A política deve incluir:\n(a) Um sistema de categorização dos incidentes que seja coerente com a avaliação e a classificação de eventos efetuadas nos termos do ponto 3.4.1;\n(b) Planos de comunicação eficazes, incluindo para a escalada de incidentes e a notificação;\n(c) A atribuição, a trabalhadores competentes, de funções relacionadas com a deteção e a resposta adequada a incidentes;\n(d) Os documentos a utilizar no contexto da deteção e da resposta a incidentes, tais como manuais de resposta a incidentes, diagramas de escalada de incidentes, listas de contactos e modelos."}, {"id": "3.1.3", "section": "3. Tratamento de incidentes", "text": "As funções, as responsabilidades e os procedimentos estabelecidos na política são testados e analisados e, se for caso disso, atualizados a intervalos planeados e na sequência de incidentes significativos ou alterações significativas das operações ou dos riscos."}, {"id": "3.2.1", "section": "3. Tratamento de incidentes", "text": "As entidades pertinentes estabelecem procedimentos e utilizam ferramentas para monitorizar e registar as atividades nos seus sistemas de rede e informação, de modo a detetar eventos suscetíveis de ser considerados incidentes e a responder-lhes em conformidade para atenuar o seu impacto."}, {"id": "3.2.2", "section": "3. Tratamento de incidentes", "text": "Na medida do possível, a monitorização deve ser automatizada e efetuada de forma contínua ou a intervalos regulares, em função das capacidades empresariais. As entidades pertinentes executam as suas atividades de monitorização de forma a minimizar o número de falsos positivos e de falsos negativos."}, {"id": "3.2.3", "section": "3. Tratamento de incidentes", "text": "As entidades pertinentes mantêm, documentam e analisam os registos, com base nos procedimentos a que se refere o ponto 3.2.1. As entidades pertinentes estabelecem uma lista dos ativos que devem ser sujeitos a registo, com base nos resultados da avaliação dos riscos efetuada nos termos do ponto 2.1. Se for caso disso, os registos devem incluir:\n(a) O tráfego pertinente de saída e de entrada na rede;\n(b) A criação, alteração ou supressão de utilizadores dos sistemas de rede e informação das entidades pertinentes e a extensão das autorizações;\n(c) O acesso a sistemas e aplicações;\n(d) Eventos relacionados com a autenticação;\n(e) Todos os acessos privilegiados a sistemas e aplicações, bem como as atividades realizadas através de contas administrativas;\n(f) O acesso ou as alterações a ficheiros críticos de configuração ou de segurança;\n(g) Registos de eventos e registos de ferramentas de segurança, tais como programas antivírus, sistemas de deteção de intrusões ou barreiras de segurança (firewalls);\n(h) A utilização dos recursos do sistema, bem como o seu desempenho;\n(i) O acesso físico às instalações;\n(j) O acesso a e a utilização dos seus equipamentos e dispositivos de rede;\n(k) A ativação, a cessação e a suspensão dos vários registos;\n(l) Os eventos ambientais."}, {"id": "3.2.4", "section": "3. Tratamento de incidentes", "text": "Os registos devem ser analisados regularmente para detetar eventuais tendências invulgares ou indesejadas. Se for caso disso, as entidades pertinentes estabelecem valores adequados para limiares de alerta. Se os valores fixados para um limiar de alerta forem excedidos, o alerta é acionado automaticamente, se for caso disso. Cumpre às entidades pertinentes assegurar que, em caso de alerta, seja dada uma resposta qualificada e adequada em tempo útil."}, {"id": "3.2.5", "section": "3. Tratamento de incidentes", "text": "As entidades pertinentes mantêm registos — bem como cópias de segurança dos mesmos — durante um período predefinido e protegem-nos do acesso ou de alterações não autorizados."}, {"id": "3.2.6", "section": "3. Tratamento de incidentes", "text": "Na medida do possível, as entidades pertinentes asseguram que todos os sistemas dispõem de fontes horárias sincronizadas, para permitir correlacionar registos entre sistemas para efeitos de avaliação de eventos. As entidades pertinentes elaboram e mantêm uma lista de todos os ativos que estão a ser alvo de registo e asseguram a redundância dos sistemas de monitorização e de registo. A disponibilidade dos sistemas de monitorização e de registo é monitorizada separadamente dos sistemas que estes monitorizam."}, {"id": "3.2.7", "section": "3. Tratamento de incidentes", "text": "Os procedimentos, assim como a lista dos ativos que estão a ser alvo de registo, são analisados e, se for caso disso, atualizados a intervalos regulares e na sequência de incidentes significativos."}, {"id": "3.3.1", "section": "3. Tratamento de incidentes", "text": "As entidades pertinentes criam um mecanismo simples que permita que os seus trabalhadores, fornecedores e clientes comuniquem eventos suspeitos."}, {"id": "3.3.2", "section": "3. Tratamento de incidentes", "text": "Se for caso disso, as entidades pertinentes divulgam o mecanismo de comunicação de eventos junto dos seus fornecedores e clientes e ministram regularmente aos seus trabalhadores formação sobre como utilizá-lo."}, {"id": "3.4.1", "section": "3. Tratamento de incidentes", "text": "As entidades pertinentes avaliam os eventos suspeitos para determinar se constituem incidentes e, em caso afirmativo, determinam a sua natureza e gravidade."}, {"id": "3.4.2", "section": "3. Tratamento de incidentes", "text": "Para efeitos do ponto 3.4.1, as entidades pertinentes atuam da seguinte forma:\n(a) Realizam a avaliação com base em critérios previamente definidos e numa triagem para determinar a prioridade da contenção e erradicação do incidente;\n(b) Avaliam trimestralmente a existência dos incidentes recorrentes a que se refere o artigo 4.º do presente regulamento;\n(c) Analisam os registos adequados para efeitos de avaliação e classificação de eventos;\n(d) Instauram um processo para a correlação e a análise dos registos; e\n(e) Reavaliam e reclassificam os eventos, caso fiquem disponíveis novas informações ou na sequência da análise de informações previamente disponíveis."}, {"id": "3.5.1", "section": "3. Tratamento de incidentes", "text": "As entidades pertinentes respondem aos incidentes em tempo útil e de acordo com procedimentos documentados."}, {"id": "3.5.2", "section": "3. Tratamento de incidentes", "text": "Os procedimentos de resposta a incidentes devem incluir as seguintes etapas:\n(a) Contenção do incidente, para evitar que as suas consequências se propaguem;\n(b) Erradicação, a fim de evitar a continuação ou o ressurgimento do incidente;\n(c) Recuperação do incidente, se necessário."}, {"id": "3.5.3", "section": "3. Tratamento de incidentes", "text": "As entidades pertinentes estabelecem planos e procedimentos de comunicação:\n(a) Com as equipas de resposta a incidentes de segurança informática (CSIRT, do inglês computer security incident response teams) ou, quando aplicável, com as autoridades competentes, no que diz respeito à notificação de incidentes;\n(b) Para a comunicação entre os membros do pessoal da entidade pertinente e para efeitos de comunicação com partes interessadas pertinentes externas à entidade pertinente."}, {"id": "3.5.4", "section": "3. Tratamento de incidentes", "text": "As entidades pertinentes registam as atividades de resposta a incidentes em conformidade com os procedimentos a que se refere o ponto 3.2.1 e registam os elementos de prova."}, {"id": "3.5.5", "section": "3. Tratamento de incidentes", "text": "As entidades pertinentes testam, a intervalos planeados, os seus procedimentos de resposta a incidentes."}, {"id": "3.6.1", "section": "3. Tratamento de incidentes", "text": "Se for caso disso, as entidades pertinentes procedem a análises pós-incidentes após a recuperação de incidentes. As análises pós-incidentes devem identificar, sempre que possível, a causa primária do incidente e resultar na documentação dos ensinamentos retirados, a fim de reduzir a ocorrência de incidentes futuros e atenuar as respetivas consequências."}, {"id": "3.6.2", "section": "3. Tratamento de incidentes", "text": "As entidades pertinentes asseguram que as análises pós-incidentes contribuem para melhorar a sua abordagem em matéria de segurança das redes e da informação, medidas de tratamento de riscos e procedimentos de tratamento, deteção e resposta a incidentes."}, {"id": "3.6.3", "section": "3. Tratamento de incidentes", "text": "As entidades pertinentes analisam, a intervalos planeados, se os incidentes conduziram a análises pós-incidentes."}, {"id": "4.1.1", "section": "4. Continuidade das atividades e gestão de crises", "text": "Para efeitos do artigo 21.º, n.º 2, alínea c), da Diretiva (UE) 2022/2555, as entidades pertinentes estabelecem e mantêm um plano de continuidade das atividades e de recuperação de desastres a aplicar em caso de incidentes."}, {"id": "4.1.2", "section": "4. Continuidade das atividades e gestão de crises", "text": "As operações das entidades pertinentes devem ser restabelecidas de acordo com o plano de continuidade das atividades e de recuperação de desastres. O plano deve basear-se nos resultados da avaliação dos riscos efetuada nos termos do ponto 2.1 e incluir, se for caso disso, os seguintes elementos:\n(a) Finalidade, âmbito e destinatários;\n(b) Funções e responsabilidades;\n(c) Principais contactos e canais de comunicação (internos e externos);\n(d) Condições para a ativação e desativação do plano;\n(e) Ordem pela qual devem ser recuperadas as operações;\n(f) Planos de recuperação para operações específicas, incluindo objetivos de recuperação;\n(g) Recursos necessários, incluindo cópias de segurança e redundâncias;\n(h) Transição das medidas temporárias para o restabelecimento e a retoma das atividades."}, {"id": "4.1.3", "section": "4. Continuidade das atividades e gestão de crises", "text": "As entidades pertinentes realizam uma análise de impacto na atividade para avaliar o potencial impacto de perturbações graves nas suas operações comerciais e, com base nos resultados dessa análise de impacto, estabelecem requisitos de continuidade para os sistemas de rede e informação."}, {"id": "4.1.4", "section": "4. Continuidade das atividades e gestão de crises", "text": "O plano de continuidade das atividades e de recuperação de desastres deve ser testado, analisado e, se for caso disso, atualizado a intervalos planeados e na sequência de incidentes significativos ou de alterações significativas das operações ou dos riscos. As entidades pertinentes asseguram que os planos incorporam os ensinamentos retirados desses testes."}, {"id": "4.2.1", "section": "4. Continuidade das atividades e gestão de crises", "text": "As entidades pertinentes mantêm cópias de segurança dos dados e disponibilizam recursos suficientes, incluindo instalações, sistemas de rede e informação e pessoal, a fim de assegurar um nível adequado de redundância."}, {"id": "4.2.2", "section": "4. Continuidade das atividades e gestão de crises", "text": "Com base nos resultados da avaliação dos riscos realizada nos termos do ponto 2.1. e no plano de continuidade das atividades, as entidades pertinentes estabelecem planos de reserva que incluam o seguinte:\n(a) Tempos de recuperação;\n(b) A garantia de que as cópias de segurança estão completas e são exatas, incluindo os dados de configuração e os dados armazenados no ambiente de um serviço de computação em nuvem;\n(c) O armazenamento das cópias de segurança (em linha ou fora dela) num local ou locais seguros que não se encontrem na mesma rede que o sistema e que estejam a uma distância suficiente para escapar a eventuais danos resultantes de um desastre nas instalações principais;\n(d) Controlos adequados do acesso físico e lógico às cópias de segurança, em conformidade com o nível de classificação dos ativos;\n(e) O restabelecimento dos dados a partir de cópias de segurança;\n(f) Os períodos de conservação, baseados em requisitos empresariais e regulamentares."}, {"id": "4.2.3", "section": "4. Continuidade das atividades e gestão de crises", "text": "As entidades pertinentes efetuam verificações regulares da integridade das cópias de segurança."}, {"id": "4.2.4", "section": "4. Continuidade das atividades e gestão de crises", "text": "Com base nos resultados da avaliação dos riscos realizada nos termos do ponto 2.1. e no plano de continuidade das atividades, as entidades pertinentes asseguram a disponibilidade suficiente de recursos através, no mínimo, da redundância parcial dos seguintes elementos:\n(a) Sistemas de rede e informação;\n(b) Ativos, incluindo instalações, equipamentos e fornecimentos;\n(c) Pessoal dotado da responsabilidade, da autoridade e da competência necessárias;\n(d) Canais de comunicação adequados."}, {"id": "4.2.5", "section": "4. Continuidade das atividades e gestão de crises", "text": "Se for caso disso, as entidades pertinentes asseguram que o acompanhamento e o ajustamento dos recursos, incluindo as instalações, os sistemas e o pessoal, se baseiam devidamente nos requisitos relativos às cópias de segurança e à redundância."}, {"id": "4.2.6", "section": "4. Continuidade das atividades e gestão de crises", "text": "As entidades pertinentes realizam testes regulares da recuperação de cópias de segurança e das redundâncias, a fim de assegurar que, num contexto de recuperação, tais recursos podem ser utilizados de forma fiável e abrangem as cópias, os processos e os conhecimentos necessários para uma recuperação eficaz. As entidades pertinentes devem documentar os resultados dos testes e, se necessário, tomar medidas corretivas."}, {"id": "4.3.1", "section": "4. Continuidade das atividades e gestão de crises", "text": "As entidades pertinentes criam um processo de gestão de crises."}, {"id": "4.3.2", "section": "4. Continuidade das atividades e gestão de crises", "text": "As entidades pertinentes asseguram que o processo de gestão de crises contempla, pelo menos, os seguintes elementos:\n(a) As funções e responsabilidades do pessoal e, se for caso disso, dos fornecedores e prestadores de serviços, especificando a atribuição de funções em situações de crise, incluindo os passos específicos a seguir;\n(b) Meios de comunicação adequados entre as entidades pertinentes e as autoridades competentes pertinentes;\n(c) A aplicação de medidas adequadas para garantir a manutenção da segurança do sistema de rede e informação em situações de crise.\nPara efeitos da alínea b), o fluxo de informações entre as entidades pertinentes e as autoridades competentes pertinentes deve abranger as comunicações obrigatórias (como, por exemplo, os relatórios de incidentes e os calendários conexos) e as comunicações não obrigatórias."}, {"id": "4.3.3", "section": "4. Continuidade das atividades e gestão de crises", "text": "As entidades pertinentes devem implementar um processo de gestão e utilização das informações sobre incidentes, vulnerabilidades, ameaças ou eventuais medidas de atenuação que recebem das CSIRT ou, quando aplicável, das autoridades competentes."}, {"id": "4.3.4", "section": "4. Continuidade das atividades e gestão de crises", "text": "As entidades pertinentes testam, analisam e, se for caso disso, atualizam o plano de gestão de crises regularmente ou na sequência de incidentes significativos ou de alterações significativas das operações ou dos riscos."}, {"id": "5.1.1", "section": "5. Segurança da cadeia de abastecimento", "text": "Para efeitos do artigo 21.º, n.º 2, alínea d), da Diretiva (UE) 2022/2555, as entidades pertinentes estabelecem, executam e aplicam uma política de segurança da cadeia de abastecimento que reja as relações com os seus fornecedores e prestadores de serviços diretos, a fim de atenuar os riscos identificados para a segurança dos sistemas de rede e informação. Na política de segurança da cadeia de abastecimento, as entidades pertinentes identificam a sua função na cadeia de abastecimento e comunicam-na aos seus fornecedores e prestadores de serviços diretos."}, {"id": "5.1.2", "section": "5. Segurança da cadeia de abastecimento", "text": "No âmbito da política de segurança da cadeia de abastecimento a que se refere o ponto 5.1.1., as entidades pertinentes estabelecem os critérios aplicáveis à seleção e à contratação de fornecedores e prestadores de serviços. Esses critérios incluem o seguinte:\n(a) As práticas de cibersegurança dos fornecedores e dos prestadores de serviços, incluindo os respetivos procedimentos de desenvolvimento seguro;\n(b) A capacidade dos fornecedores e dos prestadores de serviços para cumprirem as especificações de cibersegurança estabelecidas pelas entidades pertinentes;\n(c) A qualidade e a resiliência globais dos produtos de TIC e dos serviços de TIC e as medidas de gestão dos riscos de cibersegurança neles incorporadas, incluindo os riscos e o nível de classificação desses produtos e serviços;\n(d) A capacidade das entidades pertinentes para diversificarem as fontes de abastecimento e limitarem a vinculação a fornecedores, quando aplicável."}, {"id": "5.1.3", "section": "5. Segurança da cadeia de abastecimento", "text": "Ao estabelecerem a sua política de segurança da cadeia de abastecimento, as entidades pertinentes têm em conta os resultados das avaliações coordenadas dos riscos de segurança das cadeias de abastecimento críticas realizadas nos termos do artigo 22.º, n.º 1, da Diretiva (UE) 2022/2555, quando aplicável."}, {"id": "5.1.4", "section": "5. Segurança da cadeia de abastecimento", "text": "Com base na política de segurança da cadeia de abastecimento e tendo em conta os resultados da avaliação dos riscos realizada em conformidade com o ponto 2.1. do presente anexo, as entidades pertinentes asseguram que os seus contratos com os fornecedores e prestadores de serviços estipulam, se for caso disso por meio de acordos de nível de serviço, os seguintes elementos, quando aplicáveis:\n(a) Requisitos de cibersegurança para os fornecedores ou prestadores de serviços, incluindo os requisitos estabelecidos no ponto 6.1. em matéria de segurança na aquisição de serviços de TIC ou produtos de TIC;\n(b) Requisitos relativos à sensibilização, às competências e à formação, bem como, se for caso disso, às certificações, exigidas aos trabalhadores dos fornecedores ou prestadores de serviços;\n(c) Requisitos relativos à verificação dos antecedentes dos trabalhadores dos fornecedores e dos prestadores de serviços;\n(d) A obrigação de os fornecedores e prestadores de serviços notificarem as entidades pertinentes, sem demora injustificada, dos incidentes que representem um risco para a segurança dos sistemas de rede e informação dessas entidades;\n(e) O direito de efetuar auditorias ou o direito de receber relatórios de auditoria;\n(f) A obrigação de os fornecedores e prestadores de serviços lidarem com vulnerabilidades que representem um risco para a segurança dos sistemas de rede e informação das entidades pertinentes;\n(g) Requisitos relativos à subcontratação e, no caso de esta ser autorizada pelas entidades pertinentes, requisitos de cibersegurança aplicáveis aos subcontratantes, em conformidade com os requisitos de cibersegurança referidos na alínea a);\n(h) Obrigações dos fornecedores e prestadores de serviços aquando da rescisão do contrato, como, por exemplo, a recuperação e a eliminação das informações obtidas pelos fornecedores e prestadores de serviços no exercício das suas funções."}, {"id": "5.1.5", "section": "5. Segurança da cadeia de abastecimento", "text": "As entidades pertinentes têm em conta os elementos referidos nos pontos 5.1.2 e 5.1.3. no âmbito do processo de seleção de novos fornecedores e prestadores de serviços, bem como no processo de adjudicação a que se refere o ponto 6.1."}, {"id": "5.1.6", "section": "5. Segurança da cadeia de abastecimento", "text": "As entidades pertinentes analisam a política de segurança da cadeia de abastecimento e acompanham, avaliam e, se necessário, tomam medidas em resposta a alterações nas práticas de cibersegurança dos fornecedores e prestadores de serviços, a intervalos planeados e sempre que ocorram alterações significativas das operações ou dos riscos ou incidentes significativos relacionados com a prestação de serviços de TIC ou que tenham um impacto na segurança dos produtos de TIC dos fornecedores e prestadores de serviços."}, {"id": "5.1.7", "section": "5. Segurança da cadeia de abastecimento", "text": "Para efeitos do ponto 5.1.6, as entidades pertinentes:\n(a) Acompanham regularmente os relatórios sobre a aplicação dos acordos de nível de serviço, quando aplicável;\n(b) Analisam os incidentes relacionados com produtos de TIC e serviços de TIC de fornecedores e prestadores de serviços;\n(c) Avaliam a necessidade de análises não programadas e documentam as conclusões de forma compreensível;\n(d) Analisam os riscos decorrentes das alterações relacionadas com os produtos de TIC e serviços de TIC dos fornecedores e prestadores de serviços e, se for caso disso, tomam atempadamente medidas para atenuar tais riscos."}, {"id": "5.2", "section": "5. Segurança da cadeia de abastecimento", "text": "As entidades pertinentes conservam e mantêm atualizado um registo dos seus fornecedores e prestadores de serviços diretos, incluindo:\n(a) Os pontos de contacto para cada fornecedor e prestador de serviços direto;\n(b) Uma lista dos produtos de TIC, dos serviços de TIC e dos processos de TIC que o fornecedor ou o prestador de serviços direto fornece ou presta às entidades pertinentes."}, {"id": "6.1.1", "section": "6. Segurança na aquisição, desenvolvimento e manutenção dos sistemas de rede e informação", "text": "Para efeitos do artigo 21.º, n.º 2, alínea e), da Diretiva (UE) 2022/2555, as entidades pertinentes estabelecem e aplicam processos para gerir, com base na avaliação dos riscos realizada nos termos do ponto 2.1, os riscos decorrentes da aquisição, a fornecedores ou prestadores de serviços, de serviços de TIC ou produtos de TIC para componentes críticos para a segurança dos seus sistemas de rede e informação, ao longo do ciclo de vida de tais serviços ou produtos."}, {"id": "6.1.2", "section": "6. Segurança na aquisição, desenvolvimento e manutenção dos sistemas de rede e informação", "text": "Para efeitos do ponto 6.1.1, os processos aí referidos incluem:\n(a) Requisitos de segurança aplicáveis aos serviços de TIC ou produtos de TIC a adquirir;\n(b) Requisitos relacionados com atualizações de segurança ao longo de toda a vida útil dos serviços de TIC ou dos produtos de TIC, ou com a substituição após o termo do período de suporte;\n(c) Informações que descrevam os componentes de hardware e software utilizados nos serviços de TIC ou nos produtos de TIC;\n(d) Informações que descrevam as funções de cibersegurança dos serviços de TIC ou produtos de TIC implementadas e a configuração necessária para o seu funcionamento seguro;\n(e) A garantia de que os serviços de TIC ou produtos de TIC cumprem os requisitos de segurança nos termos da alínea a);\n(f) Métodos para validar o cumprimento, pelos serviços de TIC ou produtos de TIC fornecidos, dos requisitos de segurança declarados, bem como documentação dos resultados da validação."}, {"id": "6.1.3", "section": "6. Segurança na aquisição, desenvolvimento e manutenção dos sistemas de rede e informação", "text": "As entidades pertinentes analisam e, se for caso disso, atualizam os processos a intervalos planeados e sempre que ocorram incidentes significativos."}, {"id": "6.2.1", "section": "6. Segurança na aquisição, desenvolvimento e manutenção dos sistemas de rede e informação", "text": "Antes de desenvolverem um sistema de rede e informação, incluindo software, as entidades pertinentes estabelecem regras para o desenvolvimento seguro de sistemas de rede e informação e aplicam-nas aquando do desenvolvimento de sistemas de rede e informação a nível interno, ou sempre que externalizem tal desenvolvimento. As regras devem abranger todas as fases do desenvolvimento, incluindo a especificação, a conceção, o desenvolvimento, a implementação e os ensaios."}, {"id": "6.2.2", "section": "6. Segurança na aquisição, desenvolvimento e manutenção dos sistemas de rede e informação", "text": "Para efeitos do ponto 6.2.1, as entidades pertinentes:\n(a) Efetuam uma análise dos requisitos de segurança nas fases de especificação e conceção de qualquer projeto de desenvolvimento ou aquisição executado pelas mesmas ou em seu nome;\n(b) Aplicam a quaisquer atividades de desenvolvimento de sistemas de informação princípios para a engenharia de sistemas seguros e princípios de codificação segura, como a promoção da cibersegurança desde a conceção e de arquiteturas de confiança zero;\n(c) Estabelecem requisitos de segurança no que respeita aos ambientes de desenvolvimento;\n(d) Estabelecem e aplicam processos de ensaio da segurança durante o ciclo de vida do desenvolvimento;\n(e) Selecionam, protegem e gerem adequadamente os dados dos ensaios da segurança;\n(f) Limpam definitivamente e anonimizam os dados dos ensaios de acordo com a avaliação dos riscos efetuada nos termos do ponto 2.1."}, {"id": "6.2.3", "section": "6. Segurança na aquisição, desenvolvimento e manutenção dos sistemas de rede e informação", "text": "No que diz respeito à externalização do desenvolvimento de sistemas de rede e informação, as entidades pertinentes aplicam igualmente as políticas e os procedimentos a que se referem os pontos 5 e 6.1."}, {"id": "6.2.4", "section": "6. Segurança na aquisição, desenvolvimento e manutenção dos sistemas de rede e informação", "text": "As entidades pertinentes analisam e, se necessário, atualizam as suas regras de desenvolvimento seguro, a intervalos planeados."}, {"id": "6.3.1", "section": "6. Segurança na aquisição, desenvolvimento e manutenção dos sistemas de rede e informação", "text": "As entidades pertinentes tomam as medidas adequadas para estabelecer, documentar, implementar e monitorizar as configurações, incluindo as configurações de segurança do hardware, do software, dos serviços e das redes."}, {"id": "6.3.2", "section": "6. Segurança na aquisição, desenvolvimento e manutenção dos sistemas de rede e informação", "text": "Para efeitos do ponto 6.3.1, as entidades pertinentes:\n(a) Estabelecem e garantem segurança nas configurações do seu hardware, software, serviços e redes;\n(b) Estabelecem e aplicam processos e ferramentas para fazer respeitar as configurações seguras estabelecidas para o hardware, o software, os serviços e as redes, dos sistemas recém-instalados e dos sistemas já em funcionamento ao longo da sua vida útil."}, {"id": "6.3.3", "section": "6. Segurança na aquisição, desenvolvimento e manutenção dos sistemas de rede e informação", "text": "As entidades pertinentes analisam e, se for caso disso, atualizam as configurações a intervalos planeados e sempre que ocorram incidentes significativos ou alterações significativas das operações ou dos riscos."}, {"id": "6.4.1", "section": "6. Segurança na aquisição, desenvolvimento e manutenção dos sistemas de rede e informação", "text": "As entidades pertinentes aplicam procedimentos de gestão das alterações para controlar as alterações dos sistemas de rede e informação. Quando aplicável, os procedimentos devem ser coerentes com as políticas gerais das entidades pertinentes em matéria de gestão das alterações."}, {"id": "6.4.2", "section": "6. Segurança na aquisição, desenvolvimento e manutenção dos sistemas de rede e informação", "text": "Os procedimentos a que se refere o ponto 6.4.1 devem ser aplicados a novas versões, modificações e alterações de emergência de qualquer software e hardware em funcionamento, bem como a alterações da configuração. Os procedimentos devem assegurar que tais alterações são documentadas e, antes de serem aplicadas, são testadas e avaliadas tendo em conta o impacto potencial, com base na avaliação dos riscos realizada nos termos do ponto 2.1."}, {"id": "6.4.3", "section": "6. Segurança na aquisição, desenvolvimento e manutenção dos sistemas de rede e informação", "text": "Caso uma emergência leve a que seja impossível seguir os procedimentos regulares de gestão das alterações, as entidades pertinentes documentam o resultado da alteração, bem como uma explicação das razões pelas quais não foi possível seguir os procedimentos."}, {"id": "6.4.4", "section": "6. Segurança na aquisição, desenvolvimento e manutenção dos sistemas de rede e informação", "text": "As entidades pertinentes analisam e, se for caso disso, atualizam os procedimentos a intervalos planeados e sempre que ocorram incidentes significativos ou alterações significativas das operações ou dos riscos."}, {"id": "6.5.1", "section": "6. Segurança na aquisição, desenvolvimento e manutenção dos sistemas de rede e informação", "text": "As entidades pertinentes estabelecem, implementam e aplicam uma política e procedimentos para os ensaios da segurança."}, {"id": "6.5.2", "section": "6. Segurança na aquisição, desenvolvimento e manutenção dos sistemas de rede e informação", "text": "As entidades pertinentes:\n(a) Estabelecem, com base na avaliação dos riscos efetuada nos termos do ponto 2.1., a necessidade, o âmbito, a frequência e o tipo de ensaios da segurança;\n(b) Realizam ensaios da segurança de acordo com uma metodologia de ensaio documentada, abrangendo os componentes que uma análise dos riscos tenha identificado como pertinentes para o funcionamento seguro;\n(c) Documentam o tipo, o âmbito, a data e os resultados dos ensaios, incluindo a avaliação da criticalidade e as medidas de atenuação para cada constatação;\n(d) Aplicam medidas de atenuação em caso de constatações críticas."}, {"id": "6.5.3", "section": "6. Segurança na aquisição, desenvolvimento e manutenção dos sistemas de rede e informação", "text": "As entidades pertinentes analisam e, se for caso disso, atualizam as suas políticas de ensaios da segurança, a intervalos planeados."}, {"id": "6.6.1", "section": "6. Segurança na aquisição, desenvolvimento e manutenção dos sistemas de rede e informação", "text": "As entidades pertinentes especificam e aplicam procedimentos, coerentes com os procedimentos de gestão das alterações a que se refere o ponto 6.4.1., bem como com os procedimentos de gestão de vulnerabilidades, gestão dos riscos e outros procedimentos de gestão pertinentes, para assegurar que:\n(a) As correções de segurança são aplicadas num prazo razoável após ficarem disponíveis;\n(b) As correções de segurança são testadas antes de serem aplicadas nos sistemas de produção;\n(c) As correções de segurança provêm de fontes fiáveis e a sua integridade é verificada;\n(d) São aplicadas medidas adicionais e são aceites os riscos residuais nos casos em que não esteja disponível ou não seja aplicada uma correção nos termos do ponto 6.6.2."}, {"id": "6.6.2", "section": "6. Segurança na aquisição, desenvolvimento e manutenção dos sistemas de rede e informação", "text": "Em derrogação do ponto 6.6.1, alínea a), as entidades pertinentes podem optar por não aplicar correções de segurança caso as desvantagens da aplicação dessas correções superem os benefícios em matéria de cibersegurança. Caso tomem essa decisão, documentam e fundamentam devidamente as razões subjacentes."}, {"id": "6.7.1", "section": "6. Segurança na aquisição, desenvolvimento e manutenção dos sistemas de rede e informação", "text": "As entidades pertinentes tomam as medidas adequadas para proteger os seus sistemas de rede e informação contra ciberameaças."}, {"id": "6.7.2", "section": "6. Segurança na aquisição, desenvolvimento e manutenção dos sistemas de rede e informação", "text": "Para efeitos do ponto 6.7.1, as entidades pertinentes:\n(a) Documentam a arquitetura da rede de forma compreensível e atualizada;\n(b) Determinam e aplicam controlos para proteger os domínios de rede internos das entidades pertinentes contra o acesso não autorizado;\n(c) Configuram controlos para impedir os acessos e a comunicação em rede não necessários para o funcionamento das entidades pertinentes;\n(d) Determinam e aplicam controlos ao acesso remoto aos sistemas de rede e informação, incluindo o acesso por parte de prestadores de serviços;\n(e) Abstêm-se de utilizar para outros fins os sistemas utilizados para gerir a execução da política de segurança;\n(f) Proíbem ou desativam explicitamente ligações e serviços desnecessários;\n(g) Se for caso disso, permitem o acesso aos respetivos sistemas de rede e informação exclusivamente a dispositivos por si autorizados;\n(h) Apenas permitem ligações de prestadores de serviços na sequência de um pedido de autorização e por um período específico, como a duração de uma operação de manutenção;\n(i) Estabelecem a comunicação entre sistemas distintos apenas por meio de canais de confiança isolados de outros canais de comunicação através de uma separação lógica, criptográfica ou física e preveem a identificação segura dos seus pontos terminais e a proteção dos dados do canal contra alterações ou divulgação;\n(j) Adotam um plano de execução para a transição plena para protocolos de comunicação de camadas de rede da última geração de forma segura, adequada e gradual, e estabelecem medidas para acelerar essa transição;\n(k) Adotam um plano de execução para a implantação de normas modernas, internacionalmente acordadas e interoperáveis em matéria de comunicações por correio eletrónico, de modo a proteger tais comunicações e a atenuar as vulnerabilidades associadas às ameaças relacionadas com o correio eletrónico, e estabelecem medidas para acelerar essa implantação;\n(l) Aplicam as melhores práticas no que se refere à segurança do DNS, à segurança do encaminhamento na Internet e à higiene do encaminhamento do tráfego com origem e destino na rede."}, {"id": "6.7.3", "section": "6. Segurança na aquisição, desenvolvimento e manutenção dos sistemas de rede e informação", "text": "As entidades pertinentes analisam e, se for caso disso, atualizam essas medidas a intervalos planeados e sempre que ocorram incidentes significativos ou alterações significativas das operações ou dos riscos."}, {"id": "6.8.1", "section": "6. Segurança na aquisição, desenvolvimento e manutenção dos sistemas de rede e informação", "text": "As entidades pertinentes segmentam os sistemas em redes ou zonas, em conformidade com os resultados da avaliação dos riscos a que se refere o ponto 2.1. Asseguram a segmentação dos seus sistemas e redes face aos sistemas e redes de terceiros."}, {"id": "6.8.2", "section": "6. Segurança na aquisição, desenvolvimento e manutenção dos sistemas de rede e informação", "text": "Para o efeito, as entidades pertinentes:\n(a) Têm em conta a relação funcional, lógica e física, incluindo a localização, entre sistemas e serviços fiáveis;\n(b) Concedem acesso a uma rede ou zona com base numa avaliação dos respetivos requisitos de segurança;\n(c) Mantêm os sistemas críticos para o funcionamento das entidades pertinentes ou para a segurança em zonas protegidas;\n(d) Implantam uma zona desmilitarizada nas suas redes de comunicação, a fim de garantir a segurança da comunicação com origem nas suas redes ou com destino às mesmas;\n(e) Limitam o acesso e as comunicações entre e dentro das zonas ao necessário para o funcionamento das entidades pertinentes ou para garantir a segurança;\n(f) Separam a rede específica para a administração dos sistemas de rede e informação da rede operacional das entidades pertinentes;\n(g) Separam os canais de administração da rede de outro tráfego da rede;\n(h) Separam os sistemas de produção dos serviços das entidades pertinentes dos sistemas utilizados no desenvolvimento e nos ensaios, incluindo as cópias de segurança."}, {"id": "6.8.3", "section": "6. Segurança na aquisição, desenvolvimento e manutenção dos sistemas de rede e informação", "text": "As entidades pertinentes analisam e, se for caso disso, atualizam a segmentação da rede a intervalos planeados e sempre que ocorram incidentes significativos ou alterações significativas das operações ou dos riscos."}, {"id": "6.9.1", "section": "6. Segurança na aquisição, desenvolvimento e manutenção dos sistemas de rede e informação", "text": "As entidades pertinentes protegem os seus sistemas de rede e informação contra software malicioso e não autorizado."}, {"id": "6.9.2", "section": "6. Segurança na aquisição, desenvolvimento e manutenção dos sistemas de rede e informação", "text": "Para o efeito, as entidades pertinentes devem, em especial, aplicar medidas que detetem ou impeçam a utilização de software malicioso e não autorizado. As entidades pertinentes asseguram, se for caso disso, que os seus sistemas de rede e informação estão dotados de software de deteção e resposta, sendo esse software atualizado regularmente em conformidade com a avaliação dos riscos efetuada nos termos do ponto 2.1. e com os acordos contratuais celebrados com os fornecedores."}, {"id": "6.10.1", "section": "6. Segurança na aquisição, desenvolvimento e manutenção dos sistemas de rede e informação", "text": "As entidades pertinentes obtêm informações sobre as vulnerabilidades técnicas dos seus sistemas de rede e informação, avaliam a sua exposição a essas vulnerabilidades e tomam medidas adequadas para geri-las."}, {"id": "6.10.2", "section": "6. Segurança na aquisição, desenvolvimento e manutenção dos sistemas de rede e informação", "text": "Para efeitos do ponto 6.10.1., as entidades pertinentes:\n(a) Monitorizam as informações sobre vulnerabilidades através de canais adequados, tais como anúncios das CSIRT ou das autoridades competentes ou informações fornecidas por fornecedores ou prestadores de serviços;\n(b) Realizam a intervalos planeados, se for caso disso, análises da vulnerabilidade e registam os elementos de prova dos respetivos resultados;\n(c) Dão resposta, sem demora injustificada, às vulnerabilidades que identificaram como sendo críticas para as suas operações;\n(d) Asseguram que o seu tratamento das vulnerabilidades é compatível com os seus procedimentos de gestão de alterações, gestão de correções de segurança, gestão dos riscos e gestão de incidentes;\n(e) Estabelecem um procedimento para a divulgação de vulnerabilidades em conformidade com a política nacional aplicável em matéria de divulgação coordenada de vulnerabilidades."}, {"id": "6.10.3", "section": "6. Segurança na aquisição, desenvolvimento e manutenção dos sistemas de rede e informação", "text": "Sempre que o impacto potencial da vulnerabilidade o justifique, as entidades pertinentes elaboram e aplicam um plano para atenuar a vulnerabilidade. Noutros casos, as entidades pertinentes devem documentar e fundamentar o motivo pelo qual a vulnerabilidade não exige correção."}, {"id": "6.10.4", "section": "6. Segurança na aquisição, desenvolvimento e manutenção dos sistemas de rede e informação", "text": "As entidades pertinentes analisam e, se for caso disso, atualizam, a intervalos planeados, os canais que utilizam para monitorizar as informações sobre as vulnerabilidades."}, {"id": "7.1", "section": "7. Políticas e procedimentos para avaliar a eficácia das medidas de gestão dos riscos de cibersegurança", "text": "Para efeitos do artigo 21.º, n.º 2, alínea f), da Diretiva (UE) 2022/2555, as entidades pertinentes estabelecem, executam e aplicam uma política e procedimentos para avaliar se as medidas de gestão dos riscos de cibersegurança por si adotadas são aplicadas e mantidas de forma eficaz."}, {"id": "7.2", "section": "7. Políticas e procedimentos para avaliar a eficácia das medidas de gestão dos riscos de cibersegurança", "text": "A política e os procedimentos a que se refere o ponto 7.1 têm em conta os resultados da avaliação dos riscos efetuada ao abrigo do ponto 2.1, bem como incidentes significativos anteriores. As entidades pertinentes determinam:\n(a) Que medidas de gestão dos riscos de cibersegurança devem ser monitorizadas e medidas, incluindo processos e controlos;\n(b) Os métodos de monitorização, medição, análise e avaliação, conforme aplicáveis, para assegurar resultados válidos;\n(c) Quando se deve proceder à monitorização e à medição;\n(d) Quem é responsável pela monitorização e medição da eficácia das medidas de gestão dos riscos de cibersegurança;\n(e) Quando se deve proceder à análise e à avaliação dos resultados da monitorização e da medição;\n(f) Quem fica encarregado de analisar e avaliar estes resultados."}, {"id": "7.3", "section": "7. Políticas e procedimentos para avaliar a eficácia das medidas de gestão dos riscos de cibersegurança", "text": "As entidades pertinentes analisam e, se for caso disso, atualizam as políticas e os procedimentos a intervalos planeados e sempre que ocorram incidentes significativos ou alterações significativas das operações ou dos riscos."}, {"id": "8.1.1", "section": "8. Práticas básicas de ciber-higiene e formação em cibersegurança", "text": "Para efeitos do artigo 21.º, n.º 2, alínea g), da Diretiva (UE) 2022/2555, as entidades pertinentes asseguram que os seus trabalhadores, incluindo os membros dos órgãos de direção, bem como os fornecedores e prestadores de serviços diretos, estão cientes dos riscos, são informados da importância da cibersegurança e aplicam práticas de ciber-higiene."}, {"id": "8.1.2", "section": "8. Práticas básicas de ciber-higiene e formação em cibersegurança", "text": "Para efeitos do ponto 8.1.1., as entidades pertinentes propõem aos seus trabalhadores, incluindo os membros dos órgãos de direção, bem como aos fornecedores e prestadores de serviços diretos, se for caso disso, nos termos do ponto 5.1.4., um programa de sensibilização que:\n(a) Seja programado ao longo do tempo, de modo a que as atividades se repitam e abranjam novos trabalhadores;\n(b) Seja estabelecido em consonância com a política de segurança das redes e da informação, as políticas temáticas e os procedimentos pertinentes em matéria de segurança das redes e da informação;\n(c) Abranja as ciberameaças pertinentes, as medidas de gestão dos riscos de cibersegurança em vigor, os pontos de contacto e recursos para informações adicionais e aconselhamento em matéria de cibersegurança, bem como práticas de ciber-higiene para os utilizadores."}, {"id": "8.1.3", "section": "8. Práticas básicas de ciber-higiene e formação em cibersegurança", "text": "A eficácia do programa de sensibilização deve, se for caso disso, ser testada. O programa de sensibilização deve ser atualizado e proposto a intervalos planeados, tendo em conta as alterações das práticas de ciber-higiene e o panorama de ameaças e os riscos que se colocam atualmente às entidades pertinentes."}, {"id": "8.2.1", "section": "8. Práticas básicas de ciber-higiene e formação em cibersegurança", "text": "As entidades pertinentes identificam os trabalhadores cujas funções requeiram conjuntos de competências e conhecimentos especializados pertinentes para a segurança e garantem que recebem periodicamente formação sobre a segurança do sistema de rede e informação."}, {"id": "8.2.2", "section": "8. Práticas básicas de ciber-higiene e formação em cibersegurança", "text": "As entidades pertinentes estabelecem, implementam e aplicam, em conformidade com a política de segurança das redes e da informação, as políticas temáticas e outros procedimentos pertinentes em matéria de segurança das redes e da informação, um programa de formação que estabeleça, com base em critérios, as necessidades de formação para determinadas funções e cargos."}, {"id": "8.2.3", "section": "8. Práticas básicas de ciber-higiene e formação em cibersegurança", "text": "A formação a que se refere o ponto 8.2.1 deve ser relevante para a função profissional do trabalhador e a sua eficácia deve ser avaliada. A formação deve ter em conta as medidas de segurança em vigor e abranger o seguinte:\n(a) Instruções sobre a configuração e o funcionamento seguros dos sistemas de rede e informação, incluindo os dispositivos móveis;\n(b) Informações sobre ciberameaças conhecidas;\n(c) Formação sobre o comportamento a adotar em caso de eventos com impacto na segurança."}, {"id": "8.2.4", "section": "8. Práticas básicas de ciber-higiene e formação em cibersegurança", "text": "As entidades pertinentes ministram formação aos membros do pessoal que assumam novos cargos ou funções que requeiram conjuntos de competências e conhecimentos especializados pertinentes para a segurança."}, {"id": "8.2.5", "section": "8. Práticas básicas de ciber-higiene e formação em cibersegurança", "text": "O programa é atualizado e executado periodicamente tendo em conta as políticas e regras aplicáveis, as funções atribuídas, as responsabilidades, as ciberameaças conhecidas e a evolução tecnológica."}, {"id": "9.1", "section": "9. Criptografia", "text": "Para efeitos do artigo 21.º, n.º 2, alínea h), da Diretiva (UE) 2022/2555, as entidades pertinentes estabelecem, executam e aplicam uma política e procedimentos relacionados com a criptografia, com vista a assegurar uma utilização adequada e eficaz da criptografia para proteger a confidencialidade, a autenticidade e a integridade dos dados, em consonância com a classificação dos ativos levada a cabo pelas entidades pertinentes e com os resultados da avaliação dos riscos realizada nos termos do ponto 2.1."}, {"id": "9.2", "section": "9. Criptografia", "text": "A política e os procedimentos a que se refere o ponto 9.1. estabelecem:\n(a) Em conformidade com a classificação de ativos das entidades pertinentes, o tipo, a força e a qualidade das medidas criptográficas necessárias para proteger os ativos das referidas entidades, incluindo os dados inativos e os dados em trânsito;\n(b) Com base na alínea a), os protocolos ou as famílias de protocolos a adotar, bem como os algoritmos criptográficos, a força da cifra, as soluções criptográficas e as práticas de utilização a aprovar e a impor nas entidades pertinentes, seguindo, se for caso disso, uma abordagem de agilidade criptográfica;\n(c) A abordagem das entidades pertinentes no que toca à gestão de chaves, incluindo, se for caso disso, métodos para:\ni) gerar diferentes chaves para sistemas e aplicações criptográficos,\nii) emitir e obter certificados de chave pública,\niii) distribuir chaves às entidades previstas, incluindo a forma de ativar as chaves após a sua receção,\niv) armazenar chaves, incluindo a forma como os utilizadores autorizados obtêm acesso às chaves,\nv) alterar ou atualizar chaves, incluindo regras sobre quando e como proceder a alterações,\nvi) lidar com chaves comprometidas,\nvii) revogar chaves, incluindo a forma de retirar ou desativar chaves,\nviii) recuperar chaves perdidas ou corrompidas,\nix) arquivar chaves ou efetuar cópias de segurança das mesmas,\nx) destruir chaves,\nxi) registar e auditar atividades fundamentais relacionadas com a gestão de chaves,\nxii) fixar datas de ativação e desativação das chaves, assegurando que estas só possam ser utilizadas durante o período especificado, de acordo com as regras da organização em matéria de gestão de chaves."}, {"id": "9.3", "section": "9. Criptografia", "text": "As entidades pertinentes analisam e, se for caso disso, atualizam as políticas e os procedimentos a intervalos planeados, tendo em conta o progresso técnico no domínio da criptografia."}, {"id": "10.1.1", "section": "10. Segurança dos recursos humanos", "text": "Para efeitos do artigo 21.º, n.º 2, alínea i), da Diretiva (UE) 2022/2555, as entidades pertinentes asseguram que os seus trabalhadores e o seus fornecedores e prestadores de serviços diretos, se for caso disso, compreendem e assumem as suas responsabilidades em matéria de segurança, em função dos serviços oferecidos e do cargo desempenhado e em consonância com a política das entidades pertinentes em matéria de segurança dos sistemas de rede e informação."}, {"id": "10.1.2", "section": "10. Segurança dos recursos humanos", "text": "O requisito a que se refere o ponto 10.1.1 inclui o seguinte:\n(a) Mecanismos para assegurar que, sempre que aplicável, todos os trabalhadores e todos os fornecedores e prestadores de serviços diretos compreendem e seguem as práticas normalizadas de ciber-higiene que as entidades pertinentes aplicam nos termos do ponto 8.1;\n(b) Mecanismos para assegurar que todos os utilizadores com acesso administrativo ou privilegiado conhecem e agem em conformidade com as suas funções, responsabilidades e autoridades;\n(c) Mecanismos para assegurar que os membros dos órgãos de direção compreendem e agem em conformidade com as suas funções, responsabilidades e autoridades em matéria de segurança do sistema de rede e informação;\n(d) Mecanismos de contratação de pessoal qualificado para as respetivas funções, tais como verificações das referências, procedimentos de avaliação, validação de certificações ou provas escritas."}, {"id": "10.1.3", "section": "10. Segurança dos recursos humanos", "text": "A intervalos planeados e, pelo menos, uma vez por ano, as entidades pertinentes analisam a afetação de pessoal a funções específicas, tal como referido no ponto 1.2, bem como os recursos humanos que disponibilizam a esse respeito. Sempre que necessário, atualizam a afetação."}, {"id": "10.2.1", "section": "10. Segurança dos recursos humanos", "text": "As entidades pertinentes asseguram, na medida do possível, a verificação dos antecedentes dos seus trabalhadores e, quando aplicável, dos fornecedores e prestadores de serviços diretos, em conformidade com o ponto 5.1.4, se tal for necessário para efeitos das suas funções, responsabilidades e autoridades."}, {"id": "10.2.2", "section": "10. Segurança dos recursos humanos", "text": "Para efeitos do ponto 10.2.1, as entidades pertinentes:\n(a) Estabelecem critérios que definam que funções, responsabilidades e autoridades só podem ser exercidas por pessoas cujos antecedentes tenham sido verificados;\n(b) Asseguram que a verificação a que se refere o ponto 10.2.1 é realizada antes de as pessoas começarem a exercer essas funções, responsabilidades e autoridades, e tem em conta as disposições legislativas, regulamentares e deontológicas aplicáveis, de forma proporcionada em relação aos requisitos empresariais, à classificação dos ativos a que se refere o ponto 12.1, aos sistemas de rede e informação a aceder e aos riscos percecionados."}, {"id": "10.2.3", "section": "10. Segurança dos recursos humanos", "text": "As entidades pertinentes analisam e, se for caso disso, atualizam a política a intervalos planeados e sempre que necessário."}, {"id": "10.3.1", "section": "10. Segurança dos recursos humanos", "text": "As entidades pertinentes asseguram que sejam contratualmente definidos e aplicados os deveres e responsabilidades em matéria de segurança do sistema de rede e informação que permaneçam válidos após a cessação ou alteração do vínculo laboral dos seus trabalhadores."}, {"id": "10.3.2", "section": "10. Segurança dos recursos humanos", "text": "Para efeitos do ponto 10.3.1, as entidades pertinentes incluem nos termos e condições de trabalho, no contrato ou no acordo celebrado com a pessoa em questão, as responsabilidades e deveres que permanecem válidos após a cessação do vínculo laboral ou a rescisão do contrato, tais como cláusulas de confidencialidade."}, {"id": "10.4.1", "section": "10. Segurança dos recursos humanos", "text": "As entidades pertinentes estabelecem, comunicam e mantêm um processo disciplinar para o tratamento de violações das políticas de segurança do sistema de rede e informação. Esse processo tem em conta os requisitos legais, estatutários, contratuais e empresariais pertinentes."}, {"id": "10.4.2", "section": "10. Segurança dos recursos humanos", "text": "As entidades pertinentes analisam e, se for caso disso, atualizam o processo disciplinar a intervalos planeados e sempre que necessário em virtude de alterações jurídicas ou de alterações significativas das operações ou dos riscos."}, {"id": "11.1.1", "section": "11. Controlo do acesso", "text": "Para efeitos do artigo 21.º, n.º 2, alínea i), da Diretiva (UE) 2022/2555, as entidades pertinentes estabelecem, documentam e aplicam políticas de controlo do acesso lógico e físico no que respeita ao acesso aos seus sistemas de rede e informação, com base nos requisitos empresariais e nos requisitos de segurança do sistema de rede e informação."}, {"id": "11.1.2", "section": "11. Controlo do acesso", "text": "As políticas a que se refere o ponto 11.1.1:\n(a) Abordam o acesso de pessoas, incluindo pessoal, visitantes e entidades externas, como fornecedores e prestadores de serviços;\n(b) Abordam o acesso por parte de sistemas de rede e informação;\n(c) Asseguram que o acesso só é concedido a utilizadores que tenham sido devidamente autenticados."}, {"id": "11.1.3", "section": "11. Controlo do acesso", "text": "As entidades pertinentes analisam e, se for caso disso, atualizam as políticas a intervalos planeados e sempre que ocorram incidentes significativos ou alterações significativas das operações ou dos riscos."}, {"id": "11.2.1", "section": "11. Controlo do acesso", "text": "As entidades pertinentes concedem, alteram, retiram e documentam os direitos de acesso aos sistemas de rede e informação em conformidade com a política de controlo do acesso a que se refere o ponto 11.1."}, {"id": "11.2.2", "section": "11. Controlo do acesso", "text": "As entidades pertinentes:\n(a) Atribuem e revogam os direitos de acesso com base nos princípios da necessidade de tomar conhecimento, do menor privilégio e da separação de funções;\n(b) Asseguram que os direitos de acesso sejam alterados em conformidade após a cessação ou alteração do vínculo laboral;\n(c) Asseguram que o acesso aos sistemas de rede e informação seja autorizado pelas pessoas pertinentes;\n(d) Asseguram que os direitos de acesso abordam adequadamente o acesso de terceiros, como visitantes, fornecedores e prestadores de serviços, nomeadamente através da limitação do âmbito e da duração de tais direitos;\n(e) Mantêm um registo dos direitos de acesso concedidos;\n(f) Procedem ao registo da gestão dos direitos de acesso."}, {"id": "11.2.3", "section": "11. Controlo do acesso", "text": "As entidades pertinentes analisam os direitos de acesso a intervalos planeados e alteram-nos com base em alterações organizacionais. As entidades pertinentes documentam os resultados da análise, incluindo as alterações necessárias dos direitos de acesso."}, {"id": "11.3.1", "section": "11. Controlo do acesso", "text": "As entidades pertinentes mantêm políticas de gestão das contas privilegiadas e das contas de administração do sistema no âmbito da política de controlo do acesso a que se refere o ponto 11.1."}, {"id": "11.3.2", "section": "11. Controlo do acesso", "text": "As políticas a que se refere o ponto 11.3.1:\n(a) Estabelecem fortes procedimentos de identificação, autenticação (autenticação multifatores, por exemplo) e autorização para as contas privilegiadas e as contas de administração do sistema;\n(b) Estabelecem contas específicas a utilizar exclusivamente para as operações de administração do sistema, tais como a instalação, a configuração, a gestão ou a manutenção;\n(c) Individualizam e restringem, tanto quanto possível, os privilégios de administração do sistema;\n(d) Preveem que as contas de administração do sistema só sejam utilizadas para efeitos de ligação a sistemas de administração do sistema."}, {"id": "11.3.3", "section": "11. Controlo do acesso", "text": "As entidades pertinentes analisam os direitos de acesso das contas privilegiadas e das contas de administração do sistema a intervalos planeados, modificando-os com base em alterações organizacionais, e documentam os resultados da análise, incluindo as alterações necessárias dos direitos de acesso."}, {"id": "11.4.1", "section": "11. Controlo do acesso", "text": "As entidades pertinentes restringem e controlam a utilização de sistemas de administração do sistema em conformidade com a política de controlo do acesso a que se refere o ponto 11.1."}, {"id": "11.4.2", "section": "11. Controlo do acesso", "text": "Para o efeito, as entidades pertinentes:\n(a) Utilizam os sistemas de administração do sistema exclusivamente para fins de administração do sistema, e não para outras operações;\n(b) Separam logicamente esses sistemas do software de aplicação não utilizado para fins de administração do sistema;\n(c) Protegem o acesso aos sistemas de administração do sistema através de autenticação e de cifragem."}, {"id": "11.5.1", "section": "11. Controlo do acesso", "text": "As entidades pertinentes gerem todo o ciclo de vida das identidades dos sistemas de rede e informação e dos respetivos utilizadores."}, {"id": "11.5.2", "section": "11. Controlo do acesso", "text": "Para o efeito, as entidades pertinentes:\n(a) Criam identidades únicas para os sistemas de rede e informação e para os respetivos utilizadores;\n(b) Associam a identidade dos utilizadores a uma única pessoa;\n(c) Asseguram a supervisão das identidades dos sistemas de rede e informação;\n(d) Procedem ao registo da gestão das identidades."}, {"id": "11.5.3", "section": "11. Controlo do acesso", "text": "As entidades pertinentes apenas autorizam identidades atribuídas a várias pessoas (por exemplo, identidades partilhadas) caso sejam necessárias por razões comerciais ou operacionais, e na condição de serem documentadas e de estarem sujeitas a um processo de aprovação explícita. As entidades pertinentes têm em conta as identidades atribuídas a várias pessoas no quadro de gestão dos riscos de cibersegurança a que se refere o ponto 2.1."}, {"id": "11.5.4", "section": "11. Controlo do acesso", "text": "As entidades pertinentes analisam regularmente as identidades criadas para os sistemas de rede e informação e os respetivos utilizadores e, caso já não sejam necessárias, desativam-nas sem demora."}, {"id": "11.6.1", "section": "11. Controlo do acesso", "text": "As entidades pertinentes aplicam procedimentos e tecnologias de autenticação seguros, baseados em restrições de acesso e na política de controlo do acesso."}, {"id": "11.6.2", "section": "11. Controlo do acesso", "text": "Para o efeito, as entidades pertinentes:\n(a) Asseguram que a força de autenticação é adequada à classificação do ativo a que se acederá;\n(b) Controlam atribuição aos utilizadores e a gestão de informações de autenticação secretas através de um processo que garanta a confidencialidade das informações, incluindo mediante a prestação de aconselhamento ao pessoal sobre o tratamento adequado das informações de autenticação;\n(c) Exigem a alteração das credenciais de autenticação aquando da sua atribuição inicial, a intervalos predefinidos e em caso de suspeita de comprometimento das mesmas;\n(d) Exigem a redefinição das credenciais de autenticação e o bloqueio dos utilizadores após um número predefinido de tentativas de início de sessão falhadas;\n(e) Põem termo às sessões inativas após um período predefinido de inatividade; e\n(f) Exigem credenciais separadas para aceder a contas privilegiadas ou a contas administrativas."}, {"id": "11.6.3", "section": "11. Controlo do acesso", "text": "As entidades pertinentes utilizam, na medida do possível, informações de autenticação únicas, bem como métodos de autenticação de ponta, em conformidade com o risco conexo avaliado e com a classificação do ativo a que se acederá."}, {"id": "11.6.4", "section": "11. Controlo do acesso", "text": "As entidades pertinentes analisam os procedimentos e tecnologias de autenticação a intervalos planeados."}, {"id": "11.7.1", "section": "11. Controlo do acesso", "text": "As entidades pertinentes asseguram que os utilizadores são autenticados por vários fatores de autenticação ou por mecanismos de autenticação contínua para efeitos de acesso aos seus sistemas de rede e informação, se for caso disso, em conformidade com a classificação do ativo a que se acederá."}, {"id": "11.7.2", "section": "11. Controlo do acesso", "text": "As entidades pertinentes asseguram que a força de autenticação é adequada à classificação do ativo a que se acederá."}, {"id": "12.1.1", "section": "12. Gestão de ativos", "text": "Para efeitos do artigo 21.º, n.º 2, alínea i), da Diretiva (UE) 2022/2555, as entidades pertinentes estabelecem níveis de classificação de todos os ativos, incluindo informações, abrangidos pelos seus sistemas de rede e informação para o nível de proteção exigido."}, {"id": "12.1.2", "section": "12. Gestão de ativos", "text": "Para efeitos do ponto 12.1.1, as entidades pertinentes:\n(a) Estabelecem um sistema de níveis de classificação dos ativos;\n(b) Atribuem um nível de classificação a todos os ativos, com base em requisitos de confidencialidade, integridade, autenticidade e disponibilidade, a fim de indicar a proteção necessária de acordo com a respetiva sensibilidade, criticalidade, risco e valor comercial;\n(c) Alinham os requisitos de disponibilidade dos ativos com os objetivos de execução e recuperação estabelecidos nos seus planos de continuidade das atividades e de recuperação de desastres."}, {"id": "12.1.3", "section": "12. Gestão de ativos", "text": "As entidades pertinentes analisam periodicamente os níveis de classificação dos ativos e atualizam-nos, se for caso disso."}, {"id": "12.2.1", "section": "12. Gestão de ativos", "text": "As entidades pertinentes estabelecem, implementam e aplicam uma política de tratamento adequado de ativos, incluindo informações, em conformidade com a sua política de segurança das redes e da informação, e comunicam essa política de tratamento a qualquer pessoa que utilize ou trate ativos."}, {"id": "12.2.2", "section": "12. Gestão de ativos", "text": "A política deve:\n(a) Abranger todo o ciclo de vida dos ativos, incluindo a aquisição, a utilização, o armazenamento, o transporte e a eliminação;\n(b) Prever regras sobre a utilização segura, o armazenamento seguro, o transporte seguro e a supressão e a destruição irreversíveis dos ativos;\n(c) Prever que a transferência seja efetuada de forma segura, de acordo com o tipo de ativo a transferir."}, {"id": "12.2.3", "section": "12. Gestão de ativos", "text": "As entidades pertinentes analisam e, se for caso disso, atualizam a política a intervalos planeados e sempre que ocorram incidentes significativos ou alterações significativas das operações ou dos riscos."}, {"id": "12.3.1", "section": "12. Gestão de ativos", "text": "As entidades pertinentes estabelecem, implementam e aplicam uma política de gestão dos suportes de armazenamento amovíveis e comunicam-na aos seus trabalhadores e a terceiros que manuseiem suportes de armazenamento amovíveis nas instalações das entidades pertinentes ou noutros locais em que os suportes amovíveis sejam ligados aos sistemas de rede e informação das entidades pertinentes."}, {"id": "12.3.2", "section": "12. Gestão de ativos", "text": "A política deve:\n(a) Prever a proibição técnica da ligação de suportes amovíveis, a menos que exista uma razão organizacional para a sua utilização;\n(b) Prever a desativação da autoexecução a partir desses suportes e a deteção de códigos maliciosos nos mesmos, antes de serem utilizados nos sistemas das entidades pertinentes;\n(c) Prever medidas de controlo e proteção dos dispositivos portáteis de armazenamento que contenham dados, durante o trânsito e o armazenamento desses dispositivos;\n(d) Se for caso disso, prever medidas para a utilização de técnicas criptográficas para proteger os dados em suportes de armazenamento amovíveis."}, {"id": "12.3.3", "section": "12. Gestão de ativos", "text": "As entidades pertinentes analisam e, se for caso disso, atualizam a política a intervalos planeados e sempre que ocorram incidentes significativos ou alterações significativas das operações ou dos riscos."}, {"id": "12.4.1", "section": "12. Gestão de ativos", "text": "As entidades pertinentes elaboram e mantêm um inventário exaustivo, exato, atualizado e coerente dos seus ativos. Registam, de forma rastreável, quaisquer alterações às entradas do inventário."}, {"id": "12.4.2", "section": "12. Gestão de ativos", "text": "A granularidade do inventário de ativos deve ser adequada às necessidades das entidades pertinentes. Esse inventário inclui o seguinte:\n(a) A lista de operações e serviços e a respetiva descrição;\n(b) A lista de sistemas de rede e informação e outros ativos conexos que apoiam as operações e os serviços das entidades pertinentes."}, {"id": "12.4.3", "section": "12. Gestão de ativos", "text": "As entidades pertinentes analisam e atualizam regularmente o inventário e os seus ativos e documentam o histórico de alterações."}, {"id": "12.5", "section": "12. Gestão de ativos", "text": "As entidades pertinentes estabelecem, implementam e aplicam procedimentos que assegurem que ativos seus sob a custódia de pessoal sejam depositados, devolvidos ou suprimidos após a cessação do vínculo laboral, e documentam o depósito, a devolução e a supressão desses ativos. Se o depósito, devolução ou supressão de ativos não for possível, as entidades pertinentes devem assegurar que os ativos deixam de poder aceder aos seus sistemas de rede e informação em conformidade com o ponto 12.2.2."}, {"id": "13.1.1", "section": "13. Segurança ambiental e física", "text": "Para efeitos do artigo 21.º, n.º 2, alínea c), da Diretiva (UE) 2022/2555, as entidades pertinentes evitam perdas, danos ou o comprometimento dos sistemas de rede e informação ou a interrupção das suas operações devido a falhas e perturbações dos serviços de utilidade pública de apoio."}, {"id": "13.1.2", "section": "13. Segurança ambiental e física", "text": "Para o efeito, as entidades pertinentes devem, se for caso disso:\n(a) Proteger as instalações de cortes de eletricidade e outras perturbações causadas por falhas nos serviços de utilidade pública de apoio, como a eletricidade, as telecomunicações, o abastecimento de água, o gás, os esgotos, a ventilação e o ar condicionado;\n(b) Ponderar o recurso à redundância nos serviços de utilidade pública;\n(c) Proteger de interceções e danos os serviços de utilidade pública de eletricidade e telecomunicações que transportam dados ou abastecem os sistemas de rede e informação;\n(d) Monitorizar os serviços de utilidade pública a que se refere a alínea c) e comunicar ao pessoal competente, a nível interno ou externo, eventos fora dos limiares de controlo mínimos e máximos a que se refere o ponto 13.2.2., alínea b), e que afetem os serviços de utilidade pública;\n(e) Celebrar contratos de fornecimento de emergência com os serviços correspondentes, designadamente para combustível para fornecimento de energia de emergência;\n(f) Assegurar a eficácia contínua, monitorizar, manter e testar o fornecimento dos sistemas de rede e informação necessário ao funcionamento do serviço oferecido, em especial de eletricidade, o controlo da temperatura e da humidade, as telecomunicações e a ligação à Internet."}, {"id": "13.1.3", "section": "13. Segurança ambiental e física", "text": "As entidades pertinentes testam, analisam e, se for caso disso, atualizam as medidas de proteção regularmente ou na sequência de incidentes significativos ou de alterações significativas das operações ou dos riscos."}, {"id": "13.2.1", "section": "13. Segurança ambiental e física", "text": "Para efeitos do artigo 21.º, n.º 2, alínea e), da Diretiva (UE) 2022/2555, com base nos resultados da avaliação dos riscos efetuada nos termos do ponto 2.1., as entidades pertinentes previnem ou reduzem as consequências de eventos decorrentes de ameaças físicas e ambientais, tais como catástrofes naturais e outras ameaças intencionais ou não intencionais."}, {"id": "13.2.2", "section": "13. Segurança ambiental e física", "text": "Para o efeito, as entidades pertinentes devem, se for caso disso:\n(a) Conceber e aplicar medidas de proteção contra ameaças físicas e ambientais;\n(b) Determinar limiares de controlo mínimos e máximos para as ameaças físicas e ambientais;\n(c) Monitorizar os parâmetros ambientais e comunicar ao pessoal competente, a nível interno ou externo, eventos fora dos limiares de controlo mínimos e máximos a que se refere a alínea b)."}, {"id": "13.2.3", "section": "13. Segurança ambiental e física", "text": "As entidades pertinentes testam, analisam e, se for caso disso, atualizam as medidas de proteção contra ameaças físicas ou ambientais regularmente ou na sequência de incidentes significativos ou de alterações significativas das operações ou dos riscos."}, {"id": "13.3.1", "section": "13. Segurança ambiental e física", "text": "Para efeitos do artigo 21.º, n.º 2, alínea i), da Diretiva (UE) 2022/2555, as entidades pertinentes previnem e monitorizam o acesso físico não autorizado, os danos e as interferências nos seus sistemas de rede e informação."}, {"id": "13.3.2", "section": "13. Segurança ambiental e física", "text": "Para o efeito, as entidades pertinentes:\n(a) Com base na avaliação dos riscos efetuada nos termos do ponto 2.1, estabelecem e utilizam perímetros de segurança para proteger as zonas em que estão situados os sistemas de rede e informação e outros ativos conexos;\n(b) Protegem as zonas referidas na alínea a) através de controlos de entrada e pontos de acesso adequados;\n(c) Concebem e implementam a segurança física dos escritórios, salas e instalações;\n(d) Monitorizam continuamente o acesso físico não autorizado às suas instalações."}, {"id": "13.3.3", "section": "13. Segurança ambiental e física", "text": "As entidades pertinentes testam, analisam e, se for caso disso, atualizam as medidas de controlo do acesso físico regularmente ou na sequência de incidentes significativos ou de alterações significativas das operações ou dos riscos."}], "r2690_letters": {"1": ["a"], "2": ["a"], "3": ["b"], "4": ["c"], "5": ["d"], "6": ["e"], "7": ["f"], "8": ["g"], "9": ["h"], "10": ["i"], "11": ["i", "j"], "12": ["i"], "13": ["c", "e", "i"]}};

